export const users = pgTable("users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  email: varchar("email").unique(),
  firstName: varchar("first_name"),
  lastName: varchar("last_name"),
  profileImageUrl: varchar("profile_image_url"),
  passwordHash: varchar("password_hash"), // For username/password auth
  status: varchar("status").notNull().default("ACTIVE"), // ACTIVE, INVITED, DISABLED
  inviteToken: varchar("invite_token").unique(), // One-time token for invite acceptance
  inviteTokenExpiresAt: timestamp("invite_token_expires_at"), // Token expiry
  role: varchar("role").notNull().default("driver"), // See userRoles for all available roles
  roleSelectedAt: timestamp("role_selected_at"), // Timestamp when user explicitly chose their role
  orgId: varchar("org_id").references(() => organizations.id), // Organization this user belongs to
  isProvisioned: boolean("is_provisioned").default(false), // Has completed onboarding
  employeeId: varchar("employee_id"), // References employees.id if this user is an employee
  driverId: varchar("driver_id"), // References drivers.id if this user is a driver
  corporateAccessAdmin: boolean("corporate_access_admin").default(false),
  canGrantSensitiveDataAccess: boolean("can_grant_sensitive_data_access").default(false),
  canGrantExports: boolean("can_grant_exports").default(false),
  moduleAccess: jsonb("module_access").default({}),
  sensitiveFieldAccess: jsonb("sensitive_field_access").default({}),
  actionPermissions: jsonb("action_permissions").default({}),
  lastLoginAt: timestamp("last_login_at"),
  isRootSuperAdmin: boolean("is_root_super_admin").default(false).notNull(),
  forcePasswordReset: boolean("force_password_reset").default(false).notNull(),
  passwordSetAt: timestamp("password_set_at"),
  firstLoginCompletedAt: timestamp("first_login_completed_at"),
  mfaEnabled: boolean("mfa_enabled").default(false).notNull(),
  mfaRequired: boolean("mfa_required").default(false).notNull(),
  mfaPhoneNumber: varchar("mfa_phone_number"),
  mfaLastVerifiedAt: timestamp("mfa_last_verified_at"),
  mfaCodeHash: varchar("mfa_code_hash"),
  mfaCodeExpiresAt: timestamp("mfa_code_expires_at"),
  mfaAttemptCount: integer("mfa_attempt_count").default(0).notNull(),
  mfaResendCount: integer("mfa_resend_count").default(0).notNull(),
  mfaResendWindowStart: timestamp("mfa_resend_window_start"),
  mfaLockoutUntil: timestamp("mfa_lockout_until"),
  securityRiskScore: integer("security_risk_score").default(0).notNull(),
  securityRiskLevel: varchar("security_risk_level").default("LOW").notNull(),
  securityRiskLastUpdatedAt: timestamp("security_risk_last_updated_at"),
  securitySuspendedUntil: timestamp("security_suspended_until"),
  pendingActivation: boolean("pending_activation").default(false).notNull(),
  // ── Heymarket integration ──────────────────────────────────────────────
  heymarketMemberId: integer("heymarket_member_id"), // Heymarket member/creator ID for outbound 1-to-1 SMS identity
  // ── SSO Identity & Access ──────────────────────────────────────────────
  ssoSubjectId: varchar("sso_subject_id").unique(), // External SSO provider subject reference
  ssoRole: varchar("sso_role"), // High-level role for downstream apps: SUPER_ADMIN | ADMIN | MANAGER | DISPATCHER | DRIVER | READ_ONLY
  hasDriverHubAccess: boolean("has_driver_hub_access").default(true).notNull(),
  hasDriverConnectAccess: boolean("has_driver_connect_access").default(false).notNull(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Append-only audit trail for human identity changes, blocked clears, repairs,
// and integrity-scan findings. Identity fields must never be silently changed.
export const userIdentityAuditLog = pgTable("user_identity_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").references(() => users.id, { onDelete: "set null" }),
  userEmail: varchar("user_email"),
  field: varchar("field").notNull(),
  action: varchar("action").notNull(), // changed | clear_blocked | repaired | detected
  oldValue: text("old_value"),
  newValue: text("new_value"),
  actorUserId: varchar("actor_user_id").references(() => users.id, { onDelete: "set null" }),
  actorEmail: varchar("actor_email"),
  source: varchar("source").notNull(),
  reason: text("reason"),
  metadata: jsonb("metadata"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  userIdx: index("user_identity_audit_user_idx").on(table.userId),
  fieldIdx: index("user_identity_audit_field_idx").on(table.field),
  actionIdx: index("user_identity_audit_action_idx").on(table.action),
  createdAtIdx: index("user_identity_audit_created_at_idx").on(table.createdAt),
}));

export type UserIdentityAuditLog = typeof userIdentityAuditLog.$inferSelect;
export type InsertUserIdentityAuditLog = typeof userIdentityAuditLog.$inferInsert;

// Approved operational employment types shared by Drivers and Recruiting.
export const employmentTypeValues = ["Part-Time", "Full-Time", "On-Call"] as const;
export type EmploymentType = typeof employmentTypeValues[number];
export const employmentTypeOptions = employmentTypeValues.map((value) => ({
  value,
  label: value,
}));
export function isApprovedEmploymentType(value: unknown): value is EmploymentType {
  return typeof value === "string" && (employmentTypeValues as readonly string[]).includes(value);
}

// Driver profile information - comprehensive fields for Personal, Professional, Payment, and Statistics
// 
// COMPUTED FIELDS: The following fields are computed at the service/API layer, not stored in DB:
// - fullName: Derived from firstName + middleName + lastName
// - age: Calculated from dateOfBirth
// - timeOnPlatform: Calculated from hireDate (years/months/days)
// - daysSinceLastMove: Calculated from lastMoveDate
//
// SECURITY: ssnOrEin field must be encrypted before persistence using application-layer encryption.
// The ssnOrEinLast4 field stores only the last 4 digits for display purposes.
// API layer implements permission-based access control for viewing full SSN/EIN.
export const drivers = pgTable("drivers", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").references(() => users.id, { onDelete: 'set null' }),
  // Driver Identification
  driverNumber: varchar("driver_number"),
  // Personal Information (mapped to existing DB columns)
  phoneNumber: varchar("phone_number"),
  // ── SMS Readiness Fields ──────────────────────────────────────────────────
  mobilePhoneNormalized:   varchar("mobile_phone_normalized"),   // E.164 (+1XXXXXXXXXX)
  mobilePhoneIsValid:      boolean("mobile_phone_is_valid").default(false),
  smsEligible:             boolean("sms_eligible").default(false),
  smsInvalidReason:        varchar("sms_invalid_reason"),        // 'missing' | 'bad_format' | 'landline' | 'do_not_contact'
  lastPhoneValidationAt:   timestamp("last_phone_validation_at", { withTimezone: true }),
  smsOptInStatus:          varchar("sms_opt_in_status").default("unknown"), // 'unknown' | 'opted_in' | 'opted_out'
  smsOptInUpdatedAt:       timestamp("sms_opt_in_updated_at",   { withTimezone: true }),
  // ─────────────────────────────────────────────────────────────────────────
  address: text("address"),
  city: varchar("city"),
  state: varchar("state"),
  zipCode: varchar("zip_code"),
  dateOfBirth: date("date_of_birth"),
  licenseNumber: varchar("license_number"),
  licenseState: varchar("license_state"),
  licenseExpiration: date("license_expiration"),
  profilePhotoUrl: varchar("profile_photo_url"),
  // Emergency contacts
  emergencyContactName: varchar("emergency_contact_name"),
  emergencyContactRelationship: varchar("emergency_contact_relationship"),
  emergencyContactPhone: varchar("emergency_contact_phone"),
  emergencyContactEmail: varchar("emergency_contact_email"),
  // Professional Information (using existing DB columns where available)
  driverType: varchar("driver_type"),
  employmentType: varchar("employment_type"), // 'Full-Time' | 'Part-Time' | 'On-Call'
  driverClassification: varchar("driver_classification"), // 'Employee' or 'Independent Contractor'
  employeeId: varchar("employee_id"), // Only used when driverClassification = 'Employee'
  independentContractorId: varchar("independent_contractor_id"), // Only used when driverClassification = 'Independent Contractor'
  market: varchar("market"), // Driver's market location
  drivershiftCustomerId: varchar("drivershift_customer_id").references(() => customers.id, { onDelete: 'set null' }), // DriverShift customer link (single-select)
  drivershiftCustomerIds: text("drivershift_customer_ids").array(), // Multi-select for DriverDash/Hybrid
  icAgreementSigned: varchar("manual_transmission").default("N"), // Aliased to existing column
  icAgreementUrl: varchar("ic_agreement_url"),
  cdlCertified: varchar("can_drive_manual"), // Aliased to existing boolean column
  hazmatCertified: varchar("eligible_for_rehire"), // Aliased temporarily
  hireDate: date("hire_date"),
  // Termination/Contract Cancellation fields
  terminationDate: date("termination_date"), // For Employee classification
  contractCancelledDate: date("contract_cancelled_date"), // For Independent Contractor classification
  terminationReason: varchar("termination_reason", { length: 50 }), // 50 character limit
  terminationEligibleForRehire: varchar("termination_eligible_for_rehire"), // 'Yes' or 'No'
  reactivationDate: date("reactivation_date"), // Informational only — does NOT auto-change status
  terminationUpdatedBy: varchar("termination_updated_by").references(() => users.id), // Who made the entry
  terminationUpdatedAt: timestamp("termination_updated_at"), // When the entry was made
  statusChangedBy: varchar("status_changed_by").references(() => users.id),
  statusChangedAt: timestamp("status_changed_at"),
  previousStatus: varchar("previous_status"),
  inactiveDate: date("inactive_date"),
  inactiveReason: text("inactive_reason"),
  dateCertified: date("date_certified"),
  certifiedBy: varchar("certified_by", { length: 50 }),
  drugTestDate: date("drug_test_date"),
  backgroundCheckDate: date("background_check_date"),
  mvrDate: date("mvr_date"),
  mvrProgress: varchar("mvr_progress", { length: 50 }),
  mvrRequestSentDate: date("mvr_request_sent_date"),
  mvrProcessStartDate: date("mvr_process_start_date"),
  mvrCommunicationType: varchar("mvr_communication_type", { length: 50 }),
  mvrResult: varchar("mvr_result", { length: 50 }),
  mvrProgressUpdatedAt: timestamp("mvr_progress_updated_at"),
  // Payment Information (mapped to existing columns)
  basePayPerMile: decimal("driver_shift_pay_rate", { precision: 10, scale: 2 }), // Aliased (now Hourly Pay Rate)
  fuelSurchargeRate: decimal("driver_dash_pay_rate", { precision: 10, scale: 2 }), // Aliased
  paymentId: varchar("payment_id", { length: 12 }),
  openforceId: varchar("openforce_id"),
  ssnOrEinEncrypted: varchar("ssn_or_ein"), // Maps to existing column
  ssnOrEinLast4: varchar("ssn_or_ein_last4"),
  adpMarketplaceId: varchar("adp_marketplace_id"),
  lastPayDate: date("last_pay_date"),
  // When I Work Sync Fields (populated by WIW API sync)
  wiwUserId: varchar("wiw_user_id"),                 // FK to wiw_users.id (set after user sync + driver match)
  wiwEmail: varchar("wiw_email"),                    // WIW email address at time of last sync
  wiwWorkplaceId: varchar("wiw_workplace_id"),        // WIW workplace/account ID (integer stored as string)
  wiwSyncStatus: varchar("wiw_sync_status").default("unmatched"), // synced | unmatched | excluded | pending
  wiwLastSeenAt: timestamp("wiw_last_seen_at", { withTimezone: true }), // last sync run that matched this driver
  // When I Work Integration Fields (populated via API)
  hoursWtd: decimal("hours_wtd", { precision: 10, scale: 2 }), // Hours Week to Date
  hoursMtd: decimal("hours_mtd", { precision: 10, scale: 2 }), // Hours Month to Date
  hoursYtd: decimal("hours_ytd", { precision: 10, scale: 2 }), // Hours Year to Date
  lifetimeHours: decimal("lifetime_hours", { precision: 10, scale: 2 }), // Total lifetime hours
  averageHoursPerWeek: decimal("average_hours_per_week", { precision: 10, scale: 2 }), // Avg hours/week
  payLastWeek: decimal("pay_last_week", { precision: 10, scale: 2 }), // Pay last week
  payWtd: decimal("pay_wtd", { precision: 10, scale: 2 }), // Pay Week to Date (Estimate)
  payMtd: decimal("pay_mtd", { precision: 10, scale: 2 }), // Pay Month to Date
  payYtd: decimal("pay_ytd", { precision: 10, scale: 2 }), // Pay Year to Date
  lifetimePay: decimal("lifetime_pay", { precision: 10, scale: 2 }), // Total lifetime pay
  averagePayPerWeek: decimal("average_pay_per_week", { precision: 10, scale: 2 }), // Avg pay/week
  // Driver Statistics (mapped to existing columns)
  lifetimeMoveCount: integer("total_moves_completed").default(0),
  currentMonthMoveCount: integer("move_count_last_30_days").default(0),
  lastMonthMoveCount: integer("move_count_last_7_days").default(0),
  firstMoveDate: date("first_move_date"),
  lastMoveDate: date("last_move_date"),
  safetyScore: varchar("safety_score"),
  // Compliance & Profile fields
  recruiter: varchar("recruiter", { length: 50 }),
  directManager: varchar("direct_manager", { length: 100 }),
  shiftPayRate: decimal("shift_pay_rate", { precision: 8, scale: 2 }),
  networkPayRate: decimal("network_pay_rate", { precision: 10, scale: 2 }),
  network: varchar("network", { length: 50 }),
  gender: varchar("gender", { length: 8 }),
  // Approval Workflow - Manager/Advocate assignments
  directManagerId: varchar("direct_manager_id").references(() => employees.id, { onDelete: 'set null' }), // For Employee drivers
  driverAdvocateId: varchar("driver_advocate_id").references(() => employees.id, { onDelete: 'set null' }), // For Independent Contractor drivers
  status: varchar("status").default("active"), // 'active', 'inactive', 'suspended', 'archived'
  isDeleted: boolean("is_deleted").default(false),
  deletedAt: timestamp("deleted_at"),
  deletedByUserId: varchar("deleted_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  deletionReason: text("deletion_reason"),
  safetyState: varchar("safety_state").default("ACTIVE"), // 'ACTIVE', 'RESTRICTED', 'SUSPENDED', 'DISQUALIFIED' (INCREMENT 25B)
  lastAccessAt: timestamp("last_access_at"),
  needsUpdate: boolean("needs_update").default(false),
  needsUpdateReasons: text("needs_update_reasons").array(),
  needsUpdateFields: text("needs_update_fields").array(),
  needsUpdateSetAt: timestamp("needs_update_set_at"),
  needsUpdateSetBy: varchar("needs_update_set_by"),
  needsUpdateImportBatchId: varchar("needs_update_import_batch_id"),
  // Merge tracking — set when this record is retired as a duplicate
  mergedIntoId: varchar("merged_into_id"), // ID of the primary driver this was merged into
  mergedAt: timestamp("merged_at"),
  mergedById: varchar("merged_by_id").references(() => users.id, { onDelete: 'set null' }),
  mergeReason: text("merge_reason"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// ── Driver Communication Logs (Heymarket SMS + Email foundation) ──────────────
// Stores every outbound communication attempt (text or email) made to a driver.
// Status is 'pending_integration' until Heymarket is live; becomes 'sent'/'failed' after.
export const driverCommunicationLogs = pgTable("driver_communication_logs", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Context
  accountId:      varchar("account_id").references(() => customers.id, { onDelete: "set null" }),
  driverId:       varchar("driver_id").references(() => drivers.id, { onDelete: "set null" }),
  sentByUserId:   varchar("sent_by_user_id").references(() => users.id, { onDelete: "set null" }),
  // Channel + Provider
  channel:        varchar("channel").notNull(), // 'sms' | 'email'
  provider:       varchar("provider"),          // 'heymarket' | 'microsoft_graph' | 'resend'
  // Recipient
  recipientPhone: varchar("recipient_phone"),
  recipientEmail: varchar("recipient_email"),
  recipientName:  varchar("recipient_name"),
  // Message
  messageBody:    text("message_body"),
  subject:        varchar("subject"),           // email only
  // Delivery state
  status:         varchar("status").notNull().default("pending_integration"),
  // 'pending_integration' | 'queued' | 'sent' | 'failed'
  externalMessageId: varchar("external_message_id"), // Heymarket message ID once live
  // Future: link communication to a module context (shift, move, claim, etc.)
  contextModule:    varchar("context_module"),   // 'assigned_drivers' | 'scheduling' | 'dispatch' | 'claims'
  contextEntityId:  varchar("context_entity_id"),// shift/move/claim ID
  // Bulk-send grouping (all messages in a single "Text Selected" action share a bulk_send_id)
  bulkSendId:     varchar("bulk_send_id"),
  // Timing
  scheduledAt:    timestamp("scheduled_at", { withTimezone: true }),
  sentAt:         timestamp("sent_at", { withTimezone: true }),
  failedAt:       timestamp("failed_at", { withTimezone: true }),
  errorMessage:   text("error_message"),
  createdAt:      timestamp("created_at", { withTimezone: true }).defaultNow(),
});
export const insertDriverCommunicationLogSchema = createInsertSchema(driverCommunicationLogs).omit({ id: true, createdAt: true });
export type DriverCommunicationLog = typeof driverCommunicationLogs.$inferSelect;
export type InsertDriverCommunicationLog = z.infer<typeof insertDriverCommunicationLogSchema>;

// ── Driver Call Logs ────────────────────────────────────────────────────────
// Manual call logging — feeds the Notes & Communications timeline
export const driverCallLogs = pgTable("driver_call_logs", {
  id:              varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  driverId:        varchar("driver_id").references(() => drivers.id, { onDelete: "set null" }),
  accountId:       varchar("account_id"),
  loggedByUserId:  varchar("logged_by_user_id").references(() => users.id, { onDelete: "set null" }),
  callType:        varchar("call_type").notNull().default("outbound"),  // 'inbound' | 'outbound'
  durationMinutes: integer("duration_minutes"),
  outcome:         varchar("outcome"),  // 'connected' | 'no_answer' | 'voicemail' | 'busy' | 'other'
  notes:           text("notes"),
  callDate:        timestamp("call_date", { withTimezone: true }).defaultNow(),
  createdAt:       timestamp("created_at", { withTimezone: true }).defaultNow(),
});
export const insertDriverCallLogSchema = createInsertSchema(driverCallLogs).omit({ id: true, createdAt: true });
export type DriverCallLog = typeof driverCallLogs.$inferSelect;
export type InsertDriverCallLog = z.infer<typeof insertDriverCallLogSchema>;

// Pay records
export const payRecords = pgTable("pay_records", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  driverId: varchar("driver_id").notNull().references(() => drivers.id, { onDelete: 'cascade' }),
  payPeriodStart: date("pay_period_start").notNull(),
  payPeriodEnd: date("pay_period_end").notNull(),
  grossPay: decimal("gross_pay", { precision: 10, scale: 2 }).notNull(),
  deductions: decimal("deductions", { precision: 10, scale: 2 }).default("0.00"),
  netPay: decimal("net_pay", { precision: 10, scale: 2 }).notNull(),
  hoursWorked: decimal("hours_worked", { precision: 6, scale: 2 }),
  milesDelivered: decimal("miles_delivered", { precision: 10, scale: 2 }),
  bonuses: decimal("bonuses", { precision: 10, scale: 2 }).default("0.00"),
  paymentDate: date("payment_date"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Trip history
export const trips = pgTable("trips", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  moveNumber: varchar("move_number").notNull().unique(),
  driverId: varchar("driver_id").references(() => drivers.id, { onDelete: 'cascade' }), // Nullable for unassigned moves
  customerId: varchar("customer_id").references(() => customers.id, { onDelete: 'set null' }),
  tripDate: timestamp("trip_date").notNull(),
  origin: varchar("origin"),      // nullable — import-created trips may not have this
  destination: varchar("destination"), // nullable — import-created trips may not have this
  distance: decimal("distance", { precision: 10, scale: 2 }),
  duration: varchar("duration"),
  status: varchar("status").default("completed"), // 'completed', 'cancelled', 'in-progress'
  moveType: varchar("move_type"), // Canonical type: DriverShift or DriverDash
  vehicleType: varchar("vehicle_type"), // Vehicle used for the move
  billRate: decimal("bill_rate", { precision: 10, scale: 2 }), // Rate charged to customer
  payRate: decimal("pay_rate", { precision: 10, scale: 2 }), // Rate paid to driver
  grossProfit: decimal("gross_profit", { precision: 10, scale: 2 }), // billRate - payRate
  notes: text("notes"),
  // ── Import-sourced fields (Move Report / Data Imports pipeline) ────────────────
  externalMoveId:      varchar("external_move_id"),        // e.g., RedCap TripId
  sourceSystem:        varchar("source_system"),            // 'redcap', 'uber', …
  importBatchId:       varchar("import_batch_id"),          // FK data_import_batches.id
  moveMinutes:         integer("move_minutes"),
  moveHours:           decimal("move_hours", { precision: 10, scale: 4 }),
  customerCharges:     decimal("customer_charges", { precision: 10, scale: 2 }),  // Chg_Total
  driverPay:           decimal("driver_pay", { precision: 10, scale: 2 }),        // Pay_Total
  driverReturnCharges: decimal("driver_return_charges", { precision: 10, scale: 2 }), // RT_Chg_Total
  revenue:             decimal("revenue", { precision: 10, scale: 2 }),            // = customerCharges
  driverCost:          decimal("driver_cost", { precision: 10, scale: 2 }),        // = driverPay + driverReturnCharges
  grossMargin:         decimal("gross_margin", { precision: 10, scale: 4 }),       // grossProfit / revenue * 100
  // INCREMENT 25B: Eligibility snapshot at ingestion
  eligibilityStatus: varchar("eligibility_status"), // 'PASS', 'WARN', 'FAIL' - snapshot at ingest
  eligibilityReasons: text("eligibility_reasons").array(), // Array of reasons for non-PASS status
  eligibilityCheckedAt: timestamp("eligibility_checked_at", { withTimezone: true }), // When eligibility was evaluated
  eligibilityPolicyVersionId: varchar("eligibility_policy_version_id"), // Policy version used for evaluation
  marketId: varchar("market_id"), // Market for this move (for eligibility checks)
  zoneId: varchar("zone_id"), // Zone for this move (for eligibility checks)
  workType: varchar("work_type"), // Work type for eligibility (ON_DEMAND, SCHEDULED, MANUAL)
  executionMode: varchar("execution_mode"), // Execution mode (COMPANY_VEHICLE, DRIVER_VEHICLE, etc.)
  // Ingest metadata (INCREMENT 25B)
  ingestSource: varchar("ingest_source"), // 'CSV', 'SCHEDULED', 'MANUAL' - how the move was ingested
  ingestedAt: timestamp("ingested_at", { withTimezone: true }), // When the move was ingested
  ingestedBy: varchar("ingested_by"), // User ID or system ID that ingested the move
  // Move Offer System (DriverConnect API)
  assignmentState: varchar("assignment_state").default("UNASSIGNED"), // UNASSIGNED | OFFERED | ASSIGNED | REASSIGNING | CANCELLED
  executionState: varchar("execution_state").default("READY"), // READY | EN_ROUTE_PICKUP | AT_PICKUP | EN_ROUTE_DESTINATION | AT_DESTINATION | COMPLETED | CANCELLED
  offeredToDriverId: varchar("offered_to_driver_id").references(() => drivers.id, { onDelete: 'set null' }),
  offerExpiresAt: timestamp("offer_expires_at", { withTimezone: true }),
  offeredAt: timestamp("offered_at", { withTimezone: true }),
  offeredByUserId: varchar("offered_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  acceptedAt: timestamp("accepted_at", { withTimezone: true }),
  declinedAt: timestamp("declined_at", { withTimezone: true }),
  declineReasonCode: varchar("decline_reason_code"), // SCHEDULE_CONFLICT, TOO_FAR, PAY_TOO_LOW, VEHICLE_ISSUE, OTHER
  declineNote: text("decline_note"),
  // Location coordinates for origin/destination
  originLat: decimal("origin_lat", { precision: 10, scale: 7 }),
  originLng: decimal("origin_lng", { precision: 10, scale: 7 }),
  destinationLat: decimal("destination_lat", { precision: 10, scale: 7 }),
  destinationLng: decimal("destination_lng", { precision: 10, scale: 7 }),
  // Move execution details
  estimatedMinutes: integer("estimated_minutes"),
  returnToOriginRequired: boolean("return_to_origin_required").default(false),
  waitTimeRulesJson: text("wait_time_rules_json"), // JSON for { pickup_minutes, drop_minutes, return_minutes }
  customerInstructions: text("customer_instructions"),
  // Pay estimate (informational only)
  payEstimateCurrency: varchar("pay_estimate_currency").default("USD"),
  payEstimateTotal: decimal("pay_estimate_total", { precision: 10, scale: 2 }),
  payEstimateRateBasis: varchar("pay_estimate_rate_basis"), // HOURLY | PER_JOB
  payEstimateBreakdownJson: text("pay_estimate_breakdown_json"), // JSON for breakdown { base, wait_time, etc }
  // Dispatch priority
  priority: varchar("priority").default("medium"), // low | medium | high | urgent
  // Photo Compliance Status (computed/cached for dashboard performance)
  pickupPhotoComplianceStatus: varchar("pickup_photo_compliance_status").default("not_started"), // not_started | partial | complete
  dropoffPhotoComplianceStatus: varchar("dropoff_photo_compliance_status").default("not_started"), // not_started | partial | complete
  // Execution Audit References (Ops Console traceability - INCREMENT: Store Execution Audit References)
  executionAuditId: varchar("execution_audit_id"), // Reference to Ops Console audit - NOT raw logs, just pointer
  slaBreachIndicator: boolean("sla_breach_indicator"), // High-level SLA breach flag from Ops Console
  blockerSummary: text("blocker_summary"), // High-level blocker description (not raw audit data)
  executionAuditReceivedAt: timestamp("execution_audit_received_at", { withTimezone: true }), // When audit reference was stored
  isDeleted: boolean("is_deleted").notNull().default(false),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
  // ── DriverConnect contract structured fields (added for POST /bookings v2) ──
  customerFirstName: varchar("customer_first_name"),
  customerLastName:  varchar("customer_last_name"),
  customerPhone:     varchar("customer_phone"),
  customerEmail:     varchar("customer_email"),
  vehicleYear:  integer("vehicle_year"),
  vehicleMake:  varchar("vehicle_make"),
  vehicleModel: varchar("vehicle_model"),
  vehicleVin:   varchar("vehicle_vin"),
  vehicleColor: varchar("vehicle_color"),
  originName:       varchar("origin_name"),
  originAddress1:   varchar("origin_address1"),
  originCity:       varchar("origin_city"),
  originState:      varchar("origin_state"),
  originPostalCode: varchar("origin_postal_code"),
  destinationName:        varchar("destination_name"),
  destinationAddress1:    varchar("destination_address1"),
  destinationCity:        varchar("destination_city"),
  destinationState:       varchar("destination_state"),
  destinationPostalCode:  varchar("destination_postal_code"),
  destinationLocationId:  varchar("destination_location_id"),
});

