// Expenses submitted by drivers/employees
// Approval stages for expense workflow
export const EXPENSE_APPROVAL_STAGES = ["manager", "coo", "executive", "completed"] as const;
export type ExpenseApprovalStage = typeof EXPENSE_APPROVAL_STAGES[number];

export const expenses = pgTable("expenses", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  expenseType: varchar("expense_type").notNull().default("driver"), // 'driver' or 'employee'
  submittedBy: varchar("submitted_by").notNull().references(() => users.id),
  driverId: varchar("driver_id").references(() => drivers.id),
  employeeId: varchar("employee_id").references(() => employees.id),
  tripId: varchar("trip_id").references(() => trips.id), // Link to move/trip for driver expenses
  expenseDate: date("expense_date").notNull(),
  category: varchar("category").notNull(), // Driver: fuel/tolls/oil/parking/maintenance/other, Employee: travel/meals/lodging/office_supplies/equipment/training/mileage/other
  amount: decimal("amount", { precision: 10, scale: 2 }).notNull(),
  description: text("description").notNull(),
  receiptUrl: varchar("receipt_url"),
  status: varchar("status").default("draft"), // 'draft', 'pending', 'approved', 'rejected', 'reimbursed'
  associatedCustomer: varchar("associated_customer"), // Customer associated with this expense
  vendorId: varchar("vendor_id").references(() => vendors.id, { onDelete: 'set null' }),
  cardType: varchar("card_type"), // 'Company' or 'Personal'
  // Multi-level approval workflow fields
  currentApprovalStage: varchar("current_approval_stage").default("manager"), // 'manager', 'coo', 'executive', 'completed'
  approvalLevel: integer("approval_level").default(1), // Current level: 1, 2, 3
  totalApprovalLevels: integer("total_approval_levels").default(2), // Total levels needed
  // Legacy single approver (kept for backwards compatibility)
  approvedBy: varchar("approved_by").references(() => users.id),
  approvalDate: timestamp("approval_date"),
  // Invoice linkage for driver expenses after COO approval
  invoiceId: varchar("invoice_id").references(() => invoices.id, { onDelete: 'set null' }),
  reimbursementDate: date("reimbursement_date"),
  notes: text("notes"),
  costCenter: varchar("cost_center"), // For accounting/billing separation
  attendees: jsonb("attendees"), // For Meals - Entertainment: array of {name, title, businessName}
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Expense approval tracking - logs each approval action
export const expenseApprovals = pgTable("expense_approvals", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  expenseId: varchar("expense_id").notNull().references(() => expenses.id, { onDelete: 'cascade' }),
  stage: varchar("stage").notNull(), // 'manager', 'coo', 'executive'
  level: integer("level").notNull(), // 1, 2, 3
  approverEmployeeId: varchar("approver_employee_id").references(() => employees.id), // Employee who should approve
  approverUserId: varchar("approver_user_id").references(() => users.id), // User who should approve
  status: varchar("status").default("pending"), // 'pending', 'approved', 'rejected'
  decidedAt: timestamp("decided_at"),
  decidedByUserId: varchar("decided_by_user_id").references(() => users.id), // User who made the decision
  notes: text("notes"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Billing Entities - operating entities with separate branding, numbering, and remit-to addresses
export const billingEntities = pgTable("billing_entities", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Entity identification
  entityCode: varchar("entity_code").notNull().unique(), // Short code e.g. "HQ", "WEST", "EAST"
  legalName: varchar("legal_name").notNull(), // Official legal name
  dbaName: varchar("dba_name"), // "Doing Business As" name (optional)
  taxId: varchar("tax_id"), // EIN or tax identification number (encrypted)
  // Contact information
  phone: varchar("phone"),
  email: varchar("email"),
  website: varchar("website"),
  // Physical address
  addressLine1: varchar("address_line_1"),
  addressLine2: varchar("address_line_2"),
  city: varchar("city"),
  state: varchar("state"),
  postalCode: varchar("postal_code"),
  country: varchar("country").default("US"),
  // Remit-to address (if different from physical)
  remitAddressLine1: varchar("remit_address_line_1"),
  remitAddressLine2: varchar("remit_address_line_2"),
  remitCity: varchar("remit_city"),
  remitState: varchar("remit_state"),
  remitPostalCode: varchar("remit_postal_code"),
  remitCountry: varchar("remit_country").default("US"),
  // Branding assets
  logoUrl: varchar("logo_url"), // URL to entity logo in object storage
  primaryColor: varchar("primary_color").default("#FF6B35"), // Hex color for branding
  secondaryColor: varchar("secondary_color"), // Optional secondary color
  // Invoice numbering settings
  invoicePrefix: varchar("invoice_prefix").default("INV"), // Prefix for invoice numbers
  invoiceNextNumber: integer("invoice_next_number").default(1), // Next sequence number
  invoiceNumberFormat: varchar("invoice_number_format").default("{PREFIX}-{YEAR}-{SEQ:5}"), // Format template
  invoicePadding: integer("invoice_padding").default(5), // Padding for sequence numbers (e.g., 5 = 00001)
  // Invoice template settings
  invoiceTemplateId: varchar("invoice_template_id"), // Optional template identifier
  defaultTermsText: text("default_terms_text"), // Default payment terms/conditions text
  footerNotes: text("footer_notes"), // Optional footer notes for invoices
  remittanceInstructions: text("remittance_instructions"), // Payment/remit-to instructions
  // Status and defaults
  isActive: boolean("is_active").default(true),
  isDefault: boolean("is_default").default(false), // Default entity for new customers
  // Audit trail
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
  createdBy: varchar("created_by").references(() => users.id),
  updatedBy: varchar("updated_by").references(() => users.id),
});

// Billing Locations - physical operating locations within an entity
export const billingLocations = pgTable("billing_locations", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Entity relationship
  billingEntityId: varchar("billing_entity_id").notNull().references(() => billingEntities.id),
  // Location identification
  locationCode: varchar("location_code").notNull(), // Short code e.g. "LA-01", "NYC-MAIN"
  locationName: varchar("location_name").notNull(), // Display name
  // Contact information
  phone: varchar("phone"),
  email: varchar("email"),
  // Physical address
  addressLine1: varchar("address_line_1"),
  addressLine2: varchar("address_line_2"),
  city: varchar("city"),
  state: varchar("state"),
  postalCode: varchar("postal_code"),
  country: varchar("country").default("US"),
  // Operating details
  timezone: varchar("timezone").default("America/Chicago"),
  // Status
  isActive: boolean("is_active").default(true),
  // Audit trail
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
  createdBy: varchar("created_by").references(() => users.id),
  updatedBy: varchar("updated_by").references(() => users.id),
});

// Billing Entity Audit Log - track entity assignments and changes
export const billingEntityAuditLog = pgTable("billing_entity_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Entity reference
  billingEntityId: varchar("billing_entity_id").references(() => billingEntities.id),
  // Action details
  action: varchar("action").notNull(), // 'created', 'updated', 'customer_assigned', 'customer_unassigned', 'invoice_created'
  targetType: varchar("target_type"), // 'customer', 'invoice', 'location', 'entity'
  targetId: varchar("target_id"), // ID of the affected record
  // Change details
  previousValues: jsonb("previous_values"),
  newValues: jsonb("new_values"),
  // Audit info
  performedBy: varchar("performed_by").references(() => users.id),
  performedAt: timestamp("performed_at").defaultNow(),
  ipAddress: varchar("ip_address"),
  notes: text("notes"),
});


// User Invoicing Permissions - Custom per-user permissions beyond role defaults
export const userInvoicingPermissions = pgTable("user_invoicing_permissions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  permission: varchar("permission").notNull(), // See INVOICING_PERMISSIONS in invoicingPermissions.ts
  grantedBy: varchar("granted_by").references(() => users.id),
  grantedAt: timestamp("granted_at").defaultNow(),
  expiresAt: timestamp("expires_at"), // Optional expiration for temporary permissions
  notes: text("notes"),
});

// MFA/SSO Settings - Enterprise authentication configuration
export const mfaSsoSettings = pgTable("mfa_sso_settings", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orgId: varchar("org_id").references(() => organizations.id),
  mfaEnabled: boolean("mfa_enabled").default(false),
  mfaRequiredForActions: text("mfa_required_for_actions").array(),
  ssoProvider: varchar("sso_provider"), // 'okta' | 'azure_ad' | 'google' | null
  ssoEnforced: boolean("sso_enforced").default(false),
  ssoConfig: jsonb("sso_config"), // Provider-specific configuration
  sessionTimeoutMinutes: integer("session_timeout_minutes").default(60),
  requireReauthForSensitiveActions: boolean("require_reauth_sensitive").default(false),
  updatedBy: varchar("updated_by").references(() => users.id),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Invoicing Action Audit Log - Comprehensive audit trail for all invoicing actions
export const invoicingActionAuditLog = pgTable("invoicing_action_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  action: varchar("action").notNull(), // 'invoice:create_draft', 'invoice:send', etc.
  resourceType: varchar("resource_type").notNull(), // 'invoice', 'payment', 'billing_entity', etc.
  resourceId: varchar("resource_id"),
  userId: varchar("user_id").notNull().references(() => users.id),
  userEmail: varchar("user_email"),
  userRole: varchar("user_role"),
  permissionUsed: varchar("permission_used"),
  success: boolean("success").default(true),
  failureReason: text("failure_reason"),
  previousValues: jsonb("previous_values"),
  newValues: jsonb("new_values"),
  metadata: jsonb("metadata"), // Additional context
  ipAddress: varchar("ip_address"),
  userAgent: varchar("user_agent"),
  performedAt: timestamp("performed_at").defaultNow(),
});

// Invoices for customer billing
export const invoices = pgTable("invoices", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceNumber: varchar("invoice_number").notNull().unique(),
  customerId: varchar("customer_id").references(() => customers.id),
  customerName: varchar("customer_name").notNull(),
  invoiceDate: date("invoice_date").notNull(),
  dueDate: date("due_date").notNull(),
  // Billing entity and location (multi-entity support)
  billingEntityId: varchar("billing_entity_id").references(() => billingEntities.id),
  locationId: varchar("location_id").references(() => billingLocations.id),
  // Billing period (for time-based billing)
  billingPeriodStart: date("billing_period_start"),
  billingPeriodEnd: date("billing_period_end"),
  // Payment terms
  paymentTerms: varchar("payment_terms").default("net_30"),
  // Amounts
  subtotalAmount: decimal("subtotal_amount", { precision: 12, scale: 2 }).default("0.00"),
  taxAmount: decimal("tax_amount", { precision: 12, scale: 2 }).default("0.00"),
  feesAmount: decimal("fees_amount", { precision: 12, scale: 2 }), // Optional fees
  totalAmount: decimal("total_amount", { precision: 10, scale: 2 }).notNull(),
  paidAmount: decimal("paid_amount", { precision: 10, scale: 2 }).default("0.00"),
  creditApplied: decimal("credit_applied", { precision: 12, scale: 2 }).default("0.00"),
  balanceDue: decimal("balance_due", { precision: 12, scale: 2 }),
  currency: varchar("currency", { length: 3 }).default("USD"),
  // Status and workflow
  status: varchar("status").default("draft"), // See INVOICE_STATUSES in invoicing section
  // Reference fields
  poNumber: varchar("po_number"),
  referenceNumber: varchar("reference_number"),
  // Customer memo and internal notes
  customerMemo: text("customer_memo"), // Shown on invoice
  internalNotes: text("internal_notes"), // Hidden from customer
  notes: text("notes"), // Legacy field kept for compatibility
  // Delivery tracking
  sentAt: timestamp("sent_at"),
  sentBy: varchar("sent_by").references(() => users.id),
  sentToEmails: jsonb("sent_to_emails"),
  lastSentAt: timestamp("last_sent_at"),
  viewedAt: timestamp("viewed_at"), // First time customer viewed the invoice
  viewCount: integer("view_count").default(0), // Number of times viewed
  // Payment link
  paymentLinkUrl: varchar("payment_link_url"),
  stripePaymentLinkId: varchar("stripe_payment_link_id"),
  paymentAccessToken: varchar("payment_access_token").unique(), // Token for public invoice access
  paymentLinkExpiresAt: timestamp("payment_link_expires_at", { withTimezone: true }), // When the payment link expires (default 90 days)
  paymentLinkExpirationDays: integer("payment_link_expiration_days").default(90), // Configurable expiration window
  // PDF generation
  pdfUrl: varchar("pdf_url"),
  pdfGeneratedAt: timestamp("pdf_generated_at"),
  // Dispute tracking
  isDisputed: boolean("is_disputed").default(false),
  disputedAmount: decimal("disputed_amount", { precision: 12, scale: 2 }),
  disputedReasonCategory: varchar("disputed_reason_category"), // 'pricing', 'service', 'damage', 'duplicate', 'other'
  disputedNotes: text("disputed_notes"),
  disputedCreatedBy: varchar("disputed_created_by").references(() => users.id),
  disputedCreatedAt: timestamp("disputed_created_at"),
  disputeResolvedAt: timestamp("dispute_resolved_at"),
  priorStatusBeforeDispute: varchar("prior_status_before_dispute"), // Store status before dispute for restoration
  // QuickBooks integration
  qbInvoiceId: varchar("qb_invoice_id"),
  qbSyncStatus: varchar("qb_sync_status").default("not_queued"),
  qbSyncError: text("qb_sync_error"),
  qbSyncedAt: timestamp("qb_synced_at"),
  // Audit trail
  createdBy: varchar("created_by").notNull().references(() => users.id),
  approvedBy: varchar("approved_by").references(() => users.id),
  approvedAt: timestamp("approved_at"),
  voidedBy: varchar("voided_by").references(() => users.id),
  voidedAt: timestamp("voided_at"),
  voidReason: text("void_reason"),
  // Approval workflow (separate from invoice status)
  approvalWorkflowState: varchar("approval_workflow_state").default("draft"), // 'draft', 'pending_approval', 'approved', 'rejected'
  submittedForApprovalBy: varchar("submitted_for_approval_by").references(() => users.id),
  submittedForApprovalAt: timestamp("submitted_for_approval_at"),
  rejectedBy: varchar("rejected_by").references(() => users.id),
  rejectedAt: timestamp("rejected_at"),
  rejectionReason: varchar("rejection_reason"), // Category: 'pricing_error', 'missing_info', 'incorrect_customer', 'duplicate', 'other'
  rejectionComment: text("rejection_comment"),
  // Late fee tracking
  lateFeeAppliedAt: timestamp("late_fee_applied_at"), // When late fee was applied (null = not applied)
  lateFeeAmount: decimal("late_fee_amount", { precision: 12, scale: 2 }), // Amount of late fee applied
  lateFeeReversedAt: timestamp("late_fee_reversed_at"), // When late fee was reversed (if applicable)
  lateFeeReversedBy: varchar("late_fee_reversed_by").references(() => users.id),
  lateFeeReversalReason: text("late_fee_reversal_reason"),
  // Write-off tracking
  writtenOffAmount: decimal("written_off_amount", { precision: 12, scale: 2 }).default("0.00"),
  writtenOffBy: varchar("written_off_by").references(() => users.id),
  writtenOffAt: timestamp("written_off_at"),
  writeOffReason: varchar("write_off_reason"),
  writeOffNotes: text("write_off_notes"),
  // Invoice number assignment (assign on send, not on draft)
  invoiceNumberFinalized: boolean("invoice_number_finalized").default(false), // True when number assigned on send
  invoiceNumberFinalizedAt: timestamp("invoice_number_finalized_at"), // When number was assigned
  draftSequence: integer("draft_sequence"), // Internal draft sequence for display only
  // Template settings applied from entity
  termsText: text("terms_text"), // Payment terms/conditions text applied from entity
  footerNotes: text("footer_notes"), // Footer notes applied from entity
  remittanceInstructions: text("remittance_instructions"), // Remit-to instructions applied from entity
  versionNumber: integer("version_number").default(1).notNull(),
  originalInvoiceId: varchar("original_invoice_id"),
  previousVersionId: varchar("previous_version_id"),
  isCurrentVersion: boolean("is_current_version").default(true).notNull(),
  revisionReason: text("revision_reason"),
  revisionType: varchar("revision_type"), // 'standard', 'credit_reissue', 'finance_approved'
  financeApprovalRequired: boolean("finance_approval_required").default(false),
  sourceReferenceId: varchar("source_reference_id"),
  financeApprovalStatus: varchar("finance_approval_status"), // 'pending', 'approved', 'rejected'
  financeApprovedBy: varchar("finance_approved_by").references(() => users.id),
  financeApprovedAt: timestamp("finance_approved_at"),
  serviceCompletionDate: date("service_completion_date"),
  isConsolidated: boolean("is_consolidated").default(false),
  consolidationType: varchar("consolidation_type"), // 'charges', 'drafts'
  consolidatedIntoId: varchar("consolidated_into_id"), // For source invoices: points to the consolidated invoice
  slaStatus: varchar("sla_status").default("ok"),
  escalationRequired: boolean("escalation_required").default(false),
  escalationRequiredAt: timestamp("escalation_required_at"),
  collectionsOwnerId: varchar("collections_owner_id").references(() => users.id),
  collectionsAssignedAt: timestamp("collections_assigned_at"),
  remindersSentCount: integer("reminders_sent_count").default(0),
  tenantId: varchar("tenant_id").references(() => organizations.id, { onDelete: "set null" }),
  updatedBy: varchar("updated_by").references(() => users.id),
  isDeleted: boolean("is_deleted").notNull().default(false),
  deletedAt: timestamp("deleted_at"),
  deletedByUserId: varchar("deleted_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  // Financial Record Locking (auto-locked on 'paid' status; override requires Owner)
  isLocked: boolean("is_locked").notNull().default(false),
  lockedAt: timestamp("locked_at"),
  lockedBy: varchar("locked_by").references(() => users.id),
  lockSource: varchar("lock_source"), // 'auto_paid', 'manual', 'deposit_reconciled'
  lockOverriddenAt: timestamp("lock_overridden_at"),
  lockOverriddenBy: varchar("lock_overridden_by").references(() => users.id),
  lockOverrideReason: text("lock_override_reason"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Invoice status history - tracks all status changes with timestamps
export const invoiceStatusHistory = pgTable("invoice_status_history", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  previousStatus: varchar("previous_status"),
  newStatus: varchar("new_status").notNull(),
  changedBy: varchar("changed_by").references(() => users.id),
  changedAt: timestamp("changed_at").defaultNow(),
  reason: text("reason"), // Optional reason for status change
  metadata: jsonb("metadata"), // Additional context (e.g., payment details)
});

// Invoice audit log - tracks all changes to invoices
export const invoiceAuditLog = pgTable("invoice_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  action: varchar("action").notNull(), // 'created', 'updated', 'sent', 'voided', 'payment_applied', etc.
  performedBy: varchar("performed_by").references(() => users.id),
  performedAt: timestamp("performed_at").defaultNow(),
  previousValues: jsonb("previous_values"), // Snapshot before change
  newValues: jsonb("new_values"), // Snapshot after change
  ipAddress: varchar("ip_address"),
  userAgent: text("user_agent"),
  notes: text("notes"),
});

// Invoice approval actions - tracks all approval workflow actions
export const invoiceApprovalActions = pgTable("invoice_approval_actions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  action: varchar("action").notNull(), // 'submitted_for_approval', 'approved', 'rejected', 'returned_to_draft'
  previousState: varchar("previous_state"), // Previous workflow state
  newState: varchar("new_state").notNull(), // New workflow state
  performedBy: varchar("performed_by").notNull().references(() => users.id),
  performedAt: timestamp("performed_at").defaultNow(),
  rejectionReason: varchar("rejection_reason"), // Only for rejections
  rejectionComment: text("rejection_comment"), // Only for rejections
  notes: text("notes"), // Additional context
});

// Invoice delivery history - tracks email deliveries and views
export const invoiceDeliveryHistory = pgTable("invoice_delivery_history", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  eventType: varchar("event_type").notNull(), // 'sent', 'resent', 'viewed', 'payment_started', 'payment_completed'
  recipientEmail: varchar("recipient_email"),
  sentBy: varchar("sent_by").references(() => users.id), // User who sent/resent (null for customer-initiated events)
  ipAddress: varchar("ip_address"),
  userAgent: text("user_agent"),
  metadata: jsonb("metadata"), // Additional event details
  createdAt: timestamp("created_at").defaultNow(),
});

// Invoice consolidation sources - links consolidated invoice to its sources
export const invoiceConsolidationSources = pgTable("invoice_consolidation_sources", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  consolidatedInvoiceId: varchar("consolidated_invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  sourceType: varchar("source_type").notNull(), // 'invoice', 'charge'
  sourceInvoiceId: varchar("source_invoice_id").references(() => invoices.id),
  sourceChargeId: varchar("source_charge_id"),
  sourceAmount: decimal("source_amount", { precision: 12, scale: 2 }).notNull(),
  sourceDescription: text("source_description"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Invoice Saved Views - user-defined and admin-shareable filter/search views
export const invoiceSavedViewTypeEnum = pgEnum("invoice_saved_view_type", [
  "private",
  "shared",
  "system",
]);

export const invoiceSavedViews = pgTable("invoice_saved_views", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name", { length: 100 }).notNull(),
  description: varchar("description", { length: 500 }),
  type: invoiceSavedViewTypeEnum("type").notNull().default("private"),
  icon: varchar("icon", { length: 50 }),
  color: varchar("color", { length: 20 }),
  filters: jsonb("filters").notNull().$type<{
    searchQuery?: string;
    statuses?: string[];
    amountMin?: number;
    amountMax?: number;
    dateRange?: {
      field: string;
      start?: string;
      end?: string;
    };
    agingBucket?: string;
    billingEntityId?: string;
    collectionsTier?: string;
    customerId?: string;
    includeConsolidated?: boolean;
  }>(),
  sortBy: varchar("sort_by", { length: 50 }).default("createdAt"),
  sortOrder: varchar("sort_order", { length: 10 }).default("desc"),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  displayOrder: integer("display_order").default(0),
  lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
  usageCount: integer("usage_count").default(0),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  isActive: boolean("is_active").default(true),
}, (table) => ({
  typeIdx: index("invoice_saved_views_type_idx").on(table.type),
  createdByIdx: index("invoice_saved_views_created_by_idx").on(table.createdBy),
  isActiveIdx: index("invoice_saved_views_is_active_idx").on(table.isActive),
}));

export const idempotencyKeys = pgTable("idempotency_keys", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  scope: varchar("scope", { length: 100 }).notNull(),
  key: varchar("key", { length: 255 }).notNull(),
  requestHash: varchar("request_hash", { length: 64 }),
  status: varchar("status", { length: 20 }).notNull().default("processing"),
  responseStatus: integer("response_status"),
  responseBody: jsonb("response_body"),
  entityType: varchar("entity_type", { length: 50 }),
  entityId: varchar("entity_id"),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  scopeKeyIdx: uniqueIndex("idempotency_keys_scope_key_idx").on(table.scope, table.key),
  expiresAtIdx: index("idempotency_keys_expires_at_idx").on(table.expiresAt),
}));

export const resilienceLog = pgTable("resilience_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  context: varchar("context", { length: 100 }).notNull(),
  entityType: varchar("entity_type", { length: 50 }).notNull(),
  entityId: varchar("entity_id"),
  action: varchar("action", { length: 100 }).notNull(),
  status: varchar("status", { length: 20 }).notNull(),
  idempotencyKey: varchar("idempotency_key", { length: 255 }),
  errorMessage: text("error_message"),
  errorCode: varchar("error_code", { length: 50 }),
  retryCount: integer("retry_count").default(0),
  metadata: jsonb("metadata"),
  resolvedAt: timestamp("resolved_at", { withTimezone: true }),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  contextIdx: index("resilience_log_context_idx").on(table.context),
  entityIdx: index("resilience_log_entity_idx").on(table.entityType, table.entityId),
  statusIdx: index("resilience_log_status_idx").on(table.status),
  createdAtIdx: index("resilience_log_created_at_idx").on(table.createdAt),
}));

export const reconciliationRuns = pgTable("reconciliation_runs", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  runDate: timestamp("run_date", { withTimezone: true }).notNull().defaultNow(),
  status: varchar("status", { length: 20 }).notNull().default("completed"),
  totalOutstandingCalc: decimal("total_outstanding_calc", { precision: 14, scale: 2 }),
  totalOutstandingDashboard: decimal("total_outstanding_dashboard", { precision: 14, scale: 2 }),
  totalPaymentsApplied: decimal("total_payments_applied", { precision: 14, scale: 2 }),
  totalPaymentsLedger: decimal("total_payments_ledger", { precision: 14, scale: 2 }),
  depositBatchesBalanced: boolean("deposit_batches_balanced").default(true),
  discrepanciesFound: integer("discrepancies_found").default(0),
  discrepancyDetails: jsonb("discrepancy_details"),
  executionTimeMs: integer("execution_time_ms"),
  triggeredBy: varchar("triggered_by").default("scheduler"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const insertReconciliationRunSchema = createInsertSchema(reconciliationRuns).omit({ id: true, createdAt: true });
export type InsertReconciliationRun = z.infer<typeof insertReconciliationRunSchema>;
export type ReconciliationRun = typeof reconciliationRuns.$inferSelect;

// Line item category enum for reporting and accounting mapping
export const lineItemCategoryEnum = pgEnum("line_item_category", [
  "service",
  "mileage", 
  "fee",
  "surcharge",
  "late_fee",
  "bad_debt",
  "other"
]);

// Invoice line items
export const invoiceLineItems = pgTable("invoice_line_items", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  // Line details
  lineNumber: integer("line_number"),
  lineItemType: varchar("line_item_type").default("service"), // 'service', 'late_fee', 'credit', 'adjustment', 'discount'
  category: lineItemCategoryEnum("category").default("service").notNull(), // Category for reporting/accounting
  serviceType: varchar("service_type"), // 'hourly_labor', 'expense_passthrough', 'flat_rate', 'mileage', 'other'
  description: varchar("description").notNull(),
  // Amounts
  quantity: decimal("quantity", { precision: 10, scale: 4 }).notNull(),
  unitPrice: decimal("unit_price", { precision: 10, scale: 4 }).notNull(),
  totalPrice: decimal("total_price", { precision: 12, scale: 2 }).notNull(),
  // Tax handling
  isTaxable: boolean("is_taxable").default(false),
  taxRate: decimal("tax_rate", { precision: 5, scale: 4 }),
  taxAmount: decimal("tax_amount", { precision: 12, scale: 2 }),
  // Source tracking (links to original charge)
  chargeId: varchar("charge_id"), // Reference to billable_charges.id
  sourceType: varchar("source_type"), // 'timesheet', 'expense', 'trip', 'manual', 'rideshare_aggregate'
  sourceId: varchar("source_id"),   // e.g. rideshare_billing_aggregates.id
  sourceRecordType: varchar("source_record_type"), // 'rideshare_billing_aggregate' | 'billable_charge' | etc.
  // Service coding
  serviceCode: varchar("service_code"), // Internal service code, e.g. 'DRIVERRETURN_RIDESHARE'
  // Billing period (for aggregate / weekly lines)
  billingPeriodStart: date("billing_period_start"),
  billingPeriodEnd:   date("billing_period_end"),
  // QuickBooks mapping
  qbItemId: varchar("qb_item_id"),
  qbClassName: varchar("qb_class_name"),
  qbLocationName: varchar("qb_location_name"),
  // Reference fields
  dateOfService: date("date_of_service"),
  jobReference: varchar("job_reference"),
  notes: text("notes"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Invoice Line Candidates - draft billable items from execution events (Ticket 19)
export const invoiceLineCandidates = pgTable("invoice_line_candidates", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").references(() => invoices.id, { onDelete: 'set null' }),
  customerId: varchar("customer_id").notNull().references(() => customers.id),
  moveId: varchar("move_id"),
  driverId: varchar("driver_id"),
  // serviceType deprecated — productId is the forward path for this table
  serviceType: varchar("service_type"),
  description: varchar("description"),
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  currency: varchar("currency").default("USD"),
  status: varchar("status").default("draft").notNull(),
  supportingEventIds: jsonb("supporting_event_ids").default([]),
  proofRefs: jsonb("proof_refs").default([]),
  rateCardId: varchar("rate_card_id"),
  baseRate: decimal("base_rate", { precision: 12, scale: 2 }),
  addOns: jsonb("add_ons").default([]),
  approvedBy: varchar("approved_by").references(() => users.id),
  approvedAt: timestamp("approved_at"),
  issuedAt: timestamp("issued_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Invoice Adjustments - offset adjustments that never modify original candidate (Ticket 19)
export const invoiceAdjustments = pgTable("invoice_adjustments", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").references(() => invoices.id, { onDelete: 'cascade' }),
  candidateId: varchar("candidate_id").references(() => invoiceLineCandidates.id, { onDelete: 'cascade' }),
  moveId: varchar("move_id"),
  adjustmentType: varchar("adjustment_type").notNull(),
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  reason: text("reason").notNull(),
  createdBy: varchar("created_by").notNull().references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
});

// Customers table - stored in database as "customers"
// Note: UI uses "Accounts" terminology, but database retains "customers" naming for stability
export const CUSTOMER_STATUS_VALUES = [
  "Onboarding",
  "Pending",
  "Active",
  "Inactive",
  "Suspended",
  "Cancelled",
] as const;
export type CustomerStatus = typeof CUSTOMER_STATUS_VALUES[number];

export const customers = pgTable("customers", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Company Details
  customerName: varchar("customer_name").notNull(),
  customerNumber: varchar("customer_number"),
  dealerId: varchar("dealer_id"),
  status: varchar("status").default("Active"),
  customerType: varchar("customer_type"),
  customerLegalName: varchar("customer_legal_name"),
  customerGroup: varchar("customer_group"),
  customerAddress: text("customer_address"),
  customerCity: varchar("customer_city"),
  customerState: varchar("customer_state"),
  customerZip: varchar("customer_zip"),
  nearestAirportCode: varchar("nearest_airport_code", { length: 10 }),
  implementationDate: date("implementation_date"),
  cancellationDate: date("cancellation_date"),
  cancellationReason: text("cancellation_reason"),
  // Products, Rate, Price (stored as JSON for flexibility)
  productsRatePrice: text("products_rate_price"),
  // Financial Information
  arStatus: varchar("ar_status"), // A/R status
  lastInvoiceDate: date("last_invoice_date"),
  lastInvoicePdfUrl: varchar("last_invoice_pdf_url"),
  // Location
  customerLatitude: decimal("customer_latitude", { precision: 10, scale: 7 }),
  customerLongitude: decimal("customer_longitude", { precision: 10, scale: 7 }),
  // Operations
  network: varchar("network"),
  potentialRisk: varchar("potential_risk"),
  customerWebsite: varchar("customer_website"),
  // Primary Contact
  primaryContactName: varchar("primary_contact_name"),
  primaryContactNumber: varchar("primary_contact_number"),
  primaryContactCell: varchar("primary_contact_cell"),
  primaryContactEmail: varchar("primary_contact_email"),
  // Billing Contact
  billingContactName: varchar("billing_contact_name"),
  billingContactNumber: varchar("billing_contact_number"),
  billingContactEmail: varchar("billing_contact_email"),
  // HubSpot Integration
  hubspotId: varchar("hubspot_id").unique(),
  hubspotLastSyncedAt: timestamp("hubspot_last_synced_at"),
  hubspotSyncStatus: varchar("hubspot_sync_status").default("pending"), // pending, synced, error
  hubspotSource: varchar("hubspot_source").default("manual"), // manual, hubspot
  // Health Indicator - AI-driven risk indicator (manual for now)
  // Values: 'green' (healthy), 'yellow' (caution), 'red' (at risk)
  health: varchar("health"),
  // Health Trend - trajectory indicator
  // Values: 'improving', 'stable', 'declining'
  healthTrend: varchar("health_trend"),
  // Health Reasons - JSON array of 1-3 reasons for current health status
  healthReasons: text("health_reasons"),
  // Last health calculation timestamp
  healthCalculatedAt: timestamp("health_calculated_at"),
  // Parent Account - for enterprise/hierarchical relationships
  parentAccountId: varchar("parent_account_id"),
  // Activity Tracking
  lastActivityDate: date("last_activity_date"),
  // Next Required Touch - accountability for follow-ups
  nextRequiredTouchDate: date("next_required_touch_date"),
  // Account Owner - user responsible for this account
  accountOwnerId: varchar("account_owner_id").references(() => users.id, { onDelete: 'set null' }),
  // SLA & Services Configuration
  // Enabled services: JSON array of service types
  enabledServices: text("enabled_services"), // JSON: ["pickup_delivery", "parts_delivery", "dealer_transfers", "transport", "other"]
  // Operating hours: JSON object with per-day config
  operatingHours: text("operating_hours"), // JSON: { "monday": { "start": "08:00", "end": "17:00" }, ... }
  // Coverage expectation: guaranteed or best_effort
  coverageExpectation: varchar("coverage_expectation"), // "guaranteed" | "best_effort"
  // Driver requirements
  icAllowed: boolean("ic_allowed").default(true),
  employeeOnly: boolean("employee_only").default(false),
  driverTier: varchar("driver_tier"), // e.g., "tier_1", "tier_2", "any"
  // Technology Partner integration
  techPartnerName: varchar("tech_partner_name"),       // "RedCap" | "Draiver" | "DriverConnect"
  techPartnerAccountId: varchar("tech_partner_account_id"), // partner-assigned account identifier
  // Driver Model - the operational service model for the account
  // Values: "drivershift" | "driverdash" | "hybrid"
  driverModel: varchar("driver_model"),
  // Program - the commercial program this account is enrolled in
  program: varchar("program"),
  // Region - the geographic region this account belongs to
  region: varchar("region"),
  // Shift Bill Rate - standard hourly billing rate for DriverShift services (DH-001167)
  shiftBillRate: decimal("shift_bill_rate", { precision: 10, scale: 2 }),
  // SLA Metrics (v1 placeholders - will be calculated from actual data in v2)
  slaLatePickups: integer("sla_late_pickups").default(0),
  slaMissedCoverage: integer("sla_missed_coverage").default(0),
  slaEscalations: integer("sla_escalations").default(0),
  // Strategic & Sensitivity Flags
  // These flags do NOT affect Health scores - they're for prioritization and routing
  isStrategicAccount: boolean("is_strategic_account").default(false),
  isHighSensitivity: boolean("is_high_sensitivity").default(false),
  isCarrierVisible: boolean("is_carrier_visible").default(false),
  requiresExecAttention: boolean("requires_exec_attention").default(false),
  // AI Scoring v1 - Payment Timeliness & Collections Risk
  // Score 0-100 based on payment behavior metrics (higher = better payer)
  paymentTimelinessScore: integer("payment_timeliness_score"),
  // Risk tier: healthy (70+), watchlist (50-69), at_risk (30-49), collections_candidate (<30)
  collectionsRiskTier: varchar("collections_risk_tier"), // 'healthy' | 'watchlist' | 'at_risk' | 'collections_candidate'
  // Top 3 drivers for the score (JSON array of strings)
  scoreExplanation: text("score_explanation"), // JSON: ["DSO worsening", "high dispute rate", "pays after reminders"]
  // When score was last calculated
  lastScoredAt: timestamp("last_scored_at"),
  // Archive / Non-Destructive Lifecycle (DH-000039)
  isArchived: boolean("is_archived").notNull().default(false),
  archivedAt: timestamp("archived_at", { withTimezone: true }),
  archivedBy: varchar("archived_by").references(() => users.id, { onDelete: "set null" }),
  archiveReason: text("archive_reason"),
  isDeleted: boolean("is_deleted").notNull().default(false),
  deletedAt: timestamp("deleted_at"),
  deletedByUserId: varchar("deleted_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  // Merge tracking — set when this record is retired as a duplicate
  mergedIntoId: varchar("merged_into_id"), // ID of the primary account this was merged into
  mergedAt: timestamp("merged_at"),
  mergedById: varchar("merged_by_id").references(() => users.id, { onDelete: 'set null' }),
  mergeReason: text("merge_reason"),
  // ── Weekly Report Config ───────────────────────────────────────────────────
  reportContactName: varchar("report_contact_name", { length: 255 }),  // Overrides primaryContactName for report greeting
  reportPrimaryEmail: varchar("report_primary_email"),        // Legacy single To: override (deprecated; use reportPrimaryEmails)
  reportPrimaryEmails: text("report_primary_emails"),         // JSON array of To: email addresses (multi-recipient)
  reportCcEmails: text("report_cc_emails"),                   // JSON array of CC email addresses
  sendWeeklyReport: boolean("send_weekly_report").default(false),
  reportSendDay: varchar("report_send_day").default("monday"),   // mon-sun
  reportSendTime: varchar("report_send_time").default("08:00"),  // HH:mm (24h, America/Chicago)
  includeSchedulePdf: boolean("include_schedule_pdf").default(true),
  includeHoursExcel: boolean("include_hours_excel").default(true),
  // ── Account Timezone ───────────────────────────────────────────────────────
  // IANA timezone string (e.g. "America/Chicago"). Used for scheduling displays.
  // Backfilled from customer_state on creation; editable by admins.
  timezone: varchar("timezone").default("America/Chicago"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Alias for new "Accounts" terminology in UI (database still uses "customers" table)
export const accounts = customers;

// HubSpot Field Mappings - maps DriverHub customer fields to HubSpot company properties
// Two-tier access control:
// - Admin (NexCopy team): Can create, modify, lock/unlock any mapping
// - Super User (Customer team): Can modify unlocked mappings only, cannot change locked mappings
export const hubspotFieldMappings = pgTable("hubspot_field_mappings", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // DriverHub field name (from customers table)
  driverHubField: varchar("driverhub_field").notNull().unique(),
  // HubSpot property name (internal name from HubSpot API)
  hubspotProperty: varchar("hubspot_property"),
  // HubSpot property label (display name)
  hubspotPropertyLabel: varchar("hubspot_property_label"),
  // Whether this mapping is active
  isActive: boolean("is_active").default(true),
  // Whether this mapping is locked by NexCopy (Admin role)
  // Locked mappings cannot be modified by Super Users (Customer team)
  isLocked: boolean("is_locked").default(false),
  // Who locked this mapping (for audit trail)
  lockedBy: varchar("locked_by").references(() => users.id, { onDelete: 'set null' }),
  lockedAt: timestamp("locked_at"),
  // Field type for validation
  fieldType: varchar("field_type"), // 'string', 'number', 'date', 'boolean'
  // Transformation rule (for future use)
  transformRule: text("transform_rule"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  updatedBy: varchar("updated_by").references(() => users.id, { onDelete: 'set null' }),
});

export const insertHubspotFieldMappingSchema = createInsertSchema(hubspotFieldMappings).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});
export type InsertHubspotFieldMapping = z.infer<typeof insertHubspotFieldMappingSchema>;
export type HubspotFieldMapping = typeof hubspotFieldMappings.$inferSelect;

