// Driver accidents/claims/incidents - comprehensive tracking
export const claimExecutionSystemOptions = [
  { value: "redcap", label: "RedCap" },
  { value: "move_now_driver_connect", label: "MoveNow / DriverConnect" },
] as const;
export type ClaimExecutionSystem = typeof claimExecutionSystemOptions[number]["value"];
export const claimExecutionSystemValues = claimExecutionSystemOptions.map(
  ({ value }) => value
) as [ClaimExecutionSystem, ...ClaimExecutionSystem[]];
/** Historical values remain readable but are intentionally not selectable. */
export const claimExecutionSystemLegacyValueLabels = {
  draiver: "Draiver",
  Draiver: "Draiver",
} as const;

/**
 * Claim Resolution Status — the single authoritative source for the accidents.status
 * field's options and display labels. This describes the operational/financial
 * disposition of a Claim (e.g. Pending, Denied, DoD Paid) and is a distinct concept
 * from the Claim Workflow / carrier-submission stage (accidents.claimStatus).
 * Consumed by Claim Detail (Resolution Status field) and the Claims Analysis Report
 * (Status column/filter) — do not duplicate this list elsewhere. DH-002337.
 */
export const claimResolutionStatusOptions = [
  { value: "abandoned", label: "Abandoned" },
  { value: "denied", label: "Denied" },
  { value: "denied_abandoned", label: "Denied/Abandoned" },
  { value: "driver_paid", label: "Driver Paid" },
  { value: "insurance_paid", label: "Insurance Paid" },
  { value: "dod_paid", label: "DoD Paid" },
  { value: "paid_jri", label: "Paid-JRI" },
  { value: "paid_other_insurance", label: "Paid-Other Insurance" },
  { value: "pending", label: "Pending" },
] as const;
export type ClaimResolutionStatus = typeof claimResolutionStatusOptions[number]["value"];

export const accidents = pgTable("accidents", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  driverId: varchar("driver_id").notNull().references(() => drivers.id, { onDelete: 'cascade' }),
  // Identification
  redcapId: varchar("redcap_id"),
  executionSystem: varchar("execution_system"), // 'redcap', 'move_now_driver_connect'; legacy 'draiver' remains readable
  // Date Information
  incidentDate: timestamp("incident_date"),
  monthOfIncident: varchar("month_of_incident"),
  yearOfIncident: varchar("year_of_incident"),
  // Legacy field for backwards compatibility (still required for existing data)
  accidentDate: timestamp("accident_date").notNull(),
  // Location
  location: varchar("location").notNull(),
  // Cost Estimates
  damageEst1: decimal("damage_est_1", { precision: 10, scale: 2 }),
  damageEst2: decimal("damage_est_2", { precision: 10, scale: 2 }),
  propertyDamage: decimal("property_damage", { precision: 10, scale: 2 }),
  injuries: varchar("injuries"),
  totalEstimate: decimal("total_estimate", { precision: 10, scale: 2 }),
  probableCost: decimal("probable_cost", { precision: 10, scale: 2 }),
  actualCost: decimal("actual_cost", { precision: 10, scale: 2 }),
  // Status (legacy field - kept for backwards compatibility)
  status: varchar("status").default("open"), // 'open', 'investigating', 'resolved', 'closed'
  paidNotClosed: boolean("paid_not_closed").default(false),
  // Claim Lifecycle Status (canonical state machine)
  // States: DRAFT, SUBMITTED, UNDER_REVIEW, ADDITIONAL_INFO_REQUESTED, SENT_TO_CARRIER, APPROVED, DENIED, PAID, CLOSED
  claimStatus: varchar("claim_status").default("DRAFT"),
  // Claim Type and Severity (for Claims MVP filtering)
  claimType: varchar("claim_type"), // DAMAGE, ACCIDENT, INJURY, PROPERTY, OTHER
  claimSeverity: varchar("claim_severity"), // LOW, MEDIUM, HIGH, CRITICAL
  // Triage & Severity Classification (Day-Zero Control)
  triageSeverity: varchar("triage_severity"), // minor, moderate, severe
  injuryFlag: boolean("injury_flag").default(false),
  drivableFlag: boolean("drivable_flag").default(true),
  triageOwnerUserId: varchar("triage_owner_user_id").references(() => users.id),
  carrierNotificationRequired: boolean("carrier_notification_required").default(false),
  triageDecisionAt: timestamp("triage_decision_at"),
  triageOverrideReason: text("triage_override_reason"),
  triageOverrideByUserId: varchar("triage_override_by_user_id").references(() => users.id),
  triageOverrideAt: timestamp("triage_override_at"),
  // Market (for filtering)
  marketId: varchar("market_id"),
  // Driver Information
  driverClassification: varchar("driver_classification"), // 'employee', 'independent_contractor'
  employeeId: varchar("employee_id"), // Links to employee driver (7 chars)
  independentContractorId: varchar("independent_contractor_id"), // Links to IC driver (7 chars)
  dodAtFault: varchar("dod_at_fault"), // 'yes', 'no', 'pending', 'partial'
  driverPaymentPercent: decimal("driver_payment_percent", { precision: 5, scale: 2 }),
  // Customer Information
  customerId: varchar("customer_id").references(() => customers.id),
  // Driver Drug Testing
  driverDrugTestRequested: varchar("driver_drug_test_requested"), // 'yes', 'no'
  driverDrugTestRequestedDate: timestamp("driver_drug_test_requested_date"),
  driverDrugTestResults: varchar("driver_drug_test_results"), // 'positive', 'negative', 'pending', 'refused'
  driverDrugTestResultsDate: timestamp("driver_drug_test_results_date"),
  // Notes
  notesReceived: text("notes_received"),
  incidentCommentsHistory: jsonb("incident_comments_history"), // Array of {id, text, createdAt, createdBy}
  paidNotClosedStatus: varchar("paid_not_closed_status"), // '(-Loss) Yes - Salvage', '(-Loss) Yes - Subro', '(+Loss) Yes - Addtl Claim', '(+Loss) Yes - Subro'
  // Vehicle & Incident Type
  vehicleInvolved: varchar("vehicle_involved"),
  incidentType: varchar("incident_type"), // event-only: bodily_injury_single, got_rear_ended, careless_driving, etc.
  // Incident Classification (structured fields — separated from incidentType)
  liabilityFault: varchar("liability_fault"), // at_fault | not_at_fault | shared_fault | unknown
  claimCategory: varchar("claim_category"), // insurance_claim | internal_claim
  damageLocation: varchar("damage_location"), // front | rear | driver_side | passenger_side | wheel_area | windshield | interior | multiple_areas | unknown
  estimatedDamageAmount: decimal("estimated_damage_amount", { precision: 10, scale: 2 }),
  preventability: varchar("preventability"), // Preventable | Non-Preventable | Undetermined
  // Documentation & Operational Flags
  noPhotosFlag: boolean("no_photos_flag").default(false),
  poorPhotosFlag: boolean("poor_photos_flag").default(false),
  abandonedFlag: boolean("abandoned_flag").default(false),
  // Zendesk Integration
  zendeskTicketNumber: varchar("zendesk_ticket_number"),
  // Insurance Information
  insuranceClaimSubmitted: boolean("insurance_claim_submitted").default(false),
  insuranceClaimSubmittedStatus: varchar("insurance_claim_submitted_status"), // 'yes', 'no', 'pending'
  insuranceClaimNumber: varchar("insurance_claim_number"),
  subrogationClaim: varchar("subrogation_claim"),
  insuranceReserve: decimal("insurance_reserve", { precision: 10, scale: 2 }),
  insurancePaid: decimal("insurance_paid", { precision: 10, scale: 2 }),
  insuranceTotal: decimal("insurance_total", { precision: 10, scale: 2 }),
  insuranceDate: timestamp("insurance_date"),
  insuranceFault: varchar("insurance_fault"),
  insuranceComments: text("insurance_comments"),
  insuranceCommentsHistory: jsonb("insurance_comments_history"), // Array of {id, text, createdAt, createdBy}
  // Legacy fields for backwards compatibility
  policeReportFiled: boolean("police_report_filed").default(false),
  policeReportNumber: varchar("police_report_number"),
  atFault: varchar("at_fault"),
  repairCost: decimal("repair_cost", { precision: 10, scale: 2 }),
  finalRepairCost: decimal("final_repair_cost", { precision: 10, scale: 2 }),
  repairStartDate: timestamp("repair_start_date"),
  repairCompletionDate: timestamp("repair_completion_date"),
  insuranceSubmitted: boolean("insurance_submitted").default(false),
  description: text("description"),
  resolutionNotes: text("resolution_notes"),
  // Move linkage (optional - may be null for incidents not tied to a specific move)
  moveId: varchar("move_id").references(() => trips.id, { onDelete: 'set null' }),
  // Immutable snapshot reference for submitted claims (set when claim transitions to SUBMITTED)
  moveSnapshotId: varchar("move_snapshot_id"), // References move_snapshots.id (added after table definition to avoid circular ref)
  // Evidence Compliance (photo/document status for claim defensibility)
  evidenceComplianceStatus: varchar("evidence_compliance_status").default("none"), // none | partial | complete
  evidencePresent: boolean("evidence_present").default(false), // Has any evidence been attached?
  // Claim Outcome (for reporting success rates when photos exist)
  claimOutcome: varchar("claim_outcome"), // denied | paid | recovered | pending
  payoutAmount: decimal("payout_amount", { precision: 10, scale: 2 }), // Amount paid out (if any)
  recoveredAmount: decimal("recovered_amount", { precision: 10, scale: 2 }), // Amount recovered (subrogation, etc.)
  // Claim Review Decision Layer
  // Claim Severity Estimate — early financial triage field (set by ops, drives insurance routing suggestion)
  severityEstimate: varchar("severity_estimate").default("minor"), // minor | moderate | major | catastrophic
  reviewPreventability: varchar("review_preventability"), // Preventable | Non-Preventable | Undetermined
  reviewSeverity: varchar("review_severity"), // Minor | Moderate | Major | Catastrophic
  reviewHandlingType: varchar("review_handling_type"), // Internal | Insurance
  reviewRootCause: varchar("review_root_cause"), // Distracted Driving | Backing Error | ...
  reviewCorrectiveAction: varchar("review_corrective_action"), // No Action | Coaching | ...
  reviewDate: timestamp("review_date"),
  reviewNotes: text("review_notes"),
  reviewedByUserId: varchar("reviewed_by_user_id").references(() => users.id),
  // Litigation Hold & Legal Readiness (Ticket 5)
  litigationHoldActive: boolean("litigation_hold_active").default(false),
  litigationHoldReason: text("litigation_hold_reason"), // Required when manually activated
  litigationHoldTrigger: varchar("litigation_hold_trigger"), // 'auto_injury', 'auto_severe', 'auto_attorney_letter', 'manual'
  litigationHoldActivatedAt: timestamp("litigation_hold_activated_at"),
  litigationHoldActivatedByUserId: varchar("litigation_hold_activated_by_user_id").references(() => users.id),
  litigationHoldReleasedAt: timestamp("litigation_hold_released_at"),
  litigationHoldReleasedByUserId: varchar("litigation_hold_released_by_user_id").references(() => users.id),
  litigationHoldReleaseReason: text("litigation_hold_release_reason"),
  attorneyLetterReceived: boolean("attorney_letter_received").default(false),
  attorneyLetterReceivedAt: timestamp("attorney_letter_received_at"),
  // Post-Accident Drug Test Workflow (Ticket 6)
  drugTestRequired: boolean("drug_test_required").default(false),
  drugTestStatus: varchar("drug_test_status").default("not_required"), // not_required, required, notified, acknowledged, completed, failed_to_comply, waived
  drugTestRequiredAt: timestamp("drug_test_required_at"),
  drugTestDueBy: timestamp("drug_test_due_by"), // default required_at + 24h
  drugTestRequiredReason: text("drug_test_required_reason"), // reason for requiring (auto or manual)
  drugTestWaivedReason: text("drug_test_waived_reason"), // required when waiving
  drugTestCompletedAt: timestamp("drug_test_completed_at"),
  drugTestLastNotifiedAt: timestamp("drug_test_last_notified_at"),
  drugTestAcknowledgedAt: timestamp("drug_test_acknowledged_at"),
  policeReportFlag: boolean("police_report_flag").default(false), // used for auto-trigger
  // ========== Carrier Submission Packet (v1) ==========
  carrierSubmissionStatus: varchar("carrier_submission_status").default("DRAFT"),
  // Loss Details
  lossDate: timestamp("loss_date"),
  lossTime: varchar("loss_time"),
  lossLocation: text("loss_location"),
  descriptionOfLoss: text("description_of_loss"),
  pointOfImpact: varchar("point_of_impact"),
  weatherConditions: varchar("weather_conditions"),
  roadConditions: varchar("road_conditions"),
  // Our Vehicle
  vehicleYear: varchar("vehicle_year"),
  vehicleMake: varchar("vehicle_make"),
  vehicleModel: varchar("vehicle_model"),
  vehicleVin: varchar("vehicle_vin"),
  vehicleLicensePlate: varchar("vehicle_license_plate"),
  vehicleState: varchar("vehicle_state"),
  // Other Party / Claimant
  claimantName: varchar("claimant_name"),
  claimantPhone: varchar("claimant_phone"),
  claimantAddress: text("claimant_address"),
  claimantInsurance: varchar("claimant_insurance"),
  claimantPolicyNumber: varchar("claimant_policy_number"),
  claimantVehicleYear: varchar("claimant_vehicle_year"),
  claimantVehicleMake: varchar("claimant_vehicle_make"),
  claimantVehicleModel: varchar("claimant_vehicle_model"),
  claimantVehicleVin: varchar("claimant_vehicle_vin"),
  // Police Report (carrier form fields)
  policeReportObtained: boolean("police_report_obtained").default(false),
  policeReportDepartment: varchar("police_report_department"),
  policeReportCaseNumber: varchar("police_report_case_number"),
  // Single business decision governing both police-related evidence requirements.
  // Existing column retained for backwards compatibility; the UI labels this
  // "No Police Involvement".
  policeReportWaived: boolean("police_report_waived").notNull().default(false),
  policeReportWaivedReason: text("police_report_waived_reason"),
  policeReportWaivedByUserId: varchar("police_report_waived_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  policeReportWaivedAt: timestamp("police_report_waived_at"),
  // Witnesses
  witnessName: varchar("witness_name"),
  witnessPhone: varchar("witness_phone"),
  witnessStatement: text("witness_statement"),
  // Injuries
  injuryDescription: text("injury_description"),
  medicalTreatmentSought: boolean("medical_treatment_sought").default(false),
  medicalProvider: varchar("medical_provider"),
  // Catastrophic Loss
  catastrophicLoss: boolean("catastrophic_loss").default(false),
  catastrophicAcknowledged: boolean("catastrophic_acknowledged").default(false),
  // ========== General Liability (GL) Carrier Submission Fields ==========
  // Insured
  insuredName: varchar("insured_name").default("AutoNition, LLC DBA Driver on Demand"),
  // GL Loss Location (structured address)
  lossLocationAddress: text("loss_location_address"),
  lossLocationCity: text("loss_location_city"),
  lossLocationState: text("loss_location_state"),
  lossLocationZip: text("loss_location_zip"),
  // GL Incident
  allegedIncidentDescription: text("alleged_incident_description"),
  productInvolved: boolean("product_involved").default(false),
  productDescription: text("product_description"),
  // GL Injured Parties (repeatable JSON list)
  injuredParties: jsonb("injured_parties"),
  // GL Property Damage (repeatable JSON list)
  propertyDamageEntries: jsonb("property_damage_entries"),
  // GL Lawsuit
  lawsuitFiled: boolean("lawsuit_filed").default(false),
  lawsuitCountyState: text("lawsuit_county_state"),
  dateOfService: timestamp("date_of_service"),
  // GL Reporter Info
  reportFiledByName: text("report_filed_by_name"),
  reportFiledByEmail: text("report_filed_by_email"),
  reportFiledByPhone: text("report_filed_by_phone"),
  dateOfReport: timestamp("date_of_report"),
  // Placeholders for follow-on (branch/policy)
  branchName: varchar("branch_name"),
  branchNumber: varchar("branch_number"),
  policyNumber: varchar("policy_number"),
  accountNumber: varchar("account_number"),
  // GL Reporting Acknowledgment
  glReportingAcknowledged: boolean("gl_reporting_acknowledged").default(false),
  glReportingAcknowledgedBy: varchar("gl_reporting_acknowledged_by").references(() => users.id),
  glReportingAcknowledgedAt: timestamp("gl_reporting_acknowledged_at"),
  // GL Compliance Training
  glTrainingReviewed: boolean("gl_training_reviewed").default(false),
  glTrainingReviewedBy: varchar("gl_training_reviewed_by").references(() => users.id),
  glTrainingReviewedAt: timestamp("gl_training_reviewed_at"),
  // Carrier Handling Mode
  carrierHandlingMode: boolean("carrier_handling_mode").default(false),
  carrierHandlingModeSetBy: varchar("carrier_handling_mode_set_by").references(() => users.id),
  carrierHandlingModeSetAt: timestamp("carrier_handling_mode_set_at"),
  carrierHandlingOverrideReason: text("carrier_handling_override_reason"),
  // Submission Reporting
  carrierReportedAt: timestamp("carrier_reported_at"),
  carrierReportedByUserId: varchar("carrier_reported_by_user_id").references(() => users.id),
  carrierReportedTo: varchar("carrier_reported_to"),
  carrierReportedMethod: varchar("carrier_reported_method"),
  carrierReportedNotes: text("carrier_reported_notes"),
  // Adjuster Info
  carrierAcknowledgedAt: timestamp("carrier_acknowledged_at"),
  adjusterName: varchar("adjuster_name"),
  adjusterPhone: varchar("adjuster_phone"),
  adjusterEmail: varchar("adjuster_email"),
  adjusterAssignedAt: timestamp("adjuster_assigned_at"),
  // Submission Closure
  carrierSubmissionClosedAt: timestamp("carrier_submission_closed_at"),
  carrierSubmissionClosedReason: text("carrier_submission_closed_reason"),
  // Email Submission Tracking (v1 — push via email)
  carrierSubmissionEmailedAt: timestamp("carrier_submission_emailed_at"),
  carrierSubmissionEmailedBy: varchar("carrier_submission_emailed_by").references(() => users.id, { onDelete: "set null" }),
  carrierSubmissionRecipients: jsonb("carrier_submission_recipients"), // string[]
  carrierSubmissionCc: jsonb("carrier_submission_cc"),               // string[]
  carrierSubmissionNotes: text("carrier_submission_notes"),
  carrierSubmissionArtifacts: jsonb("carrier_submission_artifacts"), // [{type, fileName, fileUrl, fileSizeBytes, createdAt}]
  carrierSubmissionFailureReason: text("carrier_submission_failure_reason"),
  carrierSubmissionMessageId: varchar("carrier_submission_message_id"), // Resend email ID
  // ========== Evidence Lock (Ticket: Claims Evidence Lock) ==========
  // Auto-set when claimStatus transitions to a carrier-reported/litigation state.
  // Manual toggle also available (super admin only).
  evidenceLock: boolean("evidence_lock").default(false),
  evidenceLockReason: text("evidence_lock_reason"),
  evidenceLockSetByUserId: varchar("evidence_lock_set_by_user_id").references(() => users.id),
  evidenceLockSetAt: timestamp("evidence_lock_set_at"),
  // Metadata
  reportedBy: varchar("reported_by").notNull().references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
  updatedBy: varchar("updated_by").references(() => users.id, { onDelete: 'set null' }),
  // Import tracking — set when a row was committed under Initial Load Mode with missing/invalid fields
  needsUpdate: boolean("needs_update").default(false),
  needsUpdateFields: text("needs_update_fields").array(),
  needsUpdateReasons: text("needs_update_reasons").array(),
  needsUpdateImportBatchId: varchar("needs_update_import_batch_id"),
  isDeleted: boolean("is_deleted").notNull().default(false),
  deletedAt: timestamp("deleted_at"),
  deletedByUserId: varchar("deleted_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  // User-facing displayed Claim ID (set to moveId when available; fallback to short UUID prefix)
  displayClaimId: varchar("display_claim_id"),
});

