// Deletion Override Requests — dual-approval workflow for deleting evidence-locked attachments
export const deletionOverrideStatusEnum = ['pending', 'approved', 'rejected', 'expired'] as const;
export type DeletionOverrideStatus = typeof deletionOverrideStatusEnum[number];

export const deletionOverrideRequests = pgTable("deletion_override_requests", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  claimId: varchar("claim_id").notNull().references(() => accidents.id, { onDelete: 'cascade' }),
  attachmentId: varchar("attachment_id").notNull().references(() => accidentAttachments.id, { onDelete: 'cascade' }),
  requestedByUserId: varchar("requested_by_user_id").notNull().references(() => users.id),
  requestedAt: timestamp("requested_at").defaultNow(),
  requestReason: text("request_reason").notNull(),
  status: varchar("status").notNull().default("pending"), // DeletionOverrideStatus
  approvedByUserId: varchar("approved_by_user_id").references(() => users.id),
  approvedAt: timestamp("approved_at"),
  approvalNotes: text("approval_notes"),
  expiresAt: timestamp("expires_at").notNull(), // requestedAt + 24h
  createdAt: timestamp("created_at").defaultNow(),
});

export const insertDeletionOverrideRequestSchema = createInsertSchema(deletionOverrideRequests).omit({
  id: true,
  requestedAt: true,
  createdAt: true,
  status: true,
  approvedByUserId: true,
  approvedAt: true,
  approvalNotes: true,
});
export type InsertDeletionOverrideRequest = z.infer<typeof insertDeletionOverrideRequestSchema>;
export type DeletionOverrideRequest = typeof deletionOverrideRequests.$inferSelect;

