// Move Media - photos and evidence for pickup/dropoff/claims
export const moveMedia = pgTable("move_media", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  moveId: varchar("move_id").notNull().references(() => trips.id, { onDelete: 'cascade' }),
  claimId: varchar("claim_id").references(() => accidents.id, { onDelete: 'set null' }), // Nullable - set if photo is claim-specific
  stage: varchar("stage").notNull(), // pickup | dropoff | claim
  category: varchar("category").notNull(), // angle_front_left, angle_front_right, etc.
  fileUrl: text("file_url").notNull(), // Object storage URL
  storageKey: varchar("storage_key").notNull(), // Object storage key for deletion
  capturedByUserId: varchar("captured_by_user_id").notNull().references(() => users.id),
  capturedAt: timestamp("captured_at", { withTimezone: true }).defaultNow(),
  // Quality/analysis metadata
  blurScore: decimal("blur_score", { precision: 5, scale: 2 }), // 0-100, higher = blurrier
  qualityScore: decimal("quality_score", { precision: 5, scale: 2 }), // 0-100, higher = better
  qualityPassed: boolean("quality_passed").default(true), // Did photo pass quality threshold?
  qualityOverridden: boolean("quality_overridden").default(false), // User chose "use anyway"
  // Image metadata
  metadata: jsonb("metadata"), // { width, height, fileSize, hash, mimeType }
  isDeleted: boolean("is_deleted").notNull().default(false),
  deletedAt: timestamp("deleted_at"),
  deletedByUserId: varchar("deleted_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  deletionReason: text("deletion_reason"),
  createdAt: timestamp("created_at").defaultNow(),
});

export const insertMoveMediaSchema = createInsertSchema(moveMedia).omit({
  id: true,
  createdAt: true,
});
export type InsertMoveMedia = z.infer<typeof insertMoveMediaSchema>;
export type MoveMedia = typeof moveMedia.$inferSelect;

