// Work Locations / Departments
export const workLocations = pgTable("work_locations", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  entityId: varchar("entity_id"),
  name: varchar("name").notNull(),
  address: text("address"),
  city: varchar("city"),
  state: varchar("state"),
  zipCode: varchar("zip_code"),
  latitude: decimal("latitude", { precision: 10, scale: 7 }),
  longitude: decimal("longitude", { precision: 10, scale: 7 }),
  geofenceRadius: integer("geofence_radius").default(100), // meters for GPS clock-in validation
  timezone: varchar("timezone").default("America/New_York"),
  isActive: boolean("is_active").default(true),
  // Labor Budget & Cost Controls
  dailyLaborBudget: decimal("daily_labor_budget", { precision: 10, scale: 2 }), // Budget threshold per day
  weeklyLaborBudget: decimal("weekly_labor_budget", { precision: 10, scale: 2 }), // Budget threshold per week
  budgetWarningThreshold: integer("budget_warning_threshold").default(90), // Percentage (0-100) to trigger warning
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Shift Templates for quick scheduling
export const shiftTemplates = pgTable("shift_templates", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  entityId: varchar("entity_id"),
  name: varchar("name").notNull(),
  description: text("description"),
  locationId: varchar("location_id").references(() => workLocations.id),
  locationName: varchar("location_name"), // Denormalized for display
  role: varchar("role"),
  startTime: varchar("start_time").notNull(), // HH:MM format
  endTime: varchar("end_time").notNull(), // HH:MM format
  breakDuration: integer("break_duration").default(0), // minutes
  requiredHeadcount: integer("required_headcount").default(1),
  color: varchar("color").default("#3B82F6"), // for calendar display
  requiredSkills: jsonb("required_skills"), // array of skill tags
  notes: text("notes"),
  isActive: boolean("is_active").default(true),
  createdBy: varchar("created_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Shifts - actual scheduled work periods
export const shifts = pgTable("shifts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  locationId: varchar("location_id").references(() => workLocations.id),
  templateId: varchar("template_id").references(() => shiftTemplates.id),
  date: date("date").notNull(),
  startTime: timestamp("start_time").notNull(),
  endTime: timestamp("end_time").notNull(),
  breakDuration: integer("break_duration").default(0), // minutes
  scheduledHours: decimal("scheduled_hours", { precision: 5, scale: 2 }),
  requiredStaff: integer("required_staff").default(1),
  assignedStaff: integer("assigned_staff").default(0),
  status: varchar("status").default("draft"), // draft, published, completed, cancelled
  roleName: varchar("role_name"),
  notes: text("notes"),
  color: varchar("color").default("#3B82F6"),
  isOpenShift: boolean("is_open_shift").default(false), // employees can claim
  estimatedLaborCost: decimal("estimated_labor_cost", { precision: 10, scale: 2 }),
  sourceSystem: varchar("source_system"),
  sourceImportRunId: varchar("source_import_run_id"),
  sourceRowHash: varchar("source_row_hash").unique(),
  createdBy: varchar("created_by").references(() => users.id),
  publishedAt: timestamp("published_at"),
  publishedBy: varchar("published_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Shift Assignments - who is assigned to which shift
export const shiftAssignments = pgTable("shift_assignments", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  shiftId: varchar("shift_id").notNull().references(() => shifts.id, { onDelete: 'cascade' }),
  userId: varchar("user_id").notNull().references(() => users.id),
  employeeId: varchar("employee_id").references(() => employees.id),
  driverId: varchar("driver_id").references(() => drivers.id),
  status: varchar("status").default("assigned"), // assigned, confirmed, declined, swapped, no_show
  assignmentRole: varchar("assignment_role").default("primary"), // primary, backup, on_call
  assignedBy: varchar("assigned_by").references(() => users.id),
  confirmedAt: timestamp("confirmed_at"),
  notes: text("notes"),
  // Labor Cost Tracking - captured at assignment time for accurate costing
  hourlyRate: decimal("hourly_rate", { precision: 6, scale: 2 }), // Rate at time of assignment
  scheduledHours: decimal("scheduled_hours", { precision: 5, scale: 2 }), // Calculated shift duration
  actualHours: decimal("actual_hours", { precision: 5, scale: 2 }), // From time & attendance
  estimatedCost: decimal("estimated_cost", { precision: 10, scale: 2 }), // hourlyRate * scheduledHours
  actualCost: decimal("actual_cost", { precision: 10, scale: 2 }), // hourlyRate * actualHours
  isOvertime: boolean("is_overtime").default(false), // Overtime flag
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Payroll Exports - track export history
