export type InsertPolicyVersion = z.infer<typeof insertPolicyVersionSchema>;
export type PayPeriod = typeof payPeriods.$inferSelect;
export type InsertPayPeriod = z.infer<typeof insertPayPeriodSchema>;
export type PayLine = typeof payLines.$inferSelect;
export type InsertPayLine = z.infer<typeof insertPayLineSchema>;
export type Move = typeof moves.$inferSelect;
export type InsertMove = z.infer<typeof insertMoveSchema>;
export type ExportAuditLogEntry = typeof exportAuditLog.$inferSelect;
export type InsertExportAuditLog = z.infer<typeof insertExportAuditLogSchema>;
export type PayrollException = typeof payrollExceptions.$inferSelect;
export type InsertPayrollException = z.infer<typeof insertPayrollExceptionSchema>;

// Insert schemas for scheduling tables
export const insertWorkLocationSchema = createInsertSchema(workLocations).omit({ id: true, createdAt: true, updatedAt: true });
export const insertShiftTemplateSchema = createInsertSchema(shiftTemplates).omit({ id: true, createdAt: true });
export const insertShiftSchema = createInsertSchema(shifts).omit({ id: true, createdAt: true, updatedAt: true });
export const insertShiftAssignmentSchema = createInsertSchema(shiftAssignments).omit({ id: true, createdAt: true, updatedAt: true });
