// Invoicing statuses and enums
export const CHARGE_STATUSES = ["draft", "pending_approval", "approved", "invoiced", "paid", "adjusted", "void"] as const;
export type ChargeStatus = typeof CHARGE_STATUSES[number];

export const INVOICE_STATUSES = ["draft", "approved", "exported", "sent", "viewed", "partially_paid", "paid", "overdue", "disputed", "void", "written_off", "cancelled"] as const;
export type InvoiceStatus = typeof INVOICE_STATUSES[number];

export const DISPUTE_REASON_CATEGORIES = ["pricing", "service", "damage", "duplicate", "other"] as const;
export type DisputeReasonCategory = typeof DISPUTE_REASON_CATEGORIES[number];

export const PAYMENT_METHODS = ["credit_card", "ach", "check", "wire", "cash", "other"] as const;
export type PaymentMethod = typeof PAYMENT_METHODS[number];

export const PAYMENT_STATUSES = ["initiated", "pending", "processing", "completed", "failed", "refunded", "chargeback"] as const;
export type PaymentStatus = typeof PAYMENT_STATUSES[number];

export const DEPOSIT_STATUSES = ["draft", "balanced", "submitted", "locked", "reconciled"] as const;
export type DepositStatus = typeof DEPOSIT_STATUSES[number];

export const INTEGRATION_STATUSES = ["not_queued", "queued", "posted", "failed", "reconciled"] as const;
export type IntegrationStatus = typeof INTEGRATION_STATUSES[number];

export const PAYMENT_TERMS = ["due_upon_receipt", "net_7", "net_15", "net_30", "net_45", "net_60"] as const;
export type PaymentTerms = typeof PAYMENT_TERMS[number];

// Billable Charges - captures what will be billed (from timesheets, expenses, or manual entries)
export const billableCharges = pgTable("billable_charges", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Source reference - where the charge originated
  sourceType: varchar("source_type").notNull(), // 'timesheet', 'expense', 'trip', 'manual'
  sourceId: varchar("source_id"), // ID of the source record (timesheet id, expense id, trip id)
  // Idempotency key — caller-supplied unique token for the originating event.
  // Format convention (not enforced): "<sourceType>:<sourceId>[:<qualifier>]"
  // Example: "move:abc123", "trip:xyz:2024-03-15", "timesheet:uid:week-12"
  // A unique DB index enforces exactly-once charge creation per source event.
  sourceReferenceId: varchar("source_reference_id", { length: 500 }),
  // Customer and billing
  customerId: varchar("customer_id").notNull().references(() => customers.id),
  locationId: varchar("location_id").references(() => workLocations.id),
  // Charge details
  chargeDate: date("charge_date").notNull(),
  // serviceType is deprecated — Product is the source of truth. Kept nullable for legacy records.
  serviceType: varchar("service_type"),
  description: text("description").notNull(),
  quantity: decimal("quantity", { precision: 10, scale: 4 }).notNull(), // hours, units, miles, etc.
  unitRate: decimal("unit_rate", { precision: 10, scale: 4 }).notNull(),
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  // Optional reference fields
  jobId: varchar("job_id"), // Reference to a job or project
  referenceNumber: varchar("reference_number"), // External reference
  poNumber: varchar("po_number"), // Purchase order number
  // Product — the source of truth for all billing classification (Revenue Engine)
  productId: varchar("product_id").references(() => products.id, { onDelete: "set null" }),
  revenueCategory: varchar("revenue_category", { length: 50 }), // labor | moves | rideshare | fees | other
  // Product-snapshot: billing attributes copied from the product at charge creation time.
  // Set by the server on insert; never edited directly by users.
  productName: text("product_name"),
  billingCategory: varchar("billing_category", { length: 100 }),
  productTypeSnapshot: varchar("product_type_snapshot", { length: 100 }),
  billingFrequencySnapshot: varchar("billing_frequency_snapshot", { length: 100 }),
  unitOfMeasure: varchar("unit_of_measure", { length: 100 }),
  glCode: varchar("gl_code", { length: 100 }),
  billingStatus: varchar("billing_status", { length: 20 }).notNull().default("unbilled"), // unbilled | billed | voided
  chargeSource: varchar("charge_source", { length: 50 }), // scheduling | moves | rideshare | recurring | manual | api
  billedAt: timestamp("billed_at"),
  // Status and workflow
  status: varchar("status").default("unbilled"), // See CHARGE_STATUSES
  // Approval tracking
  approvedBy: varchar("approved_by").references(() => users.id),
  approvedAt: timestamp("approved_at"),
  approvalNotes: text("approval_notes"),
  // Invoice linkage
  invoiceId: varchar("invoice_id"), // Populated when invoiced
  invoiceLineItemId: varchar("invoice_line_item_id"), // Specific line on invoice
  // Tax handling
  isTaxable: boolean("is_taxable").default(false),
  taxRate: decimal("tax_rate", { precision: 5, scale: 4 }),
  taxAmount: decimal("tax_amount", { precision: 12, scale: 2 }),
  // Supporting documentation
  attachmentUrls: jsonb("attachment_urls"), // Array of document URLs
  notes: text("notes"),
  // Audit trail
  createdBy: varchar("created_by").notNull().references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
}, (table) => ({
  // Composite unique constraint: the combination of (sourceType, sourceReferenceId) must be
  // globally unique. NULL sourceReferenceId is excluded — manual charges with no reference
  // are not subject to deduplication. This replaces the former single-column index.
  srcTypeRefUniq: uniqueIndex("billable_charges_src_type_ref_uniq").on(table.sourceType, table.sourceReferenceId).where(sql`source_reference_id IS NOT NULL`),
}));

// Extended Customer billing profile (UI uses "Account" terminology)
