// Payment Method Change Audit Log - tracks changes to allowed payment methods per customer
export const paymentMethodAuditLog = pgTable("payment_method_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  customerId: varchar("customer_id").notNull().references(() => customers.id, { onDelete: 'cascade' }),
  changedBy: varchar("changed_by").notNull().references(() => users.id),
  changedByName: varchar("changed_by_name"),
  changeType: varchar("change_type").notNull(), // 'enabled', 'disabled', 'bulk_update'
  paymentMethod: varchar("payment_method").notNull(), // 'credit_card', 'ach', 'check', 'wire'
  previousValue: boolean("previous_value"),
  newValue: boolean("new_value"),
  reason: text("reason"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Customer Payment Methods - stored payment methods with vault tokens (no raw bank data)
export const customerPaymentMethods = pgTable("customer_payment_methods", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  customerId: varchar("customer_id").notNull().references(() => customers.id, { onDelete: 'cascade' }),
  // Payment method type
  methodType: varchar("method_type").notNull(), // 'ach', 'card'
  // Display info (safe to store)
  displayName: varchar("display_name"), // e.g., "Chase ****1234"
  last4: varchar("last4"), // Last 4 digits of account/card
  bankName: varchar("bank_name"), // For ACH: bank name
  accountType: varchar("account_type"), // For ACH: 'checking', 'savings'
  // Vault tokens (payment processor references - no raw data)
  stripePaymentMethodId: varchar("stripe_payment_method_id"), // Stripe pm_xxx or ba_xxx
  vaultToken: varchar("vault_token"), // Generic vault reference
  // Status
  isActive: boolean("is_active").default(true),
  isDefault: boolean("is_default").default(false),
  isVerified: boolean("is_verified").default(false),
  verifiedAt: timestamp("verified_at"),
  // For ACH verification
  verificationStatus: varchar("verification_status").default("pending"), // 'pending', 'verified', 'failed'
  verificationMethod: varchar("verification_method"), // 'micro_deposits', 'instant', 'plaid'
  // Audit
  createdBy: varchar("created_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
  deletedAt: timestamp("deleted_at"), // Soft delete for audit trail
});

// Autopay Attempts - tracks each autopay attempt for an invoice
export const autopayAttempts = pgTable("autopay_attempts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  customerId: varchar("customer_id").notNull().references(() => customers.id),
  paymentMethodId: varchar("payment_method_id").references(() => customerPaymentMethods.id),
  // Trigger info
  trigger: varchar("trigger").notNull(), // 'on_send', 'on_due_date', 'manual'
  // Attempt details
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  status: varchar("status").notNull().default("pending"), // 'pending', 'processing', 'succeeded', 'failed'
  // Result
  paymentId: varchar("payment_id").references(() => payments.id), // Created payment on success
  failureCode: varchar("failure_code"),
  failureMessage: text("failure_message"),
  processorResponse: text("processor_response"),
  // Timestamps
  attemptedAt: timestamp("attempted_at").defaultNow(),
  completedAt: timestamp("completed_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Invoice Activity Timeline - tracks all events related to an invoice
export const invoiceActivities = pgTable("invoice_activities", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  // Activity type
  activityType: varchar("activity_type").notNull(), // 'created', 'sent', 'viewed', 'reminder_sent', 'payment_received', 'status_changed', 'note_added'
  // Activity details
  description: text("description"),
  metadata: jsonb("metadata"), // Additional data like reminder type, payment amount, etc.
  // Who performed the action (null for system actions)
  performedBy: varchar("performed_by"),
  performedByType: varchar("performed_by_type").default("system"), // 'system', 'user', 'customer'
  // Communication details (for reminders)
  channel: varchar("channel"), // 'email', 'sms', 'portal'
  recipientEmail: varchar("recipient_email"),
  recipientPhone: varchar("recipient_phone"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Reminder Schedule Configuration (org-level)
export const reminderSchedules = pgTable("reminder_schedules", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Schedule name and description
  name: varchar("name").notNull(),
  description: text("description"),
  // Trigger timing (positive = days before due, negative = days after due)
  dayOffset: integer("day_offset").notNull(), // e.g., 3 = 3 days before, -7 = 7 days after
  // Channels
  emailEnabled: boolean("email_enabled").default(true),
  smsEnabled: boolean("sms_enabled").default(false),
  // Template references
  emailSubject: varchar("email_subject"),
  emailTemplate: text("email_template"),
  smsTemplate: varchar("sms_template"),
  // Settings
  isActive: boolean("is_active").default(true),
  isEscalation: boolean("is_escalation").default(false), // For 30-day overdue notices
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Customer Payment Behavior Metrics - for AI payment timeliness scoring
export const customerPaymentMetrics = pgTable("customer_payment_metrics", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  customerId: varchar("customer_id").notNull().references(() => customers.id).unique(),
  // Core timing metrics (rolling 6 months)
  avgDaysToPay: decimal("avg_days_to_pay", { precision: 8, scale: 2 }),
  medianDaysToPay: decimal("median_days_to_pay", { precision: 8, scale: 2 }),
  // Payment behavior percentages
  pctOnTime: decimal("pct_on_time", { precision: 5, scale: 2 }), // Paid by due_date
  pctPaidAfterReminder: decimal("pct_paid_after_reminder", { precision: 5, scale: 2 }),
  // Partial payment patterns
  avgPartialPaymentCountPerInvoice: decimal("avg_partial_payment_count", { precision: 5, scale: 2 }),
  // Dispute patterns
  disputeRate: decimal("dispute_rate", { precision: 5, scale: 2 }),
  // Reminder responsiveness
  reminderResponseTimeAvg: decimal("reminder_response_time_avg", { precision: 8, scale: 2 }), // Hours from reminder to payment
  // Trend analysis
  dsoTrendDirection: varchar("dso_trend_direction"), // 'improving', 'flat', 'worsening'
  // Supporting data
  totalInvoicesAnalyzed: integer("total_invoices_analyzed").default(0),
  totalPaymentsAnalyzed: integer("total_payments_analyzed").default(0),
  analysisWindowStart: date("analysis_window_start"),
  analysisWindowEnd: date("analysis_window_end"),
  // Calculation timestamps
  lastCalculatedAt: timestamp("last_calculated_at"),
  nextCalculationAt: timestamp("next_calculation_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Payment Events - raw events for metrics calculation
export const paymentEvents = pgTable("payment_events", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  customerId: varchar("customer_id").notNull().references(() => customers.id),
  invoiceId: varchar("invoice_id").references(() => invoices.id),
  // Event type
  eventType: varchar("event_type").notNull(), // 'invoice_sent', 'invoice_viewed', 'reminder_sent', 'payment_posted', 'dispute_opened', 'dispute_resolved'
  // Event details
  eventAt: timestamp("event_at").notNull(),
  // For reminders
  reminderType: varchar("reminder_type"), // 'pre_due', 'on_due', 'overdue', 'escalation'
  reminderScheduleId: varchar("reminder_schedule_id"),
  // For payments
  paymentAmount: decimal("payment_amount", { precision: 12, scale: 2 }),
  paymentId: varchar("payment_id").references(() => payments.id),
  // Timing data (calculated at event time for easier aggregation)
  daysToDueDate: integer("days_to_due_date"), // Negative = past due, positive = before due
  daysFromInvoiceSent: integer("days_from_invoice_sent"),
  // Metadata
  metadata: jsonb("metadata"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Payments - records of payments received
export const payments = pgTable("payments", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Payment identification
  paymentNumber: varchar("payment_number").notNull().unique(),
  customerId: varchar("customer_id").notNull().references(() => customers.id),
  // Payment details
  paymentDate: date("payment_date").notNull(),
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  paymentMethod: varchar("payment_method").notNull(), // See PAYMENT_METHODS
  // Status tracking
  status: varchar("status").default("pending"), // See PAYMENT_STATUSES
  // Stripe/processor details
  stripePaymentIntentId: varchar("stripe_payment_intent_id"),
  stripeChargeId: varchar("stripe_charge_id"),
  processorTransactionId: varchar("processor_transaction_id"),
  processorFee: decimal("processor_fee", { precision: 10, scale: 2 }),
  netAmount: decimal("net_amount", { precision: 12, scale: 2 }),
  // Check details (if payment method is check)
  checkNumber: varchar("check_number"),
  checkDate: date("check_date"),
  checkImageUrl: varchar("check_image_url"),
  bankName: varchar("bank_name"),
  depositBatchId: varchar("deposit_batch_id").references(() => depositBatches.id),
  // ACH details
  achAccountLast4: varchar("ach_account_last4"),
  achRoutingLast4: varchar("ach_routing_last4"),
  // Card details
  cardLast4: varchar("card_last4"),
  cardBrand: varchar("card_brand"),
  // Application tracking
  appliedAmount: decimal("applied_amount", { precision: 12, scale: 2 }).default("0"),
  unappliedAmount: decimal("unapplied_amount", { precision: 12, scale: 2 }),
  // Reference
  referenceNumber: varchar("reference_number"),
  remittanceAdvice: text("remittance_advice"),
  memo: text("memo"),
  // Refund tracking
  refundedAmount: decimal("refunded_amount", { precision: 12, scale: 2 }).default("0"),
  refundedAt: timestamp("refunded_at"),
  refundReason: text("refund_reason"),
  // QuickBooks integration
  qbPaymentId: varchar("qb_payment_id"),
  qbSyncStatus: varchar("qb_sync_status").default("not_queued"), // See INTEGRATION_STATUSES
  qbSyncError: text("qb_sync_error"),
  qbSyncedAt: timestamp("qb_synced_at"),
  // Failed payment details
  failureCode: varchar("failure_code"),
  failureMessage: text("failure_message"),
  failedAt: timestamp("failed_at"),
  // Retry tracking
  retryCount: integer("retry_count").default(0),
  maxRetries: integer("max_retries"),
  nextRetryAt: timestamp("next_retry_at"),
  lastRetryAt: timestamp("last_retry_at"),
  retryScheduleId: varchar("retry_schedule_id"),
  // Chargeback details
  chargebackId: varchar("chargeback_id"),
  chargebackReason: varchar("chargeback_reason"),
  chargebackAmount: decimal("chargeback_amount", { precision: 12, scale: 2 }),
  chargebackAt: timestamp("chargeback_at"),
  chargebackDeadline: date("chargeback_deadline"),
  chargebackStatus: varchar("chargeback_status"), // 'needs_response', 'under_review', 'won', 'lost'
  // Audit trail
  receivedBy: varchar("received_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
  
  // Manual/Offline payment tracking (TICKET 26)
  isManualEntry: boolean("is_manual_entry").default(false),
  enteredBy: varchar("entered_by").references(() => users.id),
  enteredAt: timestamp("entered_at"),
  attachmentUrl: varchar("attachment_url"),
  attachmentFilename: varchar("attachment_filename"),
  wireDetails: text("wire_details"),
  achManualDetails: text("ach_manual_details"),
  isDeleted: boolean("is_deleted").notNull().default(false),
  deletedAt: timestamp("deleted_at"),
  deletedByUserId: varchar("deleted_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  // Reversal tracking (TICKET: Payment Adjustment & Reversal Controls)
  isReversal: boolean("is_reversal").notNull().default(false),
  reversalOfPaymentId: varchar("reversal_of_payment_id"),
  reversalReason: text("reversal_reason"),
  isReversed: boolean("is_reversed").notNull().default(false),
  reversedAt: timestamp("reversed_at"),
  reversedByUserId: varchar("reversed_by_user_id"),
  // Adjustment tracking (edit amount / reassign)
  adjustmentReason: text("adjustment_reason"),
  previousCustomerId: varchar("previous_customer_id"),
  // Financial Record Locking
  isLocked: boolean("is_locked").notNull().default(false),
  lockedAt: timestamp("locked_at"),
  lockedBy: varchar("locked_by").references(() => users.id),
  lockSource: varchar("lock_source"), // 'deposit_locked', 'deposit_reconciled', 'manual'
  lockOverriddenAt: timestamp("lock_overridden_at"),
  lockOverriddenBy: varchar("lock_overridden_by").references(() => users.id),
  lockOverrideReason: text("lock_override_reason"),
});

// Payment Applications - how payments are applied to invoices
export const paymentApplications = pgTable("payment_applications", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  paymentId: varchar("payment_id").notNull().references(() => payments.id, { onDelete: 'cascade' }),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id),
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  appliedAt: timestamp("applied_at").defaultNow(),
  appliedBy: varchar("applied_by").references(() => users.id),
  notes: text("notes"),
  // Tolerance for auto-matching
  matchConfidence: decimal("match_confidence", { precision: 5, scale: 2 }), // 0-100
  matchMethod: varchar("match_method"), // 'invoice_number', 'amount', 'reference', 'manual'
  createdAt: timestamp("created_at").defaultNow(),
});

// Payment Retry Configuration - org-level retry rules
export const paymentRetryConfig = pgTable("payment_retry_config", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orgId: varchar("org_id").references(() => organizations.id, { onDelete: 'cascade' }),
  // Payment method specific rules
  paymentMethod: varchar("payment_method").notNull(), // 'credit_card', 'ach'
  // Retry schedule (days after failure)
  retryScheduleDays: integer("retry_schedule_days").array().notNull(), // e.g., [1, 3, 7] for card
  maxRetries: integer("max_retries").notNull().default(3),
  // Notification settings
  sendFailureEmail: boolean("send_failure_email").default(true),
  sendRetryNotice: boolean("send_retry_notice").default(true),
  includePayLink: boolean("include_pay_link").default(true),
  // Auto-retry or require manual action
  autoRetry: boolean("auto_retry").default(true),
  // Retry after final failure
  escalateToCollections: boolean("escalate_to_collections").default(false),
  markInvoiceOverdue: boolean("mark_invoice_overdue").default(true),
  // Timestamps
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
  createdBy: varchar("created_by").references(() => users.id),
});

// Payment Retry Attempts - tracks each retry attempt
export const paymentRetryAttempts = pgTable("payment_retry_attempts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  paymentId: varchar("payment_id").notNull().references(() => payments.id, { onDelete: 'cascade' }),
  // Attempt details
  attemptNumber: integer("attempt_number").notNull(),
  scheduledAt: timestamp("scheduled_at").notNull(),
  attemptedAt: timestamp("attempted_at"),
  // Result
  status: varchar("status").notNull().default("scheduled"), // 'scheduled', 'processing', 'succeeded', 'failed', 'cancelled'
  // Processor response
  processorResponse: text("processor_response"),
  failureCode: varchar("failure_code"),
  failureMessage: text("failure_message"),
  // New payment created on success
  newPaymentId: varchar("new_payment_id").references(() => payments.id),
  // Timestamps
  createdAt: timestamp("created_at").defaultNow(),
});

// Deposit Batches - group checks for bank deposit
export const depositBatches = pgTable("deposit_batches", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  batchNumber: varchar("batch_number").notNull().unique(),
  depositDate: date("deposit_date"),
  bankAccountName: varchar("bank_account_name"),
  bankAccountLast4: varchar("bank_account_last4"),
  depositMethod: varchar("deposit_method"),
  notes: text("notes"),
  itemCount: integer("item_count").default(0),
  totalAmount: decimal("total_amount", { precision: 12, scale: 2 }).default("0"),
  status: varchar("status").default("draft"),
  submittedAt: timestamp("submitted_at"),
  submittedBy: varchar("submitted_by").references(() => users.id),
  lockedAt: timestamp("locked_at"),
  lockedBy: varchar("locked_by").references(() => users.id),
  reconciledAt: timestamp("reconciled_at"),
  reconciledBy: varchar("reconciled_by").references(() => users.id),
  reconciliationReference: varchar("reconciliation_reference"),
  statementDate: date("statement_date"),
  actualDepositAmount: decimal("actual_deposit_amount", { precision: 12, scale: 2 }),
  discrepancyAmount: decimal("discrepancy_amount", { precision: 12, scale: 2 }),
  discrepancyNotes: text("discrepancy_notes"),
  qbDepositId: varchar("qb_deposit_id"),
  qbSyncStatus: varchar("qb_sync_status").default("not_queued"),
  qbSyncError: text("qb_sync_error"),
  qbSyncedAt: timestamp("qb_synced_at"),
  depositSlipUrl: varchar("deposit_slip_url"),
  createdBy: varchar("created_by").notNull().references(() => users.id),
  closedAt: timestamp("closed_at"),
  closedBy: varchar("closed_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

export const depositBatchAuditLog = pgTable("deposit_batch_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  batchId: varchar("batch_id").notNull().references(() => depositBatches.id, { onDelete: 'cascade' }),
  action: varchar("action").notNull(),
  fromStatus: varchar("from_status"),
  toStatus: varchar("to_status"),
  performedBy: varchar("performed_by").notNull().references(() => users.id),
  performedByName: varchar("performed_by_name"),
  metadata: jsonb("metadata"),
  createdAt: timestamp("created_at").defaultNow(),
});

// A/R Ledger Entries - double-entry tracking of all A/R activity
export const arLedgerEntries = pgTable("ar_ledger_entries", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Customer reference
  customerId: varchar("customer_id").notNull().references(() => customers.id),
  // Entry type and reference
  entryType: varchar("entry_type").notNull(), // 'invoice', 'payment', 'credit', 'adjustment', 'write_off', 'refund'
  referenceType: varchar("reference_type").notNull(), // 'invoice', 'payment', 'credit_memo', 'adjustment'
  referenceId: varchar("reference_id").notNull(), // ID of the referenced document
  // Entry details
  entryDate: date("entry_date").notNull(),
  description: text("description"),
  // Amounts (positive = debit/increase AR, negative = credit/decrease AR)
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  runningBalance: decimal("running_balance", { precision: 12, scale: 2 }), // Customer balance after this entry
  // Invoice reference (if applicable)
  invoiceId: varchar("invoice_id").references(() => invoices.id),
  // Audit trail
  createdBy: varchar("created_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
});

// Credit Memos - for credits and adjustments
export const creditMemos = pgTable("credit_memos", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Identification
  creditMemoNumber: varchar("credit_memo_number").notNull().unique(),
  customerId: varchar("customer_id").notNull().references(() => customers.id),
  // Reference to original invoice if applicable
  originalInvoiceId: varchar("original_invoice_id").references(() => invoices.id),
  // Credit details
  creditDate: date("credit_date").notNull(),
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  appliedAmount: decimal("applied_amount", { precision: 12, scale: 2 }).default("0"),
  remainingAmount: decimal("remaining_amount", { precision: 12, scale: 2 }),
  // Reason
  reasonCode: varchar("reason_code"), // 'billing_error', 'service_credit', 'dispute_resolution', 'price_adjustment', 'other'
  reason: text("reason").notNull(),
  // Status
  status: varchar("status").default("active"), // 'active', 'fully_applied', 'cancelled'
  // QuickBooks integration
  qbCreditMemoId: varchar("qb_credit_memo_id"),
  qbSyncStatus: varchar("qb_sync_status").default("not_queued"),
  qbSyncError: text("qb_sync_error"),
  qbSyncedAt: timestamp("qb_synced_at"),
  // Audit trail
  createdBy: varchar("created_by").notNull().references(() => users.id),
  approvedBy: varchar("approved_by").references(() => users.id),
  approvedAt: timestamp("approved_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Credit Memo Applications - how credits are applied to invoices
export const creditMemoApplications = pgTable("credit_memo_applications", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  creditMemoId: varchar("credit_memo_id").notNull().references(() => creditMemos.id, { onDelete: 'cascade' }),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id),
  amount: decimal("amount", { precision: 12, scale: 2 }).notNull(),
  appliedAt: timestamp("applied_at").defaultNow(),
  appliedBy: varchar("applied_by").references(() => users.id),
  notes: text("notes"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Customer Statements - account summaries for a date range
export const customerStatements = pgTable("customer_statements", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Statement identification
  statementNumber: varchar("statement_number").notNull().unique(),
  customerId: varchar("customer_id").notNull().references(() => customers.id),
  customerName: varchar("customer_name").notNull(),
  // Statement type and versioning
  statementType: varchar("statement_type").notNull().default("monthly"), // 'monthly', 'custom'
  snapshotVersion: integer("snapshot_version").default(1),
  // Statement period
  periodStartDate: date("period_start_date").notNull(),
  periodEndDate: date("period_end_date").notNull(),
  // Balance summary
  openingBalance: decimal("opening_balance", { precision: 12, scale: 2 }).notNull().default("0.00"),
  totalInvoicesIssued: decimal("total_invoices_issued", { precision: 12, scale: 2 }).notNull().default("0.00"),
  totalPaymentsReceived: decimal("total_payments_received", { precision: 12, scale: 2 }).notNull().default("0.00"),
  totalCreditsAdjustments: decimal("total_credits_adjustments", { precision: 12, scale: 2 }).notNull().default("0.00"),
  closingBalance: decimal("closing_balance", { precision: 12, scale: 2 }).notNull().default("0.00"),
  // Aging breakdown (as of statement date)
  agingCurrent: decimal("aging_current", { precision: 12, scale: 2 }).default("0.00"),
  aging1to30: decimal("aging_1_to_30", { precision: 12, scale: 2 }).default("0.00"),
  aging31to60: decimal("aging_31_to_60", { precision: 12, scale: 2 }).default("0.00"),
  aging61to90: decimal("aging_61_to_90", { precision: 12, scale: 2 }).default("0.00"),
  agingOver90: decimal("aging_over_90", { precision: 12, scale: 2 }).default("0.00"),
  // Invoice count by status
  invoiceCountDraft: integer("invoice_count_draft").default(0),
  invoiceCountSent: integer("invoice_count_sent").default(0),
  invoiceCountPaid: integer("invoice_count_paid").default(0),
  invoiceCountOverdue: integer("invoice_count_overdue").default(0),
  // Statement details (snapshot of transactions)
  transactionDetails: jsonb("transaction_details"), // Array of {type, date, reference, description, amount, balance}
  // Delivery tracking
  sentAt: timestamp("sent_at"),
  sentBy: varchar("sent_by").references(() => users.id),
  sentToEmails: jsonb("sent_to_emails"), // Array of email addresses
  // Audit trail
  createdBy: varchar("created_by").notNull().references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Invoice Email Log - track invoice delivery
export const invoiceEmailLog = pgTable("invoice_email_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id, { onDelete: 'cascade' }),
  // Recipients
  toEmails: jsonb("to_emails").notNull(), // Array of email addresses
  ccEmails: jsonb("cc_emails"), // Array of CC email addresses
  // Content
  subject: varchar("subject").notNull(),
  templateUsed: varchar("template_used"),
  // Delivery status
  status: varchar("status").default("queued"), // 'queued', 'sent', 'delivered', 'opened', 'bounced', 'failed'
  sentAt: timestamp("sent_at"),
  deliveredAt: timestamp("delivered_at"),
  openedAt: timestamp("opened_at"),
  bouncedAt: timestamp("bounced_at"),
  bounceReason: text("bounce_reason"),
  // Resend tracking
  resendCount: integer("resend_count").default(0),
  resendReason: text("resend_reason"),
  previousEmailId: varchar("previous_email_id"),
  // Email provider details
  emailProviderId: varchar("email_provider_id"), // Resend message ID
  // Audit trail
  sentBy: varchar("sent_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
});

// Integration Queue - for QuickBooks and other integrations
export const integrationQueue = pgTable("integration_queue", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Integration type and target
  integrationType: varchar("integration_type").notNull(), // 'quickbooks', 'stripe', 'other'
  operationType: varchar("operation_type").notNull(), // 'create', 'update', 'delete', 'sync'
  // Entity reference
  entityType: varchar("entity_type").notNull(), // 'invoice', 'payment', 'customer', 'deposit', 'credit_memo'
  entityId: varchar("entity_id").notNull(),
  // Status
  status: varchar("status").default("queued"), // 'queued', 'processing', 'completed', 'failed', 'cancelled'
  // Processing details
  priority: integer("priority").default(5), // 1 (highest) to 10 (lowest)
  retryCount: integer("retry_count").default(0),
  maxRetries: integer("max_retries").default(3),
  lastAttemptAt: timestamp("last_attempt_at"),
  nextAttemptAt: timestamp("next_attempt_at"),
  // Request/Response
  requestPayload: jsonb("request_payload"),
  responsePayload: jsonb("response_payload"),
  errorMessage: text("error_message"),
  errorDetails: jsonb("error_details"),
  // External reference (after successful sync)
  externalId: varchar("external_id"),
  // Audit trail
  queuedBy: varchar("queued_by").references(() => users.id),
  processedAt: timestamp("processed_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// QuickBooks Integration Settings - org-level QB credentials and account mappings
export const quickbooksSettings = pgTable("quickbooks_settings", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // QuickBooks connection
  realmId: varchar("realm_id"), // QuickBooks company ID
  accessToken: text("access_token"), // OAuth access token (encrypted in production)
  refreshToken: text("refresh_token"), // OAuth refresh token (encrypted in production)
  tokenExpiresAt: timestamp("token_expires_at"),
  // Connection status
  isConnected: boolean("is_connected").default(false),
  lastSyncAt: timestamp("last_sync_at"),
  connectionError: text("connection_error"),
  // Account mappings - AR and Income accounts
  arAccountId: varchar("ar_account_id"), // Accounts Receivable account in QB
  arAccountName: varchar("ar_account_name"),
  incomeAccountId: varchar("income_account_id"), // Default income account
  incomeAccountName: varchar("income_account_name"),
  // Additional account mappings
  feeAccountId: varchar("fee_account_id"), // For processing fees
  feeAccountName: varchar("fee_account_name"),
  taxAccountId: varchar("tax_account_id"), // For tax liability
  taxAccountName: varchar("tax_account_name"),
  depositAccountId: varchar("deposit_account_id"), // For bank deposits
  depositAccountName: varchar("deposit_account_name"),
  // Service type to QB Item mappings (JSON: { serviceType: { itemId, itemName } })
  itemMappings: jsonb("item_mappings"),
  // Sync configuration
  creditSyncMode: varchar("credit_sync_mode").default("credit_memo"), // 'credit_memo' or 'negative_line'
  autoSyncEnabled: boolean("auto_sync_enabled").default(false),
  syncInvoicesOnSend: boolean("sync_invoices_on_send").default(false),
  syncPaymentsOnReceive: boolean("sync_payments_on_receive").default(false),
  // Audit trail
  createdBy: varchar("created_by").references(() => users.id),
  updatedBy: varchar("updated_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Invoice disputes - track disputed invoices
export const invoiceDisputes = pgTable("invoice_disputes", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  invoiceId: varchar("invoice_id").notNull().references(() => invoices.id),
  invoiceLineItemId: varchar("invoice_line_item_id").references(() => invoiceLineItems.id),
  // Dispute details
  disputeDate: date("dispute_date").notNull(),
  disputedAmount: decimal("disputed_amount", { precision: 12, scale: 2 }).notNull(),
  reasonCode: varchar("reason_code"), // 'service_issue', 'billing_error', 'pricing_dispute', 'never_received', 'other'
  reason: text("reason").notNull(),
  // Status
  status: varchar("status").default("open"), // 'open', 'investigating', 'resolved', 'escalated', 'closed'
  resolution: text("resolution"),
  resolvedAmount: decimal("resolved_amount", { precision: 12, scale: 2 }),
  // Resolution actions
  creditMemoId: varchar("credit_memo_id").references(() => creditMemos.id),
  rebillInvoiceId: varchar("rebill_invoice_id").references(() => invoices.id),
  // Assignment
  assignedTo: varchar("assigned_to").references(() => users.id),
  // Audit trail
  reportedBy: varchar("reported_by").references(() => users.id),
  resolvedBy: varchar("resolved_by").references(() => users.id),
  resolvedAt: timestamp("resolved_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

