// Collections notes - internal notes and follow-up tracking for overdue invoices
export const collectionsNotes = pgTable("collections_notes", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Can be linked to customer (for customer-level notes) or invoice (for invoice-level notes)
  customerId: varchar("customer_id").references(() => customers.id),
  invoiceId: varchar("invoice_id").references(() => invoices.id, { onDelete: 'cascade' }),
  // Note content
  noteType: varchar("note_type").notNull().default("general"), // 'general', 'call_log', 'email_sent', 'promise_to_pay', 'escalation', 'resolution'
  content: text("content").notNull(),
  // Follow-up assignment
  assignedToUserId: varchar("assigned_to_user_id").references(() => users.id),
  followUpDate: date("follow_up_date"),
  followUpCompleted: boolean("follow_up_completed").default(false),
  followUpCompletedAt: timestamp("follow_up_completed_at"),
  // Suggested action tracking
  suggestedAction: varchar("suggested_action"), // 'send_reminder', 'call_customer', 'switch_ach_only', 'require_prepay', 'escalate_collections'
  actionTaken: varchar("action_taken"),
  actionTakenAt: timestamp("action_taken_at"),
  // Audit
  createdBy: varchar("created_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

