// Base expense schema with type-specific category validation
export const insertExpenseSchema = createInsertSchema(expenses).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
}).extend({
  expenseType: z.enum(EXPENSE_TYPES),
  category: z.string(),
  expenseDate: z.union([z.string(), z.date()]),
  amount: z.union([z.string(), z.number()]),
  description: z.string(),
  receiptUrl: z.string().optional(),
  driverId: z.string().optional().nullable(),
  employeeId: z.string().optional().nullable(),
  tripId: z.string().optional().nullable(),
  costCenter: z.string().optional().nullable(),
}).refine(
  (data) => {
    // Validate category based on expense type
    if (data.expenseType === "driver") {
      return DRIVER_EXPENSE_CATEGORIES.includes(data.category as DriverExpenseCategory);
    } else {
      return EMPLOYEE_EXPENSE_CATEGORIES.includes(data.category as EmployeeExpenseCategory);
    }
  },
  {
    message: "Invalid category for expense type",
    path: ["category"],
  }
).refine(
  (data) => {
    // If category is "other", description must be at least 15 characters
    if (data.category === "other") {
      return data.description && data.description.trim().length >= 15;
    }
    return true;
  },
  {
    message: "When 'Other' is selected, please provide a detailed description (at least 15 characters)",
    path: ["description"],
  }
).refine(
  (data) => {
    // Expense date cannot be in the future
    const expDate = typeof data.expenseDate === 'string' ? new Date(data.expenseDate) : data.expenseDate;
    const today = new Date();
    today.setHours(23, 59, 59, 999); // End of today
    return expDate <= today;
  },
  {
    message: "Expense date cannot be in the future",
    path: ["expenseDate"],
  }
).refine(
  (data) => {
    // Driver expenses must have driverId, Employee expenses must have employeeId
    if (data.expenseType === "driver") {
      return !!data.driverId;
    } else {
      return !!data.employeeId;
    }
  },
  {
    message: "Driver expenses require a driver ID, Employee expenses require an employee ID",
    path: ["driverId"],
  }
);

