const nullableNumber = z.union([
  z.literal("").transform(() => null),
  z.null(),
  z.number(),
  z.string().refine((val) => !isNaN(parseFloat(val)), { message: "Must be a valid number" })
    .transform((val) => parseFloat(val))
]).optional();

const nullableDate = z.union([
  z.literal("").transform(() => null),
  z.null(),
  z.date(),
  z.string().refine((val) => !isNaN(new Date(val).getTime()), { message: "Must be a valid date" })
    .transform((val) => new Date(val))
]).optional();

const coercedBoolean = z.union([
  z.boolean(),
  z.literal("true").transform(() => true),
  z.literal("false").transform(() => false),
  z.literal("1").transform(() => true),
  z.literal("0").transform(() => false),
]).optional();

