// ========================================
// SOCIAL MEDIA MODULE
// ========================================

// Social media platform types
export const socialPlatforms = ["facebook", "instagram", "linkedin", "twitter", "nextdoor"] as const;
export type SocialPlatform = typeof socialPlatforms[number];

export const socialPostStatuses = ["draft", "scheduled", "publishing", "published", "failed", "cancelled"] as const;
export type SocialPostStatus = typeof socialPostStatuses[number];

export const socialPostTypes = ["promotional", "job_posting", "company_news", "engagement", "other"] as const;
export type SocialPostType = typeof socialPostTypes[number];

// Social Platform Connections - stores OAuth tokens and connection info
export const socialPlatformConnections = pgTable("social_platform_connections", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  platform: varchar("platform").notNull(), // facebook, instagram, linkedin, twitter, nextdoor
  platformAccountId: varchar("platform_account_id"), // Page ID, Organization ID, etc.
  platformAccountName: varchar("platform_account_name"), // Display name of the connected account
  accessToken: text("access_token"), // Encrypted OAuth access token
  refreshToken: text("refresh_token"), // Encrypted refresh token if applicable
  tokenExpiresAt: timestamp("token_expires_at"), // When the access token expires
  scopes: text("scopes"), // Comma-separated list of granted scopes
  isActive: boolean("is_active").default(true),
  connectedById: varchar("connected_by_id").references(() => users.id),
  connectedAt: timestamp("connected_at").defaultNow(),
  lastUsedAt: timestamp("last_used_at"),
  metadata: jsonb("metadata"), // Platform-specific metadata (e.g., page category, follower count)
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Social Posts - main content table
export const socialPosts = pgTable("social_posts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  title: varchar("title"), // Internal title for organization
  content: text("content").notNull(), // The actual post content/caption
  postType: varchar("post_type").default("promotional"), // promotional, job_posting, company_news, engagement, other
  status: varchar("status").default("draft"), // draft, scheduled, publishing, published, failed, cancelled
  // Media attachments
  mediaUrls: jsonb("media_urls").$type<string[]>().default([]), // Array of image/video URLs
  mediaType: varchar("media_type"), // image, video, carousel, link
  linkUrl: varchar("link_url"), // Optional link to include in post
  linkPreviewTitle: varchar("link_preview_title"),
  linkPreviewDescription: text("link_preview_description"),
  // Platform targeting
  targetPlatforms: jsonb("target_platforms").$type<string[]>().default([]), // Which platforms to publish to
  platformSpecificContent: jsonb("platform_specific_content"), // Platform-specific variations { facebook: "...", instagram: "..." }
  // Scheduling
  scheduledFor: timestamp("scheduled_for"), // When to publish (null = draft)
  publishedAt: timestamp("published_at"), // When actually published
  // Related entities (optional links to job requisitions, products, etc.)
  relatedRequisitionId: varchar("related_requisition_id").references(() => jobRequisitions.id, { onDelete: 'set null' }),
  relatedEntityType: varchar("related_entity_type"), // requisition, product, service, etc.
  relatedEntityId: varchar("related_entity_id"),
  // AI assistance tracking
  aiGenerated: boolean("ai_generated").default(false),
  aiPromptUsed: text("ai_prompt_used"),
  // Metadata
  hashtags: jsonb("hashtags").$type<string[]>().default([]),
  // Audit
  createdById: varchar("created_by_id").references(() => users.id),
  updatedById: varchar("updated_by_id").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Social Publish Logs - tracks each publish attempt/result per platform
export const socialPublishLogs = pgTable("social_publish_logs", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  postId: varchar("post_id").notNull().references(() => socialPosts.id, { onDelete: 'cascade' }),
  platform: varchar("platform").notNull(), // facebook, instagram, etc.
  connectionId: varchar("connection_id").references(() => socialPlatformConnections.id),
  status: varchar("status").notNull(), // pending, publishing, published, failed
  externalPostId: varchar("external_post_id"), // The post ID on the external platform
  externalPostUrl: varchar("external_post_url"), // Direct link to the published post
  // Error tracking
  errorCode: varchar("error_code"),
  errorMessage: text("error_message"),
  retryCount: integer("retry_count").default(0),
  // Engagement metrics (can be updated later via API)
  likes: integer("likes").default(0),
  comments: integer("comments").default(0),
  shares: integer("shares").default(0),
  reach: integer("reach").default(0),
  impressions: integer("impressions").default(0),
  metricsUpdatedAt: timestamp("metrics_updated_at"),
  publishedAt: timestamp("published_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Social Post Templates - reusable content templates
export const socialPostTemplates = pgTable("social_post_templates", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  description: text("description"),
  templateType: varchar("template_type").notNull(), // job_posting, promotional, announcement, etc.
  content: text("content").notNull(), // Template with placeholders like {{job_title}}, {{location}}
  defaultHashtags: jsonb("default_hashtags").$type<string[]>().default([]),
  targetPlatforms: jsonb("target_platforms").$type<string[]>().default([]),
  isActive: boolean("is_active").default(true),
  createdById: varchar("created_by_id").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Social Media Insert Schemas
export const insertSocialPlatformConnectionSchema = createInsertSchema(socialPlatformConnections).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertSocialPostSchema = createInsertSchema(socialPosts).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export const insertSocialPublishLogSchema = createInsertSchema(socialPublishLogs).omit({
  id: true,
  createdAt: true,
});

export const insertSocialPostTemplateSchema = createInsertSchema(socialPostTemplates).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

// Social Media Types
export type InsertSocialPlatformConnection = z.infer<typeof insertSocialPlatformConnectionSchema>;
export type SocialPlatformConnection = typeof socialPlatformConnections.$inferSelect;

export type InsertSocialPost = z.infer<typeof insertSocialPostSchema>;
export type SocialPost = typeof socialPosts.$inferSelect;

export type InsertSocialPublishLog = z.infer<typeof insertSocialPublishLogSchema>;
export type SocialPublishLog = typeof socialPublishLogs.$inferSelect;

export type InsertSocialPostTemplate = z.infer<typeof insertSocialPostTemplateSchema>;
export type SocialPostTemplate = typeof socialPostTemplates.$inferSelect;

