// Claims MVP - Submission Schema (requires move linkage)
export const claimTypes = ["DAMAGE", "ACCIDENT", "INJURY", "PROPERTY", "OTHER"] as const;
export const claimSeverities = ["LOW", "MEDIUM", "HIGH", "CRITICAL"] as const;
// Claim Type (authoritative) — how the claim is being handled. Separate from
// Incident Type (nature of the incident, e.g. Tire/Wheel Damage) and from the
// legacy `claimType` column above (DAMAGE/ACCIDENT/etc, used only for
// GL-vs-Auto packet logic, never user-facing as "Claim Type"). DH-002340.
export const claimCategories = ["insurance_claim", "internal_claim"] as const;
export const claimCategoryOptions = [
  { value: "insurance_claim", label: "Insurance Claim" },
  { value: "internal_claim",  label: "Internal Claim" },
] as const;
export type ClaimCategory = typeof claimCategories[number];
export const claimIncidentTypeOptions = [
  { value: "bodily_injury_single",   label: "Bodily Injury – Single" },
  { value: "bodily_injury_multiple", label: "Bodily Injury – Multiple" },
  { value: "dod_rear_ended",         label: "DOD Rear-Ended – At Fault" },
  { value: "got_rear_ended",         label: "Got Rear-Ended – Not At Fault" },
  { value: "careless_driving",       label: "Careless Driving" },
  { value: "careless_parking",       label: "Careless Parking" },
  { value: "careless_reversing",     label: "Careless Reversing" },
  { value: "hit_and_run",            label: "Hit-and-Run" },
  { value: "road_debris",            label: "Road Debris" },
  { value: "tire_wheel_damage",      label: "Tire/Wheel Damage" },
  { value: "windshield",             label: "Windshield" },
  { value: "property_damage",        label: "Property Damage" },
  { value: "vandalism",              label: "Vandalism" },
  { value: "mechanical",             label: "Mechanical" },
  { value: "interior",               label: "Interior" },
  { value: "lost_item",              label: "Lost Item" },
  { value: "pre_existing_damage",    label: "Pre-Existing Damage" },
  { value: "force_majeure",          label: "Force Majeure Event" },
  { value: "unknown",                label: "Unknown" },
] as const;
export type ClaimIncidentType = typeof claimIncidentTypeOptions[number]["value"];
export const claimIncidentTypeValues = claimIncidentTypeOptions.map(
  ({ value }) => value
) as [ClaimIncidentType, ...ClaimIncidentType[]];

export function validateIncidentDate(dateStr: string): { valid: boolean; error?: string } {
  if (!dateStr || dateStr.trim() === "") {
    return { valid: false, error: "Incident date is required" };
  }
  const parsed = new Date(dateStr);
  if (isNaN(parsed.getTime())) {
    return { valid: false, error: "Invalid date format" };
  }
  const today = new Date();
  today.setHours(23, 59, 59, 999);
  if (parsed > today) {
    return { valid: false, error: "Incident date cannot be in the future" };
  }
  const fiveYearsAgo = new Date();
  fiveYearsAgo.setFullYear(fiveYearsAgo.getFullYear() - 5);
  fiveYearsAgo.setHours(0, 0, 0, 0);
  if (parsed < fiveYearsAgo) {
    return { valid: false, error: "Incident date cannot be more than 5 years in the past" };
  }
  return { valid: true };
}

export const submitClaimSchema = z.object({
  moveId: z.string().min(1, "Move is required"),
  // Claim Type (authoritative — Insurance Claim vs Internal Claim). DH-002340.
  claimCategory: z.enum(claimCategories, { required_error: "Claim type is required" }),
  incidentType: z.enum(claimIncidentTypeValues, { required_error: "Incident type is required" }),
  incidentDate: z.string().min(1, "Incident date is required").refine(
    (val) => validateIncidentDate(val).valid,
    (val) => ({ message: validateIncidentDate(val).error || "Invalid incident date" })
  ),
  incidentTime: z.string().optional(),
  driverId: z.string().min(1, "Driver is required"),
  customerId: z.string().optional().nullable(),
  description: z.string().min(10, "Description must be at least 10 characters"),
  severity: z.enum(claimSeverities, { required_error: "Severity is required" }),
  location: z.string().optional(),
});

export type SubmitClaimInput = z.infer<typeof submitClaimSchema>;
export type ClaimType = typeof claimTypes[number];
export type ClaimSeverity = typeof claimSeverities[number];

