// Risk bands for customer scoring
export const customerRiskBands = ["low", "medium", "high", "critical"] as const;

// Contract pressure flags (advisory)
export const contractPressureFlags = [
  "pricing_misaligned_with_risk",
  "contract_review_recommended",
  "exit_candidate"
] as const;

// Customer Risk Scores - Claims-calculated and owned risk metrics
export const customerRiskScores = pgTable("customer_risk_scores", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  customerId: varchar("customer_id").notNull().references(() => customers.id, { onDelete: 'cascade' }),
  // Rolling window metrics
  claimsPer1000Moves30d: decimal("claims_per_1000_moves_30d", { precision: 10, scale: 4 }),
  claimsPer1000Moves90d: decimal("claims_per_1000_moves_90d", { precision: 10, scale: 4 }),
  claimsPer1000Moves180d: decimal("claims_per_1000_moves_180d", { precision: 10, scale: 4 }),
  // Severity-weighted loss index
  severityWeightedLossIndex: decimal("severity_weighted_loss_index", { precision: 10, scale: 4 }),
  // Evidence dispute rate (if available)
  evidenceDisputeRate: decimal("evidence_dispute_rate", { precision: 5, scale: 4 }),
  // Normalized score (0-100, compared to system average)
  normalizedScore: decimal("normalized_score", { precision: 5, scale: 2 }),
  // Risk band
  riskBand: varchar("risk_band").notNull().default("low"), // One of customerRiskBands
  // Contract pressure flags (JSON array of applicable flags)
  contractPressureFlags: text("contract_pressure_flags"), // JSON array of contractPressureFlags
  // Supporting data for explainability
  totalClaims30d: integer("total_claims_30d").default(0),
  totalClaims90d: integer("total_claims_90d").default(0),
  totalClaims180d: integer("total_claims_180d").default(0),
  totalMoves30d: integer("total_moves_30d").default(0),
  totalMoves90d: integer("total_moves_90d").default(0),
  totalMoves180d: integer("total_moves_180d").default(0),
  totalClaimCost180d: decimal("total_claim_cost_180d", { precision: 12, scale: 2 }),
  // Trend tracking (delta from previous calculation)
  previousRiskBand: varchar("previous_risk_band"),
  riskBandChangedAt: timestamp("risk_band_changed_at"),
  scoreTrend: varchar("score_trend"), // improving, stable, worsening
  // Calculation metadata
  calculatedAt: timestamp("calculated_at").notNull().defaultNow(),
  systemAverageAtCalculation: decimal("system_average_at_calculation", { precision: 10, scale: 4 }),
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
});

export const insertCustomerRiskScoreSchema = createInsertSchema(customerRiskScores).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
  calculatedAt: true,
});

export type CustomerRiskScore = typeof customerRiskScores.$inferSelect;
export type InsertCustomerRiskScore = z.infer<typeof insertCustomerRiskScoreSchema>;
export type CustomerRiskBand = typeof customerRiskBands[number];
