// ── Account Departments — customer organizational structure per account ──────
export const accountDepartments = pgTable("account_departments", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  accountId: varchar("account_id").notNull().references(() => customers.id, { onDelete: 'cascade' }),
  name: varchar("name", { length: 255 }).notNull(),
  code: varchar("code", { length: 50 }),
  description: text("description"),
  sortOrder: integer("sort_order").notNull().default(0),
  isActive: boolean("is_active").notNull().default(true),
  isDefault: boolean("is_default").notNull().default(false),
  // ── Business Configuration (DH — Department Business Configuration) ─────────
  // Each nullable "override" field means: NULL = inherit from the parent Account.
  timezone: varchar("timezone"), // IANA tz string override; NULL inherits customers.timezone
  businessHours: text("business_hours"), // JSON: { "monday": { "enabled": true, "start": "08:00", "end": "17:00" }, ... }; NULL inherits customers.operatingHours
  useAccountHolidayCalendar: boolean("use_account_holiday_calendar").notNull().default(true),
  customHolidays: jsonb("custom_holidays"), // Array of { name, date, isPaid } used only when useAccountHolidayCalendar = false
  costCenter: varchar("cost_center"), // Optional accounting/billing code
  glCode: varchar("gl_code"), // Optional GL code
  defaultPromiseModel: varchar("default_promise_model"), // Future: department-level promise/SLA model
  spendApprovalThreshold: decimal("spend_approval_threshold", { precision: 10, scale: 2 }), // Future: dollar threshold requiring approval
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  createdByUserId: varchar("created_by_user_id").references(() => users.id, { onDelete: 'set null' }),
  updatedByUserId: varchar("updated_by_user_id").references(() => users.id, { onDelete: 'set null' }),
}, table => ({
  accountNameUnique: uniqueIndex("account_departments_account_name_unique").on(table.accountId, table.name),
}));

