// DRUG TEST NOTIFICATIONS (Claims Workflow)
// ============================================

export const DRUG_TEST_STATUS = ['PENDING', 'NOTIFIED', 'SCHEDULED', 'COMPLETED', 'CANCELLED', 'EXPIRED'] as const;
export type DrugTestStatus = typeof DRUG_TEST_STATUS[number];

export const DRUG_TEST_TRIGGER = ['ACCIDENT', 'INJURY', 'DOT_REQUIRED', 'RANDOM', 'POST_INCIDENT', 'REASONABLE_SUSPICION'] as const;
export type DrugTestTrigger = typeof DRUG_TEST_TRIGGER[number];

export const drugTestNotifications = pgTable("drug_test_notifications", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Link to claim/driver
  claimId: varchar("claim_id").references(() => accidents.id, { onDelete: 'set null' }),
  driverId: varchar("driver_id").references(() => users.id, { onDelete: 'cascade' }),
  // Trigger information
  triggerType: varchar("trigger_type").notNull(), // ACCIDENT, INJURY, DOT_REQUIRED, RANDOM, POST_INCIDENT, REASONABLE_SUSPICION
  triggerReason: text("trigger_reason"),
  // Status tracking
  status: varchar("status").notNull().default('PENDING'), // PENDING, NOTIFIED, SCHEDULED, COMPLETED, CANCELLED, EXPIRED
  // Notification details
  notificationSentAt: timestamp("notification_sent_at", { withTimezone: true }),
  notificationMethod: varchar("notification_method"), // EMAIL, SMS, PUSH, IN_APP
  notificationRecipients: text("notification_recipients"), // JSON array of email addresses
  // Scheduling
  scheduledDate: timestamp("scheduled_date", { withTimezone: true }),
  testLocation: varchar("test_location"),
  testProvider: varchar("test_provider"),
  // Completion
  completedAt: timestamp("completed_at", { withTimezone: true }),
  testResult: varchar("test_result"), // NEGATIVE, POSITIVE, INCONCLUSIVE, REFUSED
  resultDocumentUrl: varchar("result_document_url"),
  // Notes and audit
  notes: text("notes"),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
  // Deadline for test (typically 24-48 hours post-incident)
  deadlineAt: timestamp("deadline_at", { withTimezone: true }),
});

export const drugTestNotificationsRelations = relations(drugTestNotifications, ({ one }) => ({
  claim: one(accidents, {
    fields: [drugTestNotifications.claimId],
    references: [accidents.id],
  }),
  driver: one(users, {
    fields: [drugTestNotifications.driverId],
    references: [users.id],
  }),
  createdByUser: one(users, {
    fields: [drugTestNotifications.createdBy],
    references: [users.id],
  }),
}));

export const insertDrugTestNotificationSchema = createInsertSchema(drugTestNotifications).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type DrugTestNotification = typeof drugTestNotifications.$inferSelect;
export type InsertDrugTestNotification = z.infer<typeof insertDrugTestNotificationSchema>;

