// Time Entries - Driver timecards from ClockIn/ClockOut events
export const timeEntries = pgTable("time_entries", {
  id: serial("id").primaryKey(),
  driverId: varchar("driver_id").notNull(),
  startAt: timestamp("start_at", { withTimezone: true }).notNull(), // Clock-in time
  endAt: timestamp("end_at", { withTimezone: true }), // Clock-out time (nullable for open shifts)
  durationMinutes: integer("duration_minutes"), // Calculated duration
  marketId: varchar("market_id"), // Market for pay rules
  payPolicyId: varchar("pay_policy_id"), // Pay policy applied
  // Flags stored as JSON array
  flags: jsonb("flags").default(sql`'[]'::jsonb`), // Array of TimeEntryFlag values
  // Source event references - audit trail
  clockInEventId: varchar("clock_in_event_id").references(() => ingestedEvents.eventId),
  clockOutEventId: varchar("clock_out_event_id").references(() => ingestedEvents.eventId),
  // Geo location at clock-in
  clockInLat: real("clock_in_lat"),
  clockInLng: real("clock_in_lng"),
  // Geo location at clock-out
  clockOutLat: real("clock_out_lat"),
  clockOutLng: real("clock_out_lng"),
  // Payroll processing status
  payrollStatus: varchar("payroll_status").default("pending"), // pending, approved, exported, paid
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  driverIdIdx: index("time_entries_driver_id_idx").on(table.driverId),
  startAtIdx: index("time_entries_start_at_idx").on(table.startAt),
  driverStartIdx: index("time_entries_driver_start_idx").on(table.driverId, table.startAt),
  marketIdIdx: index("time_entries_market_id_idx").on(table.marketId),
  payrollStatusIdx: index("time_entries_payroll_status_idx").on(table.payrollStatus),
}));

export const insertTimeEntrySchema = createInsertSchema(timeEntries).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type TimeEntry = typeof timeEntries.$inferSelect;
export type InsertTimeEntry = z.infer<typeof insertTimeEntrySchema>;

// Timecard Exceptions - Flagged issues for payroll review
