// TICKET 24: Replay / Backfill Processor
// =====================================

// Replay job statuses
export const replayJobStatuses = [
  "pending",     // Job created, not yet started
  "running",     // Currently processing events
  "completed",   // All events processed successfully
  "failed",      // Job failed with errors
  "cancelled",   // Job was cancelled by user
] as const;

export type ReplayJobStatus = (typeof replayJobStatuses)[number];

// Replay Jobs - Track replay/backfill operations for event reprocessing
export const replayJobs = pgTable("replay_jobs", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Who initiated the replay
  createdBy: varchar("created_by").notNull().references(() => users.id),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  // Time range for replay
  fromTimestamp: timestamp("from_timestamp", { withTimezone: true }).notNull(),
  toTimestamp: timestamp("to_timestamp", { withTimezone: true }).notNull(),
  // Optional filters (stored as JSON for flexibility)
  filters: jsonb("filters").notNull().default(sql`'{}'::jsonb`), // { event_type?: string, move_id?: string, driver_id?: string }
  // Dry run mode - analyze without making changes
  dryRun: boolean("dry_run").notNull().default(false),
  // Job status and timing
  status: varchar("status").notNull().default("pending"), // One of replayJobStatuses
  startedAt: timestamp("started_at", { withTimezone: true }),
  completedAt: timestamp("completed_at", { withTimezone: true }),
  // Processing counts
  totalEvents: integer("total_events").notNull().default(0),
  processedCount: integer("processed_count").notNull().default(0),
  skippedCount: integer("skipped_count").notNull().default(0), // Already processed events
  failedCount: integer("failed_count").notNull().default(0),
  // Error tracking
  errorSummary: text("error_summary"),
  lastError: text("last_error"),
  // Progress tracking
  currentEventId: varchar("current_event_id"), // Last processed event for resume
  progressPercent: integer("progress_percent").notNull().default(0),
}, (table) => ({
  statusIdx: index("replay_jobs_status_idx").on(table.status),
  createdByIdx: index("replay_jobs_created_by_idx").on(table.createdBy),
  createdAtIdx: index("replay_jobs_created_at_idx").on(table.createdAt),
}));

export const insertReplayJobSchema = createInsertSchema(replayJobs).omit({
  id: true,
  createdAt: true,
  startedAt: true,
  completedAt: true,
  totalEvents: true,
  processedCount: true,
  skippedCount: true,
  failedCount: true,
  errorSummary: true,
  lastError: true,
  currentEventId: true,
  progressPercent: true,
});

export type ReplayJob = typeof replayJobs.$inferSelect;
export type InsertReplayJob = z.infer<typeof insertReplayJobSchema>;

