// Readiness status enum for driver deployment gate
export const readinessStatusEnum = pgEnum("readiness_status", ["not_ready", "in_review", "ready"]);
export type ReadinessStatus = "not_ready" | "in_review" | "ready";

export const recruitingApplications = pgTable("recruiting_applications", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Core relationships
  candidateId: varchar("candidate_id").notNull().references(() => recruitingCandidates.id, { onDelete: 'cascade' }),
  requisitionId: varchar("requisition_id").notNull().references(() => recruitingRequisitions.id, { onDelete: 'cascade' }),
  // Current stage (denormalized for query performance)
  currentStage: varchar("current_stage").notNull().default("applied"), // One of applicationStages
  currentStageEnteredAt: timestamp("current_stage_entered_at", { withTimezone: true }).notNull().defaultNow(),
  // Ownership
  ownerId: varchar("owner_id").references(() => users.id, { onDelete: 'set null' }), // Assigned recruiter
  // Disposition (final outcome)
  disposition: varchar("disposition"), // One of applicationDispositions
  dispositionReason: text("disposition_reason"),
  disposedAt: timestamp("disposed_at", { withTimezone: true }),
  disposedBy: varchar("disposed_by").references(() => users.id, { onDelete: 'set null' }),
  // Scheduling
  nextScheduledAction: varchar("next_scheduled_action"),
  nextScheduledAt: timestamp("next_scheduled_at", { withTimezone: true }),
  // =============================================
  // READINESS SCORE - Deployable Driver Gate
  // =============================================
  readinessStatus: readinessStatusEnum("readiness_status").notNull().default("not_ready"),
  readinessScore: integer("readiness_score").notNull().default(0), // 0-100
  readinessReasons: jsonb("readiness_reasons"), // Array of {rule, passed, reason, weight}
  readinessLastCalculatedAt: timestamp("readiness_last_calculated_at", { withTimezone: true }),
  // Readiness input flags (v1 - manual/imported, will be automated later)
  consentCaptured: boolean("consent_captured").default(false),
  docsComplete: boolean("docs_complete").default(false),
  backgroundCheckStatus: varchar("background_check_status").default("pending"), // pending, in_progress, passed, failed
  backgroundStatus: varchar("background_status").default("none"), // none, requested, in_progress, passed, failed (alias for compatibility)
  lastContactedAt: timestamp("last_contacted_at", { withTimezone: true }),
  lastResponseAt: timestamp("last_response_at", { withTimezone: true }),
  // State-Specific Compliance
  workState: varchar("work_state"), // State code for compliance (NY, CA, TX, etc.)
  complianceStatus: varchar("compliance_status").default("pending"), // pending, passed, blocked, waived
  complianceBlockedReason: text("compliance_blocked_reason"),
  // Notes
  internalNotes: text("internal_notes"),
  // Geo-Eligibility (computed from candidate ZIP + requisition market)
  distanceMiles: decimal("distance_miles", { precision: 8, scale: 1 }), // Distance from candidate to requisition market
  geoEligible: boolean("geo_eligible"), // true = in range, false = out of range, null = unknown
  geoCalculatedAt: timestamp("geo_calculated_at", { withTimezone: true }),
  // License Eligibility (computed from candidate license + requisition requirements)
  licenseEligible: boolean("license_eligible"), // true = meets requirements, false = does not, null = unknown/no requirements
  licenseMismatchReason: text("license_mismatch_reason"), // Human-readable reason for mismatch
  licenseCheckedAt: timestamp("license_checked_at", { withTimezone: true }),
  // Metadata
  appliedAt: timestamp("applied_at", { withTimezone: true }).notNull().defaultNow(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  updatedBy: varchar("updated_by").references(() => users.id, { onDelete: 'set null' }),
  // Soft Delete / Archival
  isArchived: boolean("is_archived").notNull().default(false),
  archivedAt: timestamp("archived_at", { withTimezone: true }),
  archivedBy: varchar("archived_by").references(() => users.id, { onDelete: 'set null' }),
  archiveReason: text("archive_reason"),
  // Reactivation / Rehire Tracking
  isRehire: boolean("is_rehire").notNull().default(false),
  previousApplicationId: varchar("previous_application_id"), // Link to prior application if rehire
  reactivatedAt: timestamp("reactivated_at", { withTimezone: true }),
  reactivatedBy: varchar("reactivated_by").references(() => users.id, { onDelete: 'set null' }),
  reactivationReason: text("reactivation_reason"),
  // Source Attribution (Ticket 23)
  source: varchar("source", { length: 50 }), // Where this specific application came from
  sourceDetails: text("source_details"),     // Free-text: referrer name, specific ad, etc.
  // Withdrawal / No-Show Tracking
  withdrawnAt: timestamp("withdrawn_at", { withTimezone: true }),
  withdrawnBy: varchar("withdrawn_by").references(() => users.id, { onDelete: 'set null' }),
  withdrawnReason: text("withdrawn_reason"),
  withdrawalSource: varchar("withdrawal_source"), // candidate, recruiter, system
  noShowAt: timestamp("no_show_at", { withTimezone: true }),
  noShowBy: varchar("no_show_by").references(() => users.id, { onDelete: 'set null' }),
  noShowReason: text("no_show_reason"),
  noShowInterviewId: varchar("no_show_interview_id"), // Link to specific interview
  excludeFromMetrics: boolean("exclude_from_metrics").default(false), // Configurable exclusion from funnel calculations
  // =============================================
  // AI PRE-SCREEN SCORING
  // =============================================
  aiPrescreenScore: integer("ai_prescreen_score"), // 0-100
  aiPrescreenRecommendation: varchar("ai_prescreen_recommendation"), // advance | review | reject_recommended
  aiPrescreenSummary: text("ai_prescreen_summary"),
  aiPrescreenGeneratedAt: timestamp("ai_prescreen_generated_at", { withTimezone: true }),
  // =============================================
  // AI RED-FLAG RULES ENGINE
  // =============================================
  aiRedFlags: jsonb("ai_red_flags"), // RedFlag[] — detected by rules engine
  redFlagOverrides: jsonb("red_flag_overrides"), // RedFlagOverride[] — recruiter dismissals
  aiRedFlagsDetectedAt: timestamp("ai_red_flags_detected_at", { withTimezone: true }),
  // =============================================
  // AI SCREENING REVIEW SUMMARY (Ticket 14)
  // =============================================
  aiScreeningReview: jsonb("ai_screening_review"), // ScreeningReviewResult — generated after all 3 results arrive
  aiScreeningReviewGeneratedAt: timestamp("ai_screening_review_generated_at", { withTimezone: true }),
  aiScreeningReviewGenerating: boolean("ai_screening_review_generating").default(false),
  // =============================================
  // RECRUITER APPROVAL GATE (Ticket 09)
  // =============================================
  recruiterDecision: varchar("recruiter_decision"), // approved_for_interview | hold | reject | null
  recruiterDecisionAt: timestamp("recruiter_decision_at", { withTimezone: true }),
  recruiterDecisionBy: varchar("recruiter_decision_by").references(() => users.id, { onDelete: 'set null' }),
  recruiterDecisionNote: text("recruiter_decision_note"),

  // PRE-OFFER APPROVAL GATE (Ticket 15)
  // =============================================
  preOfferDecision: varchar("pre_offer_decision"), // approved_for_offer | decline_after_screening | null
  preOfferDecisionAt: timestamp("pre_offer_decision_at", { withTimezone: true }),
  preOfferDecisionBy: varchar("pre_offer_decision_by").references(() => users.id, { onDelete: 'set null' }),
  preOfferDecisionNote: text("pre_offer_decision_note"),
}, (table) => ({
  // Uniqueness constraint: one application per candidate per requisition
  candidateRequisitionUnique: uniqueIndex("recruiting_applications_candidate_requisition_idx").on(table.candidateId, table.requisitionId),
  // Query performance indexes
  requisitionIdx: index("recruiting_applications_requisition_idx").on(table.requisitionId),
  currentStageIdx: index("recruiting_applications_current_stage_idx").on(table.currentStage),
  updatedAtIdx: index("recruiting_applications_updated_at_idx").on(table.updatedAt),
  ownerIdx: index("recruiting_applications_owner_idx").on(table.ownerId),
  dispositionIdx: index("recruiting_applications_disposition_idx").on(table.disposition),
  // Readiness indexes
  readinessStatusIdx: index("recruiting_applications_readiness_status_idx").on(table.readinessStatus),
  readinessScoreIdx: index("recruiting_applications_readiness_score_idx").on(table.readinessScore),
  // Soft delete index
  isArchivedIdx: index("recruiting_applications_is_archived_idx").on(table.isArchived),
  // Composite indexes for pipeline performance optimization
  stageArchivedIdx: index("recruiting_applications_stage_archived_idx").on(table.currentStage, table.isArchived),
  requisitionStageIdx: index("recruiting_applications_requisition_stage_idx").on(table.requisitionId, table.currentStage),
  stageReadinessIdx: index("recruiting_applications_stage_readiness_idx").on(table.currentStage, table.readinessStatus),
  archivedUpdatedIdx: index("recruiting_applications_archived_updated_idx").on(table.isArchived, table.updatedAt),
}));

