// ============================================================================
// RECRUITING CANDIDATE MERGES - Track merged candidate records
// ============================================================================

export const duplicateMatchTypeEnum = pgEnum("duplicate_match_type", [
  "exact_email",
  "exact_phone",
  "fuzzy_name_email",
  "fuzzy_name_phone"
]);
export type DuplicateMatchType = "exact_email" | "exact_phone" | "fuzzy_name_email" | "fuzzy_name_phone";

export const mergeStatusEnum = pgEnum("merge_status", [
  "pending",
  "completed",
  "reversed"
]);
export type MergeStatus = "pending" | "completed" | "reversed";

export const recruitingCandidateMerges = pgTable("recruiting_candidate_merges", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Source = candidate being merged away (marked as "merged")
  sourceCandidateId: varchar("source_candidate_id").notNull().references(() => recruitingCandidates.id, { onDelete: 'restrict' }),
  // Target = primary candidate (receives all data)
  targetCandidateId: varchar("target_candidate_id").notNull().references(() => recruitingCandidates.id, { onDelete: 'restrict' }),
  // Match metadata
  matchType: duplicateMatchTypeEnum("match_type").notNull(),
  matchConfidence: integer("match_confidence").notNull().default(100), // 0-100 percentage
  matchReasons: text("match_reasons"), // JSON array of match reasons
  // Status
  status: mergeStatusEnum("status").notNull().default("completed"),
  // Full snapshots for audit/reversibility
  sourceSnapshotBefore: text("source_snapshot_before").notNull(), // JSON of source candidate before merge
  targetSnapshotBefore: text("target_snapshot_before").notNull(), // JSON of target candidate before merge
  targetSnapshotAfter: text("target_snapshot_after").notNull(), // JSON of target candidate after merge
  // Related entities moved
  applicationsMoved: text("applications_moved"), // JSON array of application IDs
  documentsMoved: text("documents_moved"), // JSON array of document IDs
  tagsMoved: text("tags_moved"), // JSON array of tag IDs
  communicationsMoved: text("communications_moved"), // JSON array of communication IDs
  // Actor
  mergedBy: varchar("merged_by").notNull().references(() => users.id, { onDelete: 'set null' }),
  mergedByEmail: varchar("merged_by_email").notNull(),
  // Timestamps
  mergedAt: timestamp("merged_at", { withTimezone: true }).notNull().defaultNow(),
  reversedAt: timestamp("reversed_at", { withTimezone: true }),
  reversedBy: varchar("reversed_by").references(() => users.id, { onDelete: 'set null' }),
  // Notes
  mergeNotes: text("merge_notes"),
}, (table) => ({
  sourceCandidateIdx: index("recruiting_merge_source_idx").on(table.sourceCandidateId),
  targetCandidateIdx: index("recruiting_merge_target_idx").on(table.targetCandidateId),
  mergedAtIdx: index("recruiting_merge_merged_at_idx").on(table.mergedAt),
  statusIdx: index("recruiting_merge_status_idx").on(table.status),
}));

export const insertRecruitingCandidateMergeSchema = createInsertSchema(recruitingCandidateMerges).omit({
  id: true,
  mergedAt: true,
  reversedAt: true,
});

export type RecruitingCandidateMerge = typeof recruitingCandidateMerges.$inferSelect;
export type InsertRecruitingCandidateMerge = z.infer<typeof insertRecruitingCandidateMergeSchema>;

