// Note entity types
export const recruitingNoteEntityTypes = ['candidate', 'application', 'requisition'] as const;
export type RecruitingNoteEntityType = typeof recruitingNoteEntityTypes[number];

// Note visibility levels - controls who can see the note
export const recruitingNoteVisibilityTypes = ['recruiter-only', 'hiring-team', 'admin-only'] as const;
export type RecruitingNoteVisibility = typeof recruitingNoteVisibilityTypes[number];

export const recruitingNotes = pgTable("recruiting_notes", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Entity reference (polymorphic - candidate, application, or requisition)
  entityType: varchar("entity_type").notNull(), // One of recruitingNoteEntityTypes
  entityId: varchar("entity_id").notNull(), // ID of the entity
  // Author
  authorId: varchar("author_id").notNull().references(() => users.id, { onDelete: 'set null' }),
  authorEmail: varchar("author_email").notNull(), // Denormalized for display
  authorName: varchar("author_name"), // Denormalized for display
  // Content
  body: text("body").notNull(),
  // Visibility level: recruiter-only, hiring-team, admin-only
  visibility: varchar("visibility").notNull().default('recruiter-only'),
  // @mentions - stored as array of user IDs mentioned in the note
  mentionedUserIds: text("mentioned_user_ids").array().default(sql`ARRAY[]::text[]`),
  // Edit tracking
  isEdited: boolean("is_edited").notNull().default(false),
  editedAt: timestamp("edited_at", { withTimezone: true }),
  editedBy: varchar("edited_by").references(() => users.id, { onDelete: 'set null' }),
  originalBody: text("original_body"), // Stored when edited for audit trail
  // Timestamps
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  // Soft delete
  isDeleted: boolean("is_deleted").notNull().default(false),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
  deletedBy: varchar("deleted_by").references(() => users.id, { onDelete: 'set null' }),
}, (table) => ({
  entityIdx: index("recruiting_notes_entity_idx").on(table.entityType, table.entityId),
  authorIdx: index("recruiting_notes_author_idx").on(table.authorId),
  createdAtIdx: index("recruiting_notes_created_at_idx").on(table.createdAt),
  visibilityIdx: index("recruiting_notes_visibility_idx").on(table.visibility),
}));

export const insertRecruitingNoteSchema = createInsertSchema(recruitingNotes).omit({
  id: true,
  isEdited: true,
  editedAt: true,
  editedBy: true,
  originalBody: true,
  createdAt: true,
  updatedAt: true,
  isDeleted: true,
  deletedAt: true,
  deletedBy: true,
});

export const updateRecruitingNoteSchema = createInsertSchema(recruitingNotes).pick({
  body: true,
  visibility: true,
  mentionedUserIds: true,
}).partial();

export type RecruitingNote = typeof recruitingNotes.$inferSelect;
export type InsertRecruitingNote = z.infer<typeof insertRecruitingNoteSchema>;
export type UpdateRecruitingNote = z.infer<typeof updateRecruitingNoteSchema>;

