// ============================================================================

// Workflow status
export const workflowStatusEnum = pgEnum("workflow_status", ["active", "archived", "draft"]);
export type WorkflowStatus = "active" | "archived" | "draft";

// ============================================================================
// RECRUITING WORKFLOWS - Workflow Templates
// ============================================================================

export const recruitingWorkflows = pgTable("recruiting_workflows", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Identity
  name: varchar("name").notNull(), // "Standard Driver Pipeline", "IC Fast Track"
  description: text("description"),
  // Template targeting
  market: varchar("market"), // Null = all markets
  workerType: workerTypeEnum("worker_type"), // Null = all worker types
  // Status
  status: workflowStatusEnum("status").default("draft"),
  isDefault: boolean("is_default").default(false), // Fallback workflow
  // Versioning
  version: integer("version").default(1),
  // Decommission / Retirement
  isRetired: boolean("is_retired").notNull().default(false),
  retiredAt: timestamp("retired_at", { withTimezone: true }),
  retiredBy: varchar("retired_by").references(() => users.id, { onDelete: 'set null' }),
  retiredReason: text("retired_reason"),
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  updatedBy: varchar("updated_by").references(() => users.id, { onDelete: 'set null' }),
}, (table) => ({
  statusIdx: index("recruiting_workflows_status_idx").on(table.status),
  marketIdx: index("recruiting_workflows_market_idx").on(table.market),
  workerTypeIdx: index("recruiting_workflows_worker_type_idx").on(table.workerType),
  isDefaultIdx: index("recruiting_workflows_is_default_idx").on(table.isDefault),
  isRetiredIdx: index("recruiting_workflows_is_retired_idx").on(table.isRetired),
}));

export const insertRecruitingWorkflowSchema = createInsertSchema(recruitingWorkflows).omit({
  id: true,
  version: true,
  createdAt: true,
  updatedAt: true,
  retiredAt: true,
  retiredBy: true,
});

export type RecruitingWorkflow = typeof recruitingWorkflows.$inferSelect;
export type InsertRecruitingWorkflow = z.infer<typeof insertRecruitingWorkflowSchema>;

// ============================================================================
// RECRUITING WORKFLOW STAGES - Stages Within a Workflow
// ============================================================================

export const recruitingWorkflowStages = pgTable("recruiting_workflow_stages", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Parent workflow
  workflowId: varchar("workflow_id").notNull().references(() => recruitingWorkflows.id, { onDelete: 'cascade' }),
  // Stage identity
  stageKey: varchar("stage_key").notNull(), // One of applicationStages
  displayName: varchar("display_name").notNull(), // Human-readable name
  description: text("description"),
  // Ordering
  sortOrder: integer("sort_order").notNull().default(0),
  // SLA configuration
  stageSlaHours: integer("stage_sla_hours"), // Max hours in this stage before SLA breach
  // Stage properties
  isInitial: boolean("is_initial").default(false), // Entry stage
  isTerminal: boolean("is_terminal").default(false), // Exit stage (hired/rejected/withdrawn)
  requiresApproval: boolean("requires_approval").default(false),
  // UI hints
  color: varchar("color"), // Kanban column color
  icon: varchar("icon"), // Lucide icon name
  // Decommission / Retirement
  isRetired: boolean("is_retired").notNull().default(false),
  retiredAt: timestamp("retired_at", { withTimezone: true }),
  retiredBy: varchar("retired_by"),
  retiredReason: text("retired_reason"),
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => ({
  workflowIdx: index("recruiting_workflow_stages_workflow_idx").on(table.workflowId),
  stageKeyIdx: index("recruiting_workflow_stages_stage_key_idx").on(table.stageKey),
  sortOrderIdx: index("recruiting_workflow_stages_sort_order_idx").on(table.sortOrder),
  // Unique stage key per workflow
  workflowStageUnique: uniqueIndex("recruiting_workflow_stages_workflow_stage_unique").on(table.workflowId, table.stageKey),
  isRetiredIdx: index("recruiting_workflow_stages_is_retired_idx").on(table.isRetired),
}));

export const insertRecruitingWorkflowStageSchema = createInsertSchema(recruitingWorkflowStages).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
  retiredAt: true,
  retiredBy: true,
});

export type RecruitingWorkflowStage = typeof recruitingWorkflowStages.$inferSelect;
export type InsertRecruitingWorkflowStage = z.infer<typeof insertRecruitingWorkflowStageSchema>;

// ============================================================================
// RECRUITING WORKFLOW TRANSITIONS - Allowed Stage Transitions
// ============================================================================

export const recruitingWorkflowTransitions = pgTable("recruiting_workflow_transitions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Parent workflow
  workflowId: varchar("workflow_id").notNull().references(() => recruitingWorkflows.id, { onDelete: 'cascade' }),
  // Transition definition
  fromStageId: varchar("from_stage_id").notNull().references(() => recruitingWorkflowStages.id, { onDelete: 'cascade' }),
  toStageId: varchar("to_stage_id").notNull().references(() => recruitingWorkflowStages.id, { onDelete: 'cascade' }),
  // Transition properties
  name: varchar("name"), // "Advance to Interview", "Reject Candidate"
  requiresReason: boolean("requires_reason").default(false),
  requiresApproval: boolean("requires_approval").default(false),
  // Automation
  autoTriggerCondition: text("auto_trigger_condition"), // JSON condition for auto-transitions
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => ({
  workflowIdx: index("recruiting_workflow_transitions_workflow_idx").on(table.workflowId),
  fromStageIdx: index("recruiting_workflow_transitions_from_stage_idx").on(table.fromStageId),
  toStageIdx: index("recruiting_workflow_transitions_to_stage_idx").on(table.toStageId),
  // Unique transition per workflow
  transitionUnique: uniqueIndex("recruiting_workflow_transitions_unique").on(table.workflowId, table.fromStageId, table.toStageId),
}));

export const insertRecruitingWorkflowTransitionSchema = createInsertSchema(recruitingWorkflowTransitions).omit({
  id: true,
  createdAt: true,
});

export type RecruitingWorkflowTransition = typeof recruitingWorkflowTransitions.$inferSelect;
export type InsertRecruitingWorkflowTransition = z.infer<typeof insertRecruitingWorkflowTransitionSchema>;

// ============================================================================
// RECRUITING WORKFLOW RELATIONS
// ============================================================================

export const recruitingWorkflowsRelations = relations(recruitingWorkflows, ({ many, one }) => ({
  stages: many(recruitingWorkflowStages),
  transitions: many(recruitingWorkflowTransitions),
  requisitions: many(recruitingRequisitions),
  createdByUser: one(users, {
    fields: [recruitingWorkflows.createdBy],
    references: [users.id],
  }),
}));

export const recruitingWorkflowStagesRelations = relations(recruitingWorkflowStages, ({ one, many }) => ({
  workflow: one(recruitingWorkflows, {
    fields: [recruitingWorkflowStages.workflowId],
    references: [recruitingWorkflows.id],
  }),
  transitionsFrom: many(recruitingWorkflowTransitions, { relationName: "fromStage" }),
  transitionsTo: many(recruitingWorkflowTransitions, { relationName: "toStage" }),
}));

export const recruitingWorkflowTransitionsRelations = relations(recruitingWorkflowTransitions, ({ one }) => ({
  workflow: one(recruitingWorkflows, {
    fields: [recruitingWorkflowTransitions.workflowId],
    references: [recruitingWorkflows.id],
  }),
  fromStage: one(recruitingWorkflowStages, {
    fields: [recruitingWorkflowTransitions.fromStageId],
    references: [recruitingWorkflowStages.id],
    relationName: "fromStage",
  }),
  toStage: one(recruitingWorkflowStages, {
    fields: [recruitingWorkflowTransitions.toStageId],
    references: [recruitingWorkflowStages.id],
    relationName: "toStage",
  }),
}));

// ============================================================================
// RECRUITING CALENDAR CONNECTIONS - OAuth Connections per Recruiter
// ============================================================================

export const calendarProviderEnum = pgEnum("calendar_provider", ["google", "microsoft"]);
export type CalendarProvider = "google" | "microsoft";

export const calendarSyncStatusEnum = pgEnum("calendar_sync_status", ["active", "expired", "error", "disconnected"]);
export type CalendarSyncStatus = "active" | "expired" | "error" | "disconnected";

export const recruitingCalendarConnections = pgTable("recruiting_calendar_connections", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // User who connected the calendar
  userId: varchar("user_id").notNull().references(() => users.id, { onDelete: 'cascade' }),
  // Calendar provider
  provider: calendarProviderEnum("provider").notNull(),
  // OAuth tokens (encrypted in production)
  accessToken: text("access_token"),
  refreshToken: text("refresh_token"),
  tokenExpiresAt: timestamp("token_expires_at", { withTimezone: true }),
  // Calendar details
  calendarId: varchar("calendar_id"), // Primary calendar ID from provider
  calendarEmail: varchar("calendar_email"),
  // Sync status
  syncStatus: calendarSyncStatusEnum("sync_status").notNull().default("disconnected"),
  lastSyncAt: timestamp("last_sync_at", { withTimezone: true }),
  syncError: text("sync_error"),
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => ({
  userIdx: index("recruiting_calendar_connections_user_idx").on(table.userId),
  userProviderUnique: uniqueIndex("recruiting_calendar_connections_user_provider_idx").on(table.userId, table.provider),
}));

export const insertRecruitingCalendarConnectionSchema = createInsertSchema(recruitingCalendarConnections).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type RecruitingCalendarConnection = typeof recruitingCalendarConnections.$inferSelect;
export type InsertRecruitingCalendarConnection = z.infer<typeof insertRecruitingCalendarConnectionSchema>;

// ============================================================================
// RECRUITING INTERVIEWS - Interview Scheduling Records
// ============================================================================

export const interviewStatusEnum = pgEnum("interview_status", ["scheduled", "confirmed", "completed", "cancelled", "no_show"]);
export type InterviewStatus = "scheduled" | "confirmed" | "completed" | "cancelled" | "no_show";

export const interviewTypeEnum = pgEnum("interview_type", ["phone", "video", "in_person"]);
export type RecruitingInterviewType = "phone" | "video" | "in_person";

export const recruitingInterviews = pgTable("recruiting_interviews", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Application reference
  applicationId: varchar("application_id").notNull().references(() => recruitingApplications.id, { onDelete: 'cascade' }),
  // Interview details
  title: varchar("title").notNull(),
  interviewType: interviewTypeEnum("interview_type").notNull().default("video"),
  status: interviewStatusEnum("status").notNull().default("scheduled"),
  // Scheduling
  startTime: timestamp("start_time", { withTimezone: true }).notNull(),
  endTime: timestamp("end_time", { withTimezone: true }).notNull(),
  durationMinutes: integer("duration_minutes").notNull().default(30),
  timezone: varchar("timezone").default("America/Chicago"),
  // Location/meeting
  location: varchar("location"), // Physical address for in-person
  meetingLink: text("meeting_link"), // Video call URL
  meetingId: varchar("meeting_id"), // Provider meeting ID
  // Interviewer(s)
  interviewerIds: jsonb("interviewer_ids"), // Array of user IDs
  organizerId: varchar("organizer_id").references(() => users.id, { onDelete: 'set null' }),
  // Calendar sync
  calendarEventId: varchar("calendar_event_id"), // ID from calendar provider
  calendarConnectionId: varchar("calendar_connection_id").references(() => recruitingCalendarConnections.id, { onDelete: 'set null' }),
  // Notes and feedback
  notes: text("notes"),
  candidateFeedback: text("candidate_feedback"),
  interviewerFeedback: jsonb("interviewer_feedback"), // {userId: feedback}
  // Outcome
  outcome: varchar("outcome"), // passed, failed, needs_followup
  outcomeNotes: text("outcome_notes"),
  // =============================================
  // INTERVIEW DECISION WORKFLOW (Ticket 10)
  // =============================================
  interviewerDecision: varchar("interviewer_decision"), // proceed_to_pre_hire | hold | decline
  interviewerDecisionNote: text("interviewer_decision_note"), // Required notes for decision
  interviewerDecisionAt: timestamp("interviewer_decision_at", { withTimezone: true }),
  interviewerDecisionBy: varchar("interviewer_decision_by").references(() => users.id, { onDelete: 'set null' }),
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  updatedBy: varchar("updated_by").references(() => users.id, { onDelete: 'set null' }),
}, (table) => ({
  applicationIdx: index("recruiting_interviews_application_idx").on(table.applicationId),
  startTimeIdx: index("recruiting_interviews_start_time_idx").on(table.startTime),
  statusIdx: index("recruiting_interviews_status_idx").on(table.status),
  organizerIdx: index("recruiting_interviews_organizer_idx").on(table.organizerId),
}));

export const insertRecruitingInterviewSchema = createInsertSchema(recruitingInterviews).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type RecruitingInterview = typeof recruitingInterviews.$inferSelect;
export type InsertRecruitingInterview = z.infer<typeof insertRecruitingInterviewSchema>;

// ============================================================================
// RECRUITING SCREENING REQUESTS — Triggered after "Proceed to Pre-Hire" (Ticket 11)
// ============================================================================
export const SCREENING_TYPES = ["mvr", "background_check", "drug_test"] as const;
export type ScreeningType = typeof SCREENING_TYPES[number];

export const SCREENING_REQUEST_STATUSES = ["pending", "requested", "in_progress", "completed", "failed", "waived"] as const;
export type ScreeningRequestStatus = typeof SCREENING_REQUEST_STATUSES[number];

export const SCREENING_RESULTS = ["pass", "fail", "pending", "waived"] as const;
export type ScreeningResult = typeof SCREENING_RESULTS[number];

export const recruitingScreeningRequests = pgTable("recruiting_screening_requests", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  applicationId: varchar("application_id").notNull().references(() => recruitingApplications.id, { onDelete: 'cascade' }),
  screeningType: varchar("screening_type").notNull(), // mvr | background_check | drug_test
  status: varchar("status").notNull().default("pending"), // pending | requested | in_progress | completed | failed | waived
  result: varchar("result"), // pass | fail | pending | waived
  resultNotes: text("result_notes"),
  // Trigger provenance
  triggeredAt: timestamp("triggered_at", { withTimezone: true }).notNull().defaultNow(),
  triggeredBy: varchar("triggered_by").references(() => users.id, { onDelete: 'set null' }),
  triggeredByDecision: varchar("triggered_by_decision").notNull().default("interview_decision"),
  triggeredByDecisionId: varchar("triggered_by_decision_id"), // Interview ID that caused the trigger
  notes: text("notes"),
  // Completion tracking
  completedAt: timestamp("completed_at", { withTimezone: true }),
  completedBy: varchar("completed_by").references(() => users.id, { onDelete: 'set null' }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  appIdx: index("recruiting_screening_requests_app_idx").on(table.applicationId),
  typeIdx: index("recruiting_screening_requests_type_idx").on(table.screeningType),
  statusIdx: index("recruiting_screening_requests_status_idx").on(table.status),
}));

export const insertRecruitingScreeningRequestSchema = createInsertSchema(recruitingScreeningRequests).omit({
  id: true, createdAt: true, updatedAt: true,
});
export type RecruitingScreeningRequest = typeof recruitingScreeningRequests.$inferSelect;

// ============================================================================
// RECRUITING CANDIDATE NOTIFICATIONS — Ticket 29 (Auto-Handoff)
// Stores structured next-step notifications sent to candidates when screening
// is automatically triggered after "Proceed to Pre-Hire" interview decision.
// ============================================================================

export const recruitingCandidateNotifications = pgTable("recruiting_candidate_notifications", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  applicationId: varchar("application_id").notNull().references(() => recruitingApplications.id, { onDelete: "cascade" }),
  notificationType: varchar("notification_type").notNull().default("pre_hire_instructions"),
  // channel: in_app = recorded internally (no email provider required)
  channel: varchar("channel").notNull().default("in_app"),
  status: varchar("status").notNull().default("sent"), // sent | read | failed
  subject: varchar("subject").notNull(),
  body: text("body").notNull(),
  // Screening context — what was triggered when this notification was created
  screeningsTriggered: jsonb("screenings_triggered"), // string[] of ScreeningType
  // Trigger linkage
  triggerSource: varchar("trigger_source").notNull().default("system"), // interview_decision | manual | system
  triggerSourceId: varchar("trigger_source_id"), // interview ID
  sentAt: timestamp("sent_at", { withTimezone: true }).notNull().defaultNow(),
  readAt: timestamp("read_at", { withTimezone: true }),
  triggeredBy: varchar("triggered_by").references(() => users.id, { onDelete: "set null" }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  appIdx: index("rcn_application_idx").on(table.applicationId),
  typeIdx: index("rcn_type_idx").on(table.notificationType),
  sentIdx: index("rcn_sent_idx").on(table.sentAt),
}));

export type RecruitingCandidateNotification = typeof recruitingCandidateNotifications.$inferSelect;
export type InsertRecruitingCandidateNotification = typeof recruitingCandidateNotifications.$inferInsert;

