// ============================================================================
// RECRUITING REFERRALS - Internal Referral Tracking
// ============================================================================

export const referralStatusEnum = pgEnum("referral_status", [
  "submitted",      // Initial submission
  "pending_review", // Under review by recruiting
  "candidate_created", // Candidate record created/linked
  "application_submitted", // Application submitted for requisition
  "interviewing",   // Candidate in interview process
  "offer_extended", // Offer made to candidate
  "hired",          // Candidate hired - eligible for reward
  "rejected",       // Candidate rejected at some stage
  "withdrawn",      // Candidate withdrew
  "duplicate",      // Duplicate referral detected
  "expired"         // Referral expired without action
]);
export type ReferralStatus = "submitted" | "pending_review" | "candidate_created" | "application_submitted" | "interviewing" | "offer_extended" | "hired" | "rejected" | "withdrawn" | "duplicate" | "expired";

export const recruitingReferrals = pgTable("recruiting_referrals", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Referrer info (employee/driver who made the referral)
  referrerId: varchar("referrer_id").notNull().references(() => users.id, { onDelete: 'cascade' }),
  // Referred candidate info (before candidate record exists)
  referredFirstName: varchar("referred_first_name").notNull(),
  referredLastName: varchar("referred_last_name").notNull(),
  referredEmail: varchar("referred_email").notNull(),
  referredPhone: varchar("referred_phone"),
  // Linked records (after deduplication/creation)
  candidateId: varchar("candidate_id").references(() => recruitingCandidates.id, { onDelete: 'set null' }),
  applicationId: varchar("application_id").references(() => recruitingApplications.id, { onDelete: 'set null' }),
  // Target role/requisition (optional)
  requisitionId: varchar("requisition_id").references(() => recruitingRequisitions.id, { onDelete: 'set null' }),
  market: varchar("market"), // Target market
  roleType: varchar("role_type"), // e.g., "driver", "dispatcher", etc.
  // Referral details
  status: referralStatusEnum("status").notNull().default("submitted"),
  notes: text("notes"), // Referrer's notes about the candidate
  relationship: varchar("relationship"), // How referrer knows the candidate
  // Anti-fraud / deduplication
  referralPeriodKey: varchar("referral_period_key"), // e.g., "2026-Q1" for quarterly periods
  dedupeHash: varchar("dedupe_hash"), // Hash of normalized email+phone for quick lookup
  // Milestone tracking for rewards
  milestoneReached: varchar("milestone_reached"), // Stage that triggered reward eligibility
  milestoneReachedAt: timestamp("milestone_reached_at", { withTimezone: true }),
  // ── Extended fields (migration 0016) ─────────────────────────────────────
  // Source system that submitted the referral (driverhub | mnm | dod | api)
  sourceSystem: varchar("source_system").default("driverhub"),
  // Driver entity who submitted (separate from referrerId user FK)
  referrerDriverId: varchar("referrer_driver_id"),
  // Referred candidate location / profile
  referredCity: varchar("referred_city"),
  referredState: varchar("referred_state"),
  referredDriverType: varchar("referred_driver_type"), // shift | ondemand | hybrid
  referredYearsExp: integer("referred_years_exp"),
  referredHasCdl: boolean("referred_has_cdl").default(false),
  referredEmployer: varchar("referred_employer"),
  // Consent
  consentToShare: boolean("consent_to_share").default(false),
  // Auto candidate creation tracking
  autoCandidateCreated: boolean("auto_candidate_created").default(false),
  autoCandidateCreatedAt: timestamp("auto_candidate_created_at"),
  // ── Referral code / campaign (migration 0017) ─────────────────────────────
  referralCode: varchar("referral_code", { length: 20 }), // Driver's personal referral code used
  campaignSource: varchar("campaign_source", { length: 50 }), // 'referral_link' | 'direct' | 'mnm_app' | etc.
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  expiresAt: timestamp("expires_at", { withTimezone: true }), // Referral validity period
}, (table) => ({
  referrerIdx: index("recruiting_referrals_referrer_idx").on(table.referrerId),
  candidateIdx: index("recruiting_referrals_candidate_idx").on(table.candidateId),
  statusIdx: index("recruiting_referrals_status_idx").on(table.status),
  dedupeIdx: index("recruiting_referrals_dedupe_idx").on(table.dedupeHash),
  emailIdx: index("recruiting_referrals_email_idx").on(table.referredEmail),
  periodIdx: index("recruiting_referrals_period_idx").on(table.referralPeriodKey),
  driverIdx: index("recruiting_referrals_driver_idx").on(table.referrerDriverId),
  sourceIdx: index("recruiting_referrals_source_system_idx").on(table.sourceSystem),
}));

