// ============================================================================
// REFERRAL REWARDS LEDGER - Tracking referral bonuses
// ============================================================================

export const rewardStatusEnum = pgEnum("reward_status", [
  "pending",      // Reward triggered but not yet approved
  "approved",     // Approved for payout
  "processing",   // Payment being processed
  "paid",         // Payment completed
  "cancelled",    // Reward cancelled (e.g., candidate left early)
  "clawback"      // Reward being clawed back
]);
export type RewardStatus = "pending" | "approved" | "processing" | "paid" | "cancelled" | "clawback";

export const referralRewardsLedger = pgTable("referral_rewards_ledger", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  referralId: varchar("referral_id").notNull().references(() => recruitingReferrals.id, { onDelete: 'cascade' }),
  referrerId: varchar("referrer_id").notNull().references(() => users.id, { onDelete: 'cascade' }),
  // Reward details
  amount: decimal("amount", { precision: 10, scale: 2 }).notNull(),
  currency: varchar("currency").notNull().default("USD"),
  // Trigger
  triggerEvent: varchar("trigger_event").notNull(), // e.g., "hired", "30_day_retention", "90_day_retention"
  triggerStage: varchar("trigger_stage"), // Workflow stage that triggered this
  // Status
  status: rewardStatusEnum("status").notNull().default("pending"),
  // Payment tracking (v1: tracking only, no actual payment integration)
  approvedBy: varchar("approved_by").references(() => users.id, { onDelete: 'set null' }),
  approvedAt: timestamp("approved_at", { withTimezone: true }),
  paidAt: timestamp("paid_at", { withTimezone: true }),
  paymentReference: varchar("payment_reference"), // External payment system reference
  // Notes
  notes: text("notes"),
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => ({
  referralIdx: index("referral_rewards_referral_idx").on(table.referralId),
  referrerIdx: index("referral_rewards_referrer_idx").on(table.referrerId),
  statusIdx: index("referral_rewards_status_idx").on(table.status),
}));

export const insertReferralRewardsLedgerSchema = createInsertSchema(referralRewardsLedger).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

export type ReferralRewardsLedger = typeof referralRewardsLedger.$inferSelect;
export type InsertReferralRewardsLedger = z.infer<typeof insertReferralRewardsLedgerSchema>;

