export interface ReferralBonusMilestone {
  trigger: string;   // 'submitted' | 'interviewed' | 'hired' | '30_day' | '60_day' | '90_day'
  label: string;
  amount: number;
  currency: string;
  auto_trigger: boolean;
}

export const referralProgramConfig = pgTable("referral_program_config", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull().default("Default Referral Program"),
  description: text("description"),
  isActive: boolean("is_active").notNull().default(true),
  // Program switches
  programEnabled: boolean("program_enabled").notNull().default(true),
  requireConsent: boolean("require_consent").notNull().default(true),
  requirePhone: boolean("require_phone").notNull().default(false),
  requireCityState: boolean("require_city_state").notNull().default(false),
  requireDriverType: boolean("require_driver_type").notNull().default(false),
  // Dedupe
  dedupePeriodMonths: integer("dedupe_period_months").notNull().default(6),
  allowSelfReferral: boolean("allow_self_referral").notNull().default(false),
  // Bonus milestones stored as JSONB
  bonusMilestones: jsonb("bonus_milestones").$type<ReferralBonusMilestone[]>().notNull().default([]),
  // Eligibility
  eligibleSources: jsonb("eligible_sources").$type<string[]>().default(["driver_referral"]),
  eligibleRoles: jsonb("eligible_roles").$type<string[]>().default(["driver"]),
  minTenureDays: integer("min_tenure_days").default(0),
  // Notifications
  notifyOnSubmission: boolean("notify_on_submission").notNull().default(true),
  notifyOnStatusChange: boolean("notify_on_status_change").notNull().default(true),
  notifyOnRewardEarned: boolean("notify_on_reward_earned").notNull().default(true),
  // Metadata
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: "set null" }),
  updatedBy: varchar("updated_by").references(() => users.id, { onDelete: "set null" }),
});

