// Alert recipient types
export const alertRecipientTypeEnum = pgEnum("alert_recipient_type", [
  "dispatch",
  "management", 
  "driver",
  "account_owner",
]);

// Alert severity levels
export const alertSeverityEnum = pgEnum("alert_severity", [
  "info",
  "warning",
  "critical",
]);

// Alert status
export const alertStatusEnum = pgEnum("alert_status", [
  "pending",
  "sent",
  "acknowledged",
  "dismissed",
  "expired",
]);

// Tiered OT Alert Configuration - per location/team thresholds
export const tieredOtAlertConfigs = pgTable("tiered_ot_alert_configs", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()::text`),
  // Scope (null = global, otherwise location/team specific)
  locationId: varchar("location_id").references(() => workLocations.id, { onDelete: 'cascade' }),
  accountId: varchar("account_id").references(() => customers.id, { onDelete: 'cascade' }),
  name: varchar("name").notNull(),
  description: text("description"),
  // Threshold 1: Early warning (default 8 hours remaining)
  threshold1HoursRemaining: numeric("threshold1_hours_remaining", { precision: 5, scale: 2 }).notNull().default("8"),
  threshold1Recipients: alertRecipientTypeEnum("threshold1_recipients").array().notNull().default(sql`ARRAY['dispatch']::alert_recipient_type[]`),
  // Threshold 2: Urgent warning (default 4 hours remaining)
  threshold2HoursRemaining: numeric("threshold2_hours_remaining", { precision: 5, scale: 2 }).notNull().default("4"),
  threshold2Recipients: alertRecipientTypeEnum("threshold2_recipients").array().notNull().default(sql`ARRAY['management']::alert_recipient_type[]`),
  // Threshold 3: OT reached (0 hours remaining)
  threshold3Action: varchar("threshold3_action").notNull().default("flag_schedule"), // flag_schedule, notify_all
  threshold3Recipients: alertRecipientTypeEnum("threshold3_recipients").array().notNull().default(sql`ARRAY['dispatch', 'management']::alert_recipient_type[]`),
  // OT threshold (weekly hours limit)
  weeklyOtThresholdHours: numeric("weekly_ot_threshold_hours", { precision: 5, scale: 2 }).notNull().default("40"),
  isActive: boolean("is_active").notNull().default(true),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
});

export const insertTieredOtAlertConfigSchema = createInsertSchema(tieredOtAlertConfigs).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});
export type InsertTieredOtAlertConfig = z.infer<typeof insertTieredOtAlertConfigSchema>;
export type TieredOtAlertConfig = typeof tieredOtAlertConfigs.$inferSelect;

// OT Alert Logs - audit trail for triggered alerts
export const otAlertLogs = pgTable("ot_alert_logs", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()::text`),
  // Context
  driverId: varchar("driver_id").notNull().references(() => drivers.id, { onDelete: 'cascade' }),
  scheduleId: varchar("schedule_id").references(() => schedulingSchedules.id, { onDelete: 'set null' }),
  shiftId: varchar("shift_id").references(() => schedulingShifts.id, { onDelete: 'set null' }),
  configId: varchar("config_id").references(() => tieredOtAlertConfigs.id, { onDelete: 'set null' }),
  // Alert details
  alertType: varchar("alert_type").notNull(), // ot_threshold_1, ot_threshold_2, ot_reached, break_approaching, break_overdue
  severity: alertSeverityEnum("severity").notNull(),
  recipientType: alertRecipientTypeEnum("recipient_type").notNull(),
  // Trigger data
  hoursWorked: numeric("hours_worked", { precision: 6, scale: 2 }),
  hoursRemaining: numeric("hours_remaining", { precision: 6, scale: 2 }),
  otThreshold: numeric("ot_threshold", { precision: 5, scale: 2 }),
  // Message
  title: varchar("title").notNull(),
  message: text("message").notNull(),
  // Status tracking
  status: alertStatusEnum("status").notNull().default("pending"),
  sentAt: timestamp("sent_at"),
  acknowledgedAt: timestamp("acknowledged_at"),
  acknowledgedBy: varchar("acknowledged_by").references(() => users.id, { onDelete: 'set null' }),
  // Metadata
  metadata: jsonb("metadata").$type<Record<string, any>>(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

export const insertOtAlertLogSchema = createInsertSchema(otAlertLogs).omit({
  id: true,
  createdAt: true,
});
export type InsertOtAlertLog = z.infer<typeof insertOtAlertLogSchema>;
export type OtAlertLog = typeof otAlertLogs.$inferSelect;

