// ==================== Recruiting Consent Ledger ====================
// Immutable record of all candidate consents and disclosures

export const recruitingConsentTypes = [
  "sms_opt_in",
  "email_opt_in",
  "background_check_authorization",
  "drug_test_consent",
  "mvr_check_consent",
  "disclosure_ny_article_23a",
  "disclosure_ca_icraa",
  "disclosure_general",
  "privacy_policy",
  "terms_of_service",
  "arbitration_agreement",
  "at_will_employment"
] as const;
export type RecruitingConsentType = typeof recruitingConsentTypes[number];

export const consentSourceTypes = [
  "candidate_portal",
  "application_form",
  "sms_reply",
  "email_link",
  "in_person",
  "phone",
  "recruiter_entry",
  "api",
  "system"
] as const;
export type ConsentSource = typeof consentSourceTypes[number];

export const recruitingConsents = pgTable("recruiting_consents", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Core relationships
  candidateId: varchar("candidate_id").notNull().references(() => recruitingCandidates.id, { onDelete: 'cascade' }),
  applicationId: varchar("application_id").references(() => recruitingApplications.id, { onDelete: 'set null' }),
  // Consent details
  consentType: varchar("consent_type").notNull(), // One of recruitingConsentTypes
  version: varchar("version").notNull().default("1.0"), // Version of the consent text
  textHash: varchar("text_hash"), // SHA-256 hash of consent text for verification
  // Consent action
  accepted: boolean("accepted").notNull().default(true), // true = consent given, false = declined
  acceptedAt: timestamp("accepted_at", { withTimezone: true }).notNull().defaultNow(),
  // Source tracking
  source: varchar("source").notNull().default("candidate_portal"), // One of consentSourceTypes
  sourceDetails: jsonb("source_details"), // Additional context (IP, user agent, form ID, etc.)
  // Reference to consent document (if stored)
  documentId: varchar("document_id"), // Optional link to stored consent document
  // Witness/verification
  witnessedBy: varchar("witnessed_by").references(() => users.id, { onDelete: 'set null' }),
  verificationMethod: varchar("verification_method"), // signature, checkbox, verbal, sms_keyword
  // State-specific compliance
  stateCode: varchar("state_code"), // NY, CA, TX, etc.
  // Expiration (for time-limited consents)
  expiresAt: timestamp("expires_at", { withTimezone: true }),
  // Revocation (immutable - new record created when revoked)
  revokedAt: timestamp("revoked_at", { withTimezone: true }),
  revokedBy: varchar("revoked_by").references(() => users.id, { onDelete: 'set null' }),
  revocationReason: text("revocation_reason"),
  // Audit
  createdAt: timestamp("created_at").notNull().defaultNow(),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: 'set null' }),
  // Note: No updatedAt - consents are immutable
}, (table) => ({
  candidateIdx: index("recruiting_consents_candidate_idx").on(table.candidateId),
  applicationIdx: index("recruiting_consents_application_idx").on(table.applicationId),
  typeIdx: index("recruiting_consents_type_idx").on(table.consentType),
  acceptedAtIdx: index("recruiting_consents_accepted_at_idx").on(table.acceptedAt),
  candidateTypeIdx: index("recruiting_consents_candidate_type_idx").on(table.candidateId, table.consentType),
  stateCodeIdx: index("recruiting_consents_state_code_idx").on(table.stateCode),
}));

export const recruitingConsentsRelations = relations(recruitingConsents, ({ one }) => ({
  candidate: one(recruitingCandidates, {
    fields: [recruitingConsents.candidateId],
    references: [recruitingCandidates.id],
  }),
  application: one(recruitingApplications, {
    fields: [recruitingConsents.applicationId],
    references: [recruitingApplications.id],
  }),
}));

export const insertRecruitingConsentSchema = createInsertSchema(recruitingConsents).omit({
  id: true,
  acceptedAt: true,
  createdAt: true,
});
export type InsertRecruitingConsent = z.infer<typeof insertRecruitingConsentSchema>;
export type RecruitingConsent = typeof recruitingConsents.$inferSelect;

