// Dispatch-confirmed actions from the WIW-backed No Show Monitor. These are
// deliberately separate from the legacy internal scheduling incident table:
// recording one must never alter WIW schedule or time-clock history.
export const schedulingManualNoShowActions = pgTable("scheduling_manual_no_show_actions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  wiwShiftId: varchar("wiw_shift_id").notNull(),
  driverId: varchar("driver_id").notNull().references(() => drivers.id, { onDelete: "restrict" }),
  accountId: varchar("account_id").references(() => customers.id, { onDelete: "set null" }),
  shiftStartAt: timestamp("shift_start_at", { withTimezone: true }).notNull(),
  gracePeriodEndAt: timestamp("grace_period_end_at", { withTimezone: true }),
  firstDetectedNotClockedInAt: timestamp("first_detected_not_clocked_in_at", { withTimezone: true }),
  markedBy: varchar("marked_by").references(() => users.id, { onDelete: "restrict" }),
  markedAt: timestamp("marked_at", { withTimezone: true }).notNull().defaultNow(),
  source: varchar("source").notNull().default("Dispatch No Show Monitor"),
  status: varchar("status").notNull().default("CONFIRMED_NO_SHOW"),
  action: varchar("action"),
  actionTimestamp: timestamp("action_timestamp", { withTimezone: true }),
  contactAttempt: varchar("contact_attempt"),
  contactResult: varchar("contact_result"),
  finalDisposition: varchar("final_disposition"),
  resolvedAt: timestamp("resolved_at", { withTimezone: true }),
  note: text("note"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => ({
  shiftDriverUnique: uniqueIndex("scheduling_manual_noshow_shift_driver_idx").on(table.wiwShiftId, table.driverId),
  driverIdx: index("scheduling_manual_noshow_driver_idx").on(table.driverId),
  markedAtIdx: index("scheduling_manual_noshow_marked_at_idx").on(table.markedAt),
}));

