export const TICKET_PRIORITY_LABELS: Record<string, string> = {
  P0: "P0 — Critical",
  P1: "P1 — High",
  P2: "P2 — Medium",
  P3: "P3 — Low",
  P4: "P4 — Future",
};

export const TICKET_STATUSES = [
  "submitted", "reviewed", "sent_back_for_info", "prioritizing",
  "in_queue", "in_development", "product_decision_required", "in_production", "needs_testing",
  "user_accepts", "user_declines", "completed",
  "received", "sent_back_for_feedback", "complete",
  "on_roadmap", "cancelled",
  "duplicate",  // Terminal administrative status — excluded from all dashboards, metrics & reports by default
] as const;
export type TicketStatus = typeof TICKET_STATUSES[number];

// Governance: visual warning thresholds based on total days open (since submittedAt)
export const TICKET_DAYS_WARNING = 25;  // amber warning at 25 days open
export const TICKET_DAYS_CRITICAL = 30; // red critical alert at 30 days open; action required

// Terminal statuses that are exempt from governance rules
export const TICKET_GOVERNANCE_TERMINAL = ["completed", "cancelled", "user_accepts", "user_declines", "complete", "duplicate"] as const;

// Hours of inactivity (no status change) before an AMR is considered aging per status
export const TICKET_AGING_THRESHOLDS: Partial<Record<string, number>> = {
  submitted:                  24,        // 1 day
  reviewed:                   24,        // 1 day
  prioritizing:               48,        // 2 days
  in_queue:                   7 * 24,    // 7 days
  in_development:             5 * 24,    // 5 days
  needs_testing:              48,        // 2 days
  sent_back_for_info:         48,        // 2 days
  product_decision_required:  72,        // 3 days
};

export const TICKET_STATUS_LABELS: Record<string, string> = {
  submitted: "Submitted",
  reviewed: "Reviewed",
  sent_back_for_info: "Sent Back for Additional Information",
  prioritizing: "Prioritizing",
  in_queue: "In Queue",
  in_development: "In Development / Waiting Deployment",
  product_decision_required: "Product Decision Required",
  in_production: "In Production",
  needs_testing: "Needs Testing / User Sign-off",
  user_accepts: "User Accepts",
  user_declines: "User Declines / See Comments",
  completed: "Completed",
  received: "Reviewed",
  sent_back_for_feedback: "Sent Back for Additional Information",
  complete: "Completed",
  on_roadmap: "Roadmap",
  cancelled: "Cancelled",
  duplicate: "Duplicate",
};

// Active statuses selectable in the AMR Workflow Status dropdown.
// "on_roadmap" was a workflow status; it is now a Planning Status value
// ("roadmapped") and remains in TICKET_STATUSES only for historical audit records.
export const TICKET_ACTIVE_STATUSES = [
  "submitted", "reviewed", "sent_back_for_info", "prioritizing",
  "in_queue", "in_development", "product_decision_required", "in_production", "needs_testing",
  "user_accepts", "user_declines", "completed",
  "cancelled", "duplicate",
] as const;

// Compatibility exports for consumers that still import the former transition
// symbols. AMR workflow status selection is intentionally no longer governed by
// a transition matrix, role, ownership, or assignment relationship.
export const TICKET_TRANSITIONS: Record<string, string[]> = {};
export const TICKET_SUBMITTER_TRANSITIONS: Record<string, string[]> = {};
export function getTicketAllowedTransitions(): string[] {
  return [...TICKET_ACTIVE_STATUSES];
}

export const ticketTypeEnum = pgEnum("ticket_type", TICKET_TYPES);
export const ticketModuleEnum = pgEnum("ticket_module", TICKET_MODULES);
export const ticketStatusEnum = pgEnum("ticket_status", TICKET_STATUSES);
export const ticketPlanningStatusEnum = pgEnum("ticket_planning_status", AMR_PLANNING_STATUSES);

export const tickets = pgTable("tickets", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  ticketNumber: varchar("ticket_number", { length: 20 }).notNull().unique(),
  ticketSequence: integer("ticket_sequence").notNull().unique(),
  type: ticketTypeEnum("type").notNull(),
  module: ticketModuleEnum("module").notNull(),
  title: varchar("title", { length: 500 }).notNull(),
  desiredOutcome: text("desired_outcome"),
  businessImpact: text("business_impact"),
  priority: varchar("priority").notNull().default("P2"),
  status: ticketStatusEnum("status").notNull().default("submitted"),
  submittedByUserId: varchar("submitted_by_user_id").notNull().references(() => users.id),
  submittedByUsername: varchar("submitted_by_username", { length: 255 }).notNull(),
  assignedToUserId: varchar("assigned_to_user_id").references(() => users.id),
  productOwnerUserId: varchar("product_owner_user_id").references(() => users.id),
  orgId: varchar("org_id"),
  submittedAt: timestamp("submitted_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  lastStatusChangeAt: timestamp("last_status_change_at").defaultNow(),
  completedAt: timestamp("completed_at"),
  scheduledDevelopmentDate: date("scheduled_development_date"),
  scheduledDeploymentDate: date("scheduled_deployment_date"),
  // Immutable committed deployment date — set once when scheduledDeploymentDate is first
  // assigned, never updated thereafter. Used for Roadmap Reliability calculations so that
  // moving the target date after a miss cannot artificially inflate on-time percentages.
  firstScheduledDeploymentDate: date("first_scheduled_deployment_date"),
  releaseCheckpoint: varchar("release_checkpoint"),
  agingOwnerNotifiedAt: timestamp("aging_owner_notified_at"),
  agingAdminNotifiedAt: timestamp("aging_admin_notified_at"),
  applicationScope: varchar("application_scope", { length: 50 }).default("DriverHub"),
  developerUserId: varchar("developer_user_id").references(() => users.id),
  devTeam: varchar("dev_team", { length: 50 }),
  epicId: varchar("epic_id").references(() => epics.id, { onDelete: "set null" }),
  isEpic: boolean("is_epic").notNull().default(false),
  epicTicketId: varchar("epic_ticket_id"),
  // Idempotency token — generated by the client when the submission form opens.
  // Ensures repeated POSTs (double-click, network retry, browser retry) create only one AMR.
  submissionToken: varchar("submission_token", { length: 64 }),
  // Planning fields — independent from Workflow Status
  planningStatus: ticketPlanningStatusEnum("planning_status"),
  phaseId: varchar("phase_id").references(() => amrPhases.id, { onDelete: "set null" }),
  // Immutable committed development date — set once when scheduledDevelopmentDate is first
  // assigned; never updated thereafter. Paired with firstScheduledDeploymentDate for
  // full Roadmap Reliability tracking.
  firstScheduledDevelopmentDate: date("first_scheduled_development_date"),
}, (table) => ({
  statusIdx: index("ticket_status_idx").on(table.status),
  submittedByIdx: index("ticket_submitted_by_idx").on(table.submittedByUserId),
  moduleIdx: index("ticket_module_idx").on(table.module),
  sequenceIdx: index("ticket_sequence_idx").on(table.ticketSequence),
}));

export const insertTicketSchema = createInsertSchema(tickets).omit({
  id: true, ticketNumber: true, ticketSequence: true,
  submittedByUserId: true, submittedByUsername: true, orgId: true,
  submittedAt: true, updatedAt: true, lastStatusChangeAt: true,
});
export type InsertTicket = z.infer<typeof insertTicketSchema>;
export type Ticket = typeof tickets.$inferSelect;

