// ── Persistent executive notification for declined AMRs ────────────────────
// Created when a ticket transitions to user_declines during UAT.
// Only cleared when Will Walton changes the AMR status — reading/opening never clears it.
export const amrDeclineNotifications = pgTable("amr_decline_notifications", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  ticketId: varchar("ticket_id").notNull().references(() => tickets.id, { onDelete: "cascade" }),
  amrNumber: text("amr_number").notNull(),
  amrTitle: text("amr_title").notNull(),
  submittedByName: text("submitted_by_name"),
  declinedByUserId: varchar("declined_by_user_id").notNull(),
  declinedByName: text("declined_by_name").notNull(),
  declinedAt: timestamp("declined_at", { withTimezone: true }).notNull().defaultNow(),
  declineComment: text("decline_comment"),
  clearedAt: timestamp("cleared_at", { withTimezone: true }),
  clearedByName: text("cleared_by_name"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => ({
  ticketIdx: index("amr_decline_notif_ticket_idx").on(table.ticketId),
}));
export type AmrDeclineNotification = typeof amrDeclineNotifications.$inferSelect;

