// ── Data Imports Module ────────────────────────────────────────────────────────
// Centralized batch tracking for all external data ingestion into DriverHub.
// Migration 0033.

export const DATA_IMPORT_TYPES = [
  'move_report', 'driver_return', 'uber_transaction',
  'accounts', 'drivers', 'invoices', 'payments', 'claims', 'scheduling', 'sql_sync',
] as const;
export type DataImportType = typeof DATA_IMPORT_TYPES[number];

export const DATA_IMPORT_STATUSES = [
  'uploaded', 'validating', 'ready_for_import', 'importing',
  'imported', 'completed_with_warnings',
  'failed',            // data-quality failure (all rows rejected)
  'validation_failed', // same as failed but distinguishes validation-stage data errors
  'processing_error',  // unexpected system error during upload / validation / import
] as const;
export type DataImportStatus = typeof DATA_IMPORT_STATUSES[number];

// ── Import Source Systems ──────────────────────────────────────────────────────
export const importSourceSystems = pgTable("import_source_systems", {
  id:           varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  sourceKey:    varchar("source_key", { length: 50 }).unique().notNull(),
  displayName:  varchar("display_name", { length: 100 }).notNull(),
  importTypes:  text("import_types").array().notNull().default(sql`'{}'`),
  parserConfig: jsonb("parser_config"),
  isActive:     boolean("is_active").notNull().default(true),
  createdAt:    timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});
export type ImportSourceSystem = typeof importSourceSystems.$inferSelect;

// ── Import Source Configs ──────────────────────────────────────────────────────
// One row per configured data source.  configType selects the adapter:
//   'excel_csv'  — file upload (existing flow; ExcelCsvAdapter wraps parseBuffer)
//   'sql_server' — direct SQL Server query via SqlServerAdapter
//   'csv_url'    — HTTP/HTTPS CSV fetch via CsvUrlAdapter
//   'api'        — future: generic REST adapter
// The validation pipeline (runValidation), entity mapping, and domain writes
// are the same regardless of configType — only the source layer changes.
export const importSourceConfigs = pgTable("import_source_configs", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name:             varchar("name", { length: 100 }).notNull(),
  description:      text("description"),
  // What this config produces
  importType:       varchar("import_type", { length: 50 }).notNull(),
  sourceSystemKey:  varchar("source_system_key", { length: 50 }).notNull(),
  // Adapter selector
  configType:       varchar("config_type", { length: 30 }).notNull(),
  // Adapter connection params (schema varies by configType; passwords stored as env-var name only)
  connectionConfig: jsonb("connection_config").notNull().default(sql`'{}'`),
  // Column-name translation: source column → canonical pipeline header
  fieldMap:         jsonb("field_map").notNull().default(sql`'{}'`),
  batchMode:        varchar("batch_mode", { length: 20 }).notNull().default("supplement"),
  defaultPeriodDays: integer("default_period_days").default(30),
  isActive:         boolean("is_active").notNull().default(true),
  scheduleCron:     varchar("schedule_cron", { length: 100 }),
  // Sync tracking
  lastSyncedAt:     timestamp("last_synced_at", { withTimezone: true }),
  lastBatchId:      varchar("last_batch_id"),
  lastSyncRowCount: integer("last_sync_row_count"),
  lastSyncStatus:   varchar("last_sync_status", { length: 30 }),
  // Audit
  createdBy:        varchar("created_by"),
  createdAt:        timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt:        timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});
export type ImportSourceConfigRow = typeof importSourceConfigs.$inferSelect;

// ── Import Periods ─────────────────────────────────────────────────────────────
// One row per (period_start, period_end, import_type, source_system_key).
// Groups all batches that contribute to the same logical dataset.
export const importPeriods = pgTable("import_periods", {
  id:                   varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  periodStart:          date("period_start").notNull(),
  periodEnd:            date("period_end").notNull(),
  importType:           varchar("import_type", { length: 50 }).notNull(),
  sourceSystemKey:      varchar("source_system_key", { length: 50 }).notNull(),
  receivedBatchCount:   integer("received_batch_count").notNull().default(0),
  latestBatchId:        varchar("latest_batch_id"),
  reconciliationStatus: varchar("reconciliation_status", { length: 20 }).notNull().default("pending"),
  createdAt:            timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt:            timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});
export type ImportPeriod = typeof importPeriods.$inferSelect;

// ── Import Reconciliation Runs ─────────────────────────────────────────────────
// Stores results of cross-source comparison for a reporting period.
export const importReconciliationRuns = pgTable("import_reconciliation_runs", {
  id:            varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  periodStart:   date("period_start").notNull(),
  periodEnd:     date("period_end").notNull(),
  importType:    varchar("import_type", { length: 50 }).notNull(),
  sources:       text("sources").array().notNull().default(sql`'{}'`),
  status:        varchar("status", { length: 20 }).notNull().default("pending"),
  runBy:         varchar("run_by").references(() => users.id, { onDelete: "set null" }),
  resultSummary: jsonb("result_summary"),
  resultDetail:  jsonb("result_detail"),
  createdAt:     timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  completedAt:   timestamp("completed_at", { withTimezone: true }),
});
export type ImportReconciliationRun = typeof importReconciliationRuns.$inferSelect;

export const dataImportBatches = pgTable("data_import_batches", {
  id:                    varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  importType:            varchar("import_type", { length: 50 }).notNull(),
  sourceSystemKey:       varchar("source_system_key", { length: 50 }).notNull().default("redcap"),
  periodId:              varchar("period_id").references(() => importPeriods.id, { onDelete: "set null" }),
  batchMode:             varchar("batch_mode", { length: 20 }).notNull().default("supplement"),
  // supplement: upsert by record key (default — daily imports, late arrivals)
  // correction:  supersede old records, insert new (revised files)
  // reprocess:   retry only failed/skipped rows from this batch
  supersedesBatchId:     varchar("supersedes_batch_id"),  // self-ref; no FK to avoid boot order issue
  parentBatchId:         varchar("parent_batch_id"),      // reprocess batches point to origin
  fileName:              text("file_name").notNull(),
  fileSizeBytes:         integer("file_size_bytes"),
  fileStorageKey:        text("file_storage_key"),
  fileHash:              varchar("file_hash", { length: 64 }),
  reportingPeriodStart:  date("reporting_period_start"),
  reportingPeriodEnd:    date("reporting_period_end"),
  importedByUserId:      varchar("imported_by_user_id").notNull().references(() => users.id, { onDelete: "set null" }),
  recordsRead:           integer("records_read").notNull().default(0),
  recordsImported:       integer("records_imported").notNull().default(0),
  recordsUpdated:        integer("records_updated").notNull().default(0),
  recordsSkipped:        integer("records_skipped").notNull().default(0),
  validationErrorCount:  integer("validation_error_count").notNull().default(0),
  status:                varchar("status", { length: 30 }).notNull().default("uploaded"),
  columnHeaders:         jsonb("column_headers"),
  fieldMapping:          jsonb("field_mapping"),
  validationResult:      jsonb("validation_result"),
  importResult:          jsonb("import_result"),
  errorMessage:          text("error_message"),
  notes:                 text("notes"),
  validationStatus:      varchar("validation_status", { length: 30 }).notNull().default("not_validated"),
  validatedAt:           timestamp("validated_at", { withTimezone: true }),
  importedAt:            timestamp("imported_at", { withTimezone: true }),
  createdAt:             timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt:             timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const dataImportStagedRows = pgTable("data_import_staged_rows", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  batchId:          varchar("batch_id").notNull().references(() => dataImportBatches.id, { onDelete: "cascade" }),
  rowIndex:         integer("row_index").notNull(),
  rawData:          jsonb("raw_data").notNull(),
  mappedData:       jsonb("mapped_data"),
  validationStatus: varchar("validation_status", { length: 20 }).default("pending"),
  validationErrors: jsonb("validation_errors"),
  importStatus:     varchar("import_status", { length: 20 }).default("pending"),
  importError:      text("import_error"),
  linkedRecordId:   varchar("linked_record_id"),
  createdAt:        timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type DataImportBatch   = typeof dataImportBatches.$inferSelect;
export type DataImportStagedRow = typeof dataImportStagedRows.$inferSelect;

