// ── End Data Imports Module ────────────────────────────────────────────────────

export const FEEDBACK_SENTIMENTS = ['positive', 'neutral', 'negative'] as const;
export const feedbackSentimentEnum = pgEnum("feedback_sentiment", FEEDBACK_SENTIMENTS);

export const FEEDBACK_PROMPTS = ['sign_in', 'sign_out', 'manual'] as const;
export const feedbackPromptEnum = pgEnum("feedback_prompt_type", FEEDBACK_PROMPTS);

export const USER_FEEDBACK_STATUSES = [
  'new',
  'reviewed',
  'converted_to_quick_idea',
  'converted_to_amr',
  'no_action',
] as const;
export type UserFeedbackStatus = typeof USER_FEEDBACK_STATUSES[number];

export const userFeedback = pgTable("user_feedback", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  username: varchar("username", { length: 255 }).notNull(),
  userEmail: varchar("user_email", { length: 320 }),
  promptType: feedbackPromptEnum("prompt_type").notNull(),
  responseText: text("response_text").notNull(),
  sentiment: feedbackSentimentEnum("sentiment").notNull().default("neutral"),
  moduleContext: varchar("module_context", { length: 100 }),
  pageUrl: varchar("page_url", { length: 2048 }),
  appEnvironment: varchar("app_environment", { length: 64 }),
  dismissed: boolean("dismissed").notNull().default(false),
  adminNotified: boolean("admin_notified").notNull().default(false),
  status: varchar("status", { length: 40 }).notNull().default("new"),
  convertedRecordType: varchar("converted_record_type", { length: 40 }),
  convertedRecordId: varchar("converted_record_id"),
  convertedRecordReference: varchar("converted_record_reference", { length: 100 }),
  reviewedAt: timestamp("reviewed_at"),
  reviewedByUserId: varchar("reviewed_by_user_id").references(() => users.id, { onDelete: "set null" }),
  createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => ({
  userIdx: index("feedback_user_idx").on(table.userId),
  sentimentIdx: index("feedback_sentiment_idx").on(table.sentiment),
  statusIdx: index("feedback_status_idx").on(table.status),
  createdAtIdx: index("feedback_created_at_idx").on(table.createdAt),
}));

export const insertUserFeedbackSchema = createInsertSchema(userFeedback).omit({
  id: true,
  userId: true,
  username: true,
  userEmail: true,
  adminNotified: true,
  status: true,
  convertedRecordType: true,
  convertedRecordId: true,
  convertedRecordReference: true,
  reviewedAt: true,
  reviewedByUserId: true,
  createdAt: true,
});
export type InsertUserFeedback = z.infer<typeof insertUserFeedbackSchema>;
export type UserFeedback = typeof userFeedback.$inferSelect;

