export const driverPerformanceScores = pgTable("driver_performance_scores", {
  id:                   varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  driverId:             varchar("driver_id").notNull().references(() => drivers.id, { onDelete: "cascade" }),
  score:                numeric("score",                 { precision: 5, scale: 2 }).notNull().default("50"),
  tier:                 varchar("tier", { length: 20 }).notNull().default("Fair"),
  attendanceScore:      numeric("attendance_score",     { precision: 5, scale: 2 }).notNull().default("50"),
  adherenceScore:       numeric("adherence_score",      { precision: 5, scale: 2 }).notNull().default("50"),
  otScore:              numeric("ot_score",             { precision: 5, scale: 2 }).notNull().default("50"),
  claimsScore:          numeric("claims_score",         { precision: 5, scale: 2 }).notNull().default("50"),
  attendanceWeight:     numeric("attendance_weight",    { precision: 4, scale: 2 }).notNull().default("0.35"),
  adherenceWeight:      numeric("adherence_weight",     { precision: 4, scale: 2 }).notNull().default("0.40"),
  otWeight:             numeric("ot_weight",            { precision: 4, scale: 2 }).notNull().default("0.25"),
  claimsWeight:         numeric("claims_weight",        { precision: 4, scale: 2 }).notNull().default("0.00"),
  absences90d:          integer("absences_90d").notNull().default(0),
  workedHours30d:       numeric("worked_hours_30d",    { precision: 7, scale: 2 }).notNull().default("0"),
  scheduledHours30d:    numeric("scheduled_hours_30d", { precision: 7, scale: 2 }).notNull().default("0"),
  otWeeksCount:         integer("ot_weeks_count").notNull().default(0),
  totalWeeksCount:      integer("total_weeks_count").notNull().default(0),
  wiwLinked:            boolean("wiw_linked").notNull().default(false),
  computedAt:           timestamp("computed_at").notNull().defaultNow(),
  computedForWeekStart: date("computed_for_week_start"),
}, (table) => ({
  driverUniq:  uniqueIndex("driver_perf_score_driver_unique").on(table.driverId),
  driverIdx:   index("driver_perf_score_driver_idx").on(table.driverId),
  tierIdx:     index("driver_perf_score_tier_idx").on(table.tier),
}));

export const insertDriverPerformanceScoreSchema = createInsertSchema(driverPerformanceScores).omit({
  id: true, computedAt: true,
});
export type InsertDriverPerformanceScore = z.infer<typeof insertDriverPerformanceScoreSchema>;
export type DriverPerformanceScore = typeof driverPerformanceScores.$inferSelect;

