export const products = pgTable("products", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  tenantId: varchar("tenant_id").references(() => organizations.id, { onDelete: "set null" }),
  name: varchar("name", { length: 255 }).notNull(),
  description: text("description"),
  sku: varchar("sku", { length: 100 }),
  unitPrice: numeric("unit_price", { precision: 12, scale: 2 }).notNull().default("0"),
  currency: varchar("currency", { length: 3 }).notNull().default("USD"),
  category: varchar("category", { length: 100 }),
  unit: varchar("unit", { length: 50 }).default("each"),
  isActive: boolean("is_active").notNull().default(true),
  taxable: boolean("taxable").notNull().default(false),
  taxRate: numeric("tax_rate", { precision: 5, scale: 4 }),
  glCode: varchar("gl_code", { length: 50 }),
  // Section A — Product Identity
  serviceCategory: varchar("service_category", { length: 100 }),    // shift_coverage | coordinator_services | ...
  operationalDivision: varchar("operational_division", { length: 100 }),
  marketAvailability: varchar("market_availability", { length: 255 }),
  // Section B — Operational Configuration
  requiresScheduling: boolean("requires_scheduling").default(false),
  requiresDriverAssignment: boolean("requires_driver_assignment").default(false),
  requiresDispatch: boolean("requires_dispatch").default(false),
  eligibleForDriverDash: boolean("eligible_for_driver_dash").default(false),
  requiresBillingApproval: boolean("requires_billing_approval").default(false),
  requiresVehicleTracking: boolean("requires_vehicle_tracking").default(false),
  defaultMoveTypes: varchar("default_move_types", { length: 255 }),
  operationalNotes: text("operational_notes"),
  // Section D — Billing Configuration extras
  invoiceDescription: varchar("invoice_description", { length: 255 }),
  exportCode: varchar("export_code", { length: 50 }),
  accountingNotes: text("accounting_notes"),
  // Billing Classification (Revenue Engine)
  productType: varchar("product_type", { length: 50 }),
  pricingModel: varchar("pricing_model", { length: 50 }),
  billingFrequency: varchar("billing_frequency", { length: 50 }),
  billingTrigger: varchar("billing_trigger", { length: 50 }),
  revenueCategory: varchar("revenue_category", { length: 50 }),
  // ── Product Library expansion (migration 0029) ────────────────────────────
  // General
  productCode: varchar("product_code", { length: 50 }),
  internalNotes: text("internal_notes"),
  // Commercial Pricing
  minPrice: numeric("min_price", { precision: 12, scale: 2 }),
  maxPrice: numeric("max_price", { precision: 12, scale: 2 }),
  suggestedPrice: numeric("suggested_price", { precision: 12, scale: 2 }),
  marginTarget: numeric("margin_target", { precision: 5, scale: 4 }),
  // Pricing tab expansion (migration 0062)
  cost: numeric("cost", { precision: 12, scale: 2 }),             // cost to deliver (used for gross margin)
  effectiveDate: date("effective_date"),                            // date from which pricing is effective
  priceBook: varchar("price_book", { length: 100 }),               // price book classification / name
  // Proposal & Marketing
  headline: varchar("headline", { length: 255 }),
  executiveSummary: text("executive_summary"),
  customerDescription: text("customer_description"),
  whatItDelivers: text("what_it_delivers"),
  benefits: text("benefits"),
  bestFor: text("best_for"),
  callToAction: varchar("call_to_action", { length: 255 }),
  // Media Assets
  heroImage: text("hero_image"),
  productIcon: text("product_icon"),
  flyerUrl: text("flyer_url"),
  videoUrls: jsonb("video_urls").$type<string[]>().default([]),
  // Operations Extensions
  markets: jsonb("markets").$type<string[]>().default([]),
  driverRequirements: text("driver_requirements"),
  schedulingRules: text("scheduling_rules"),
  complianceRules: text("compliance_rules"),
  dispatchRules: text("dispatch_rules"),
  // Billing Extensions
  taxRules: text("tax_rules"),
  revenueRecognition: text("revenue_recognition"),
  passThroughRules: text("pass_through_rules"),
  createdBy: varchar("created_by").references(() => users.id),
  updatedBy: varchar("updated_by").references(() => users.id),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => ({
  tenantIdx: index("products_tenant_idx").on(table.tenantId),
  categoryIdx: index("products_category_idx").on(table.category),
  activeIdx: index("products_active_idx").on(table.isActive),
  serviceCategoryIdx: index("products_service_category_idx").on(table.serviceCategory),
}));
export const insertProductSchema = createInsertSchema(products).omit({ id: true, createdAt: true, updatedAt: true });
export type InsertProduct = z.infer<typeof insertProductSchema>;
export type Product = typeof products.$inferSelect;

