// ─── Job Ad Templates (Ticket 39) ────────────────────────────────────────────
// Admin-managed templates keyed by driver type / role type. Template body uses
// {{placeholder}} syntax for auto-population from requisition data.
export const jobAdTemplates = pgTable("job_ad_templates", {
  id:           varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orgId:        varchar("org_id").notNull(),
  name:         varchar("name", { length: 200 }).notNull(),
  // Targeting: any combination of driver types and/or role type
  driverTypes:  text("driver_types").array().notNull().default([]), // Shift, On-Demand, Shuttle, CDL
  roleType:     varchar("role_type", { length: 50 }), // shift | on_demand | shuttle | cdl | any
  // Template body: markdown/plain text with {{placeholders}}
  // Supported placeholders: {{pay_rate}}, {{location}}, {{market}}, {{dealership}},
  //   {{address}}, {{driver_types}}, {{target_date}}, {{target_count}}, {{schedule}},
  //   {{sign_on_bonus}}, {{campaign_type}}, {{phone_interview_contact}}
  templateBody: text("template_body").notNull(),
  description:  text("description"),
  isDefault:    boolean("is_default").notNull().default(false),
  isActive:     boolean("is_active").notNull().default(true),
  createdBy:    varchar("created_by"),
  updatedBy:    varchar("updated_by"),
  createdAt:    timestamp("created_at").notNull().defaultNow(),
  updatedAt:    timestamp("updated_at").notNull().defaultNow(),
}, (table) => ({
  orgIdx:  index("job_ad_templates_org_idx").on(table.orgId),
  roleIdx: index("job_ad_templates_role_idx").on(table.roleType),
}));
export const insertJobAdTemplateSchema = createInsertSchema(jobAdTemplates).omit({ id: true, createdAt: true, updatedAt: true });
export type InsertJobAdTemplate = z.infer<typeof insertJobAdTemplateSchema>;
export type JobAdTemplate = typeof jobAdTemplates.$inferSelect;

