// edited by the recruiter. One draft per requisition (UNIQUE constraint).
export const jobAdDrafts = pgTable("job_ad_drafts", {
  id:            varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  requisitionId: varchar("requisition_id").notNull()
                   .references(() => recruitingRequisitions.id, { onDelete: "cascade" }),
  templateId:    varchar("template_id"), // may become null if template is deleted
  draftBody:     text("draft_body").notNull(),
  status:        varchar("status", { length: 30 }).notNull().default("draft"), // draft | finalized | posted
  finalizedBy:   varchar("finalized_by"),
  finalizedAt:   timestamp("finalized_at"),
  createdBy:     varchar("created_by"),
  updatedBy:     varchar("updated_by"),
  createdAt:     timestamp("created_at").notNull().defaultNow(),
  updatedAt:     timestamp("updated_at").notNull().defaultNow(),
}, (table) => ({
  reqIdx: index("job_ad_drafts_req_idx").on(table.requisitionId),
}));
export const insertJobAdDraftSchema = createInsertSchema(jobAdDrafts).omit({ id: true, createdAt: true, updatedAt: true });
export type InsertJobAdDraft = z.infer<typeof insertJobAdDraftSchema>;
export type JobAdDraft = typeof jobAdDrafts.$inferSelect;

