// v1 API Keys — database-backed, multi-key, scoped
export const v1ApiKeys = pgTable("v1_api_keys", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name", { length: 255 }).notNull(),
  description: text("description"),
  keyHash: varchar("key_hash", { length: 64 }).notNull().unique(),
  keyPrefix: varchar("key_prefix", { length: 20 }).notNull(),
  orgId: varchar("org_id").references(() => organizations.id, { onDelete: "cascade" }),
  scopes: text("scopes").array().default(sql`'{}'`),
  isActive: boolean("is_active").default(true),
  lastUsedAt: timestamp("last_used_at"),
  expiresAt: timestamp("expires_at"),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: "set null" }),
  createdAt: timestamp("created_at").defaultNow(),
});

// Webhook endpoint registration
export const webhookEndpoints = pgTable("webhook_endpoints", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orgId: varchar("org_id").references(() => organizations.id, { onDelete: "cascade" }),
  name: varchar("name", { length: 255 }).notNull(),
  url: text("url").notNull(),
  secret: varchar("secret", { length: 64 }).notNull(),
  events: text("events").array().default(sql`'{}'`),
  isActive: boolean("is_active").default(true),
  description: text("description"),
  createdBy: varchar("created_by").references(() => users.id, { onDelete: "set null" }),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Webhook delivery log with retry tracking
export const webhookDeliveryLog = pgTable("webhook_delivery_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  endpointId: varchar("endpoint_id").references(() => webhookEndpoints.id, { onDelete: "cascade" }),
  eventType: varchar("event_type", { length: 100 }).notNull(),
  payload: jsonb("payload").notNull(),
  status: varchar("status", { length: 50 }).default("pending"),
  attempts: integer("attempts").default(0),
  lastAttemptAt: timestamp("last_attempt_at"),
  nextRetryAt: timestamp("next_retry_at"),
  deliveredAt: timestamp("delivered_at"),
  responseStatus: integer("response_status"),
  responseBody: text("response_body"),
  createdAt: timestamp("created_at").defaultNow(),
});

// v1 Idempotency keys — prevent duplicate POST processing
export const v1IdempotencyKeys = pgTable("v1_idempotency_keys", {
  key: varchar("key", { length: 255 }).primaryKey(),
  orgId: varchar("org_id"),
  response: jsonb("response"),
  statusCode: integer("status_code"),
  createdAt: timestamp("created_at").defaultNow(),
  expiresAt: timestamp("expires_at"),
});

// v1 Audit log — immutable write audit for all API mutations
export const v1AuditLog = pgTable("v1_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  apiKeyId: varchar("api_key_id"),
  keyName: varchar("key_name"),
  orgId: varchar("org_id"),
  action: varchar("action", { length: 100 }).notNull(),
  resource: varchar("resource", { length: 100 }).notNull(),
  resourceId: varchar("resource_id"),
  requestBody: jsonb("request_body"),
  responseStatus: integer("response_status"),
  idempotencyKey: varchar("idempotency_key"),
  ipAddress: varchar("ip_address", { length: 50 }),
  userAgent: text("user_agent"),
  createdAt: timestamp("created_at").defaultNow(),
});

// v1 Execution events — inbound events from DriverConnect
export const v1ExecutionEvents = pgTable("v1_execution_events", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  idempotencyKey: varchar("idempotency_key", { length: 255 }).unique(),
  apiKeyId: varchar("api_key_id"),
  orgId: varchar("org_id"),
  moveId: varchar("move_id"),
  driverId: varchar("driver_id"),
  eventType: varchar("event_type", { length: 100 }).notNull(),
  // Spec Section 9: explicit event_timestamp, actor_type, actor_id, notes columns
  // (also captured in payload jsonb for full request archival)
  eventTimestamp: timestamp("event_timestamp", { withTimezone: true }),
  actorType: varchar("actor_type", { length: 50 }),
  actorId: varchar("actor_id", { length: 255 }),
  notes: text("notes"),
  lat: decimal("lat", { precision: 10, scale: 7 }),
  lng: decimal("lng", { precision: 10, scale: 7 }),
  payload: jsonb("payload").notNull(),
  processedAt: timestamp("processed_at"),
  processingResult: jsonb("processing_result"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Insert schemas
export const insertV1ApiKeySchema = createInsertSchema(v1ApiKeys).omit({ id: true, keyHash: true, keyPrefix: true, lastUsedAt: true, createdAt: true });
export const insertWebhookEndpointSchema = createInsertSchema(webhookEndpoints).omit({ id: true, createdAt: true, updatedAt: true });
export const insertWebhookDeliveryLogSchema = createInsertSchema(webhookDeliveryLog).omit({ id: true, createdAt: true });
export const insertV1AuditLogSchema = createInsertSchema(v1AuditLog).omit({ id: true, createdAt: true });
export const insertV1ExecutionEventSchema = createInsertSchema(v1ExecutionEvents).omit({ id: true, createdAt: true });

export const v1Exceptions = pgTable("v1_exceptions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  idempotencyKey: varchar("idempotency_key", { length: 255 }).unique(),
  apiKeyId: varchar("api_key_id"),
  orgId: varchar("org_id"),
  moveId: varchar("move_id"),
  driverId: varchar("driver_id"),
  reasonCode: varchar("reason_code", { length: 100 }).notNull(),
  description: text("description").notNull(),
  severity: varchar("severity", { length: 20 }).notNull().default('MEDIUM'),
  status: varchar("status", { length: 20 }).notNull().default('OPEN'),
  resolutionNotes: text("resolution_notes"),
  lat: decimal("lat", { precision: 10, scale: 7 }),
  lng: decimal("lng", { precision: 10, scale: 7 }),
  payload: jsonb("payload").notNull().default({}),
  reportedAt: timestamp("reported_at").defaultNow(),
  resolvedAt: timestamp("resolved_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

export const v1DriverStatusEvents = pgTable("v1_driver_status_events", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  idempotencyKey: varchar("idempotency_key", { length: 255 }).unique(),
  apiKeyId: varchar("api_key_id"),
  orgId: varchar("org_id"),
  driverId: varchar("driver_id").notNull(),
  status: varchar("status", { length: 50 }).notNull(),
  previousStatus: varchar("previous_status", { length: 50 }),
  eventTimestamp: timestamp("event_timestamp").notNull(),
  lat: decimal("lat", { precision: 10, scale: 7 }),
  lng: decimal("lng", { precision: 10, scale: 7 }),
  notes: text("notes"),
  payload: jsonb("payload").notNull().default({}),
  createdAt: timestamp("created_at").defaultNow(),
});

export const insertV1ExceptionSchema = createInsertSchema(v1Exceptions).omit({ id: true, createdAt: true });
export const insertV1DriverStatusEventSchema = createInsertSchema(v1DriverStatusEvents).omit({ id: true, createdAt: true });

// Types
export type V1ApiKey = typeof v1ApiKeys.$inferSelect;
export type WebhookEndpoint = typeof webhookEndpoints.$inferSelect;
export type WebhookDeliveryLog = typeof webhookDeliveryLog.$inferSelect;
export type V1AuditLog = typeof v1AuditLog.$inferSelect;
export type V1ExecutionEvent = typeof v1ExecutionEvents.$inferSelect;
export type V1Exception = typeof v1Exceptions.$inferSelect;
export type V1DriverStatusEvent = typeof v1DriverStatusEvents.$inferSelect;

// ──────────────────────────────────────────────────────────────────────────────
// DriverConnect v1 — Time & Expense Event Tables
// ──────────────────────────────────────────────────────────────────────────────

// v1_time_events — immutable record of time events submitted via DriverConnect API
export const v1TimeEvents = pgTable("v1_time_events", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  idempotencyKey:   varchar("idempotency_key", { length: 255 }).unique(),
  apiKeyId:         varchar("api_key_id"),
  orgId:            varchar("org_id"),
  driverId:         varchar("driver_id").notNull(),
  tripId:           varchar("trip_id"),
  // Event type
  eventType:        varchar("event_type", { length: 50 }).notNull(), // CLOCK_IN | CLOCK_OUT | SHIFT_ENTRY
  // Time window
  startAt:          timestamp("start_at", { withTimezone: true }).notNull(),
  endAt:            timestamp("end_at",   { withTimezone: true }),
  durationMinutes:  integer("duration_minutes"),
  // Location
  lat:              decimal("lat", { precision: 10, scale: 7 }),
  lng:              decimal("lng", { precision: 10, scale: 7 }),
  // Approval workflow
  approvalStatus:   varchar("approval_status", { length: 50 }).default("pending"), // pending | approved | rejected
  approvedAt:       timestamp("approved_at"),
  approvedByUserId: varchar("approved_by_user_id"),
  // Linked internal record (set when a time_entries row is created)
  timeEntryId:      integer("time_entry_id"),
  // Notes
  notes:            text("notes"),
  // Soft-delete flag
  isVoided:         boolean("is_voided").default(false),
  createdAt:        timestamp("created_at").defaultNow(),
});

export const insertV1TimeEventSchema = createInsertSchema(v1TimeEvents).omit({ id: true, createdAt: true });
export type V1TimeEvent = typeof v1TimeEvents.$inferSelect;
export type InsertV1TimeEvent = z.infer<typeof insertV1TimeEventSchema>;

// v1_expense_events — immutable record of expense events submitted via DriverConnect API
export const v1ExpenseEvents = pgTable("v1_expense_events", {
  id:              varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  idempotencyKey:  varchar("idempotency_key", { length: 255 }).unique(),
  apiKeyId:        varchar("api_key_id"),
  orgId:           varchar("org_id"),
  // Required entity links
  driverId:        varchar("driver_id").notNull(),
  tripId:          varchar("trip_id"),
  accountId:       varchar("account_id"),
  // Expense details
  expenseType:     varchar("expense_type", { length: 100 }).notNull(), // fuel | tolls | parking | maintenance | wait_time | damage | meal | other
  category:        varchar("category", { length: 100 }),               // sub-category / label
  amount:          decimal("amount", { precision: 10, scale: 2 }).notNull(),
  currency:        varchar("currency", { length: 10 }).default("USD"),
  description:     text("description"),
  expenseDate:     date("expense_date").notNull(),
  // Receipt / evidence
  receiptUrl:      varchar("receipt_url"),
  // Billing flags
  rebillable:      boolean("rebillable").default(false),
  // Approval workflow
  approvalStatus:  varchar("approval_status", { length: 50 }).default("pending"), // pending | approved | rejected
  approvedAt:      timestamp("approved_at"),
  approvedByUserId: varchar("approved_by_user_id"),
  // Linked internal expense record (if created)
  expenseId:       varchar("expense_id"),
  // Soft-delete
  isVoided:        boolean("is_voided").default(false),
  createdAt:       timestamp("created_at").defaultNow(),
});

export const insertV1ExpenseEventSchema = createInsertSchema(v1ExpenseEvents).omit({ id: true, createdAt: true });
export type V1ExpenseEvent = typeof v1ExpenseEvents.$inferSelect;
export type InsertV1ExpenseEvent = z.infer<typeof insertV1ExpenseEventSchema>;

// ─── Integration Infrastructure Tables ───────────────────────────────────────
// Spec: "Create Integration Infrastructure Tables for DriverHub / DriverConnect"
// These tables form the durable event tracing and logging layer for the
// Integration Module bridge between DriverHub and DriverConnect.

// integration_event_log
// Durable audit trail of every integration event processed between systems.
// Used for debugging sync issues and event traceability (spec Section 19).
export const integrationEventLog = pgTable("integration_event_log", {
  id:           varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  sourceSystem: varchar("source_system", { length: 50  }).notNull(),   // driverconnect | driverhub | system
  targetSystem: varchar("target_system", { length: 50  }).notNull(),   // driverhub | driverconnect
  entityType:   varchar("entity_type",   { length: 100 }).notNull(),   // move | driver | account | payment | etc.
  entityId:     varchar("entity_id",     { length: 255 }),
  eventType:    varchar("event_type",    { length: 100 }).notNull(),   // e.g. execution_event.received
  payloadJson:  jsonb("payload_json"),
  status:       varchar("status",        { length: 50  }).notNull().default("received"), // received | processed | failed
  errorMessage: text("error_message"),
  attemptCount: integer("attempt_count").notNull().default(0),
  createdAt:    timestamp("created_at").defaultNow(),
  processedAt:  timestamp("processed_at"),
});

export const insertIntegrationEventLogSchema = createInsertSchema(integrationEventLog).omit({ id: true, createdAt: true });
export type IntegrationEventLog = typeof integrationEventLog.$inferSelect;
export type InsertIntegrationEventLog = z.infer<typeof insertIntegrationEventLogSchema>;

// ============================================================
// REPAIR ESTIMATES
// ============================================================

export const repairEstimateStatusEnum = [
  "estimate_received",
  "approved_for_repair",
  "repair_in_progress",
  "repair_completed",
] as const;
export type RepairEstimateStatus = typeof repairEstimateStatusEnum[number];

export const repairEstimates = pgTable("repair_estimates", {
  id:                 varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  claimId:            varchar("claim_id").notNull().references(() => accidents.id, { onDelete: "cascade" }),
  vendorId:           varchar("vendor_id").references(() => vendors.id, { onDelete: "set null" }),
  vendorName:         varchar("vendor_name"),
  estimateDate:       timestamp("estimate_date"),
  estimateAmount:     decimal("estimate_amount", { precision: 10, scale: 2 }),
  repairStatus:       varchar("repair_status").notNull().default("estimate_received"),
  notes:              text("notes"),
  documentId:         varchar("document_id"),
  createdByUserId:    varchar("created_by_user_id").references(() => users.id, { onDelete: "set null" }),
  createdAt:          timestamp("created_at").notNull().defaultNow(),
  updatedAt:          timestamp("updated_at").notNull().defaultNow(),
});

export const insertRepairEstimateSchema = createInsertSchema(repairEstimates).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});
export type RepairEstimate = typeof repairEstimates.$inferSelect;
export type InsertRepairEstimate = z.infer<typeof insertRepairEstimateSchema>;

// ── Repair Supplements ─────────────────────────────────────────────────────
export const repairSupplements = pgTable("repair_supplements", {
  id:                 varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  claimId:            varchar("claim_id").notNull().references(() => accidents.id, { onDelete: "cascade" }),
  supplementDate:     timestamp("supplement_date"),
  supplementAmount:   decimal("supplement_amount", { precision: 10, scale: 2 }),
  supplementReason:   varchar("supplement_reason"),
  documentPath:       varchar("document_path"),
  notes:              text("notes"),
  createdByUserId:    varchar("created_by_user_id").references(() => users.id, { onDelete: "set null" }),
  createdAt:          timestamp("created_at").notNull().defaultNow(),
  updatedAt:          timestamp("updated_at").notNull().defaultNow(),
});

export const insertRepairSupplementSchema = createInsertSchema(repairSupplements).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});
export type RepairSupplement = typeof repairSupplements.$inferSelect;
export type InsertRepairSupplement = z.infer<typeof insertRepairSupplementSchema>;

// ─── SSO Tokens — short-lived cross-app identity tokens ──────────────────────
export const ssoTokens = pgTable("sso_tokens", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  tokenHash: varchar("token_hash").notNull().unique(),
  targetApp: varchar("target_app").notNull(), // e.g. "driverconnect"
  expiresAt: timestamp("expires_at").notNull(),
  usedAt: timestamp("used_at"), // set when exchanged — one-time use
  createdAt: timestamp("created_at").defaultNow().notNull(),
});
export type SsoToken = typeof ssoTokens.$inferSelect;

// ─── User App Entitlements — preferred structure for multi-app access ─────────
// Replaces hardcoded boolean columns on users. One row per (user, appCode).
// App codes: DRIVERHUB | DRIVERCONNECT (extensible for future apps)
export const userAppEntitlements = pgTable("user_app_entitlements", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  appCode: varchar("app_code").notNull(), // DRIVERHUB | DRIVERCONNECT
  accessGranted: boolean("access_granted").notNull().default(false),
  grantedAt: timestamp("granted_at"),
  revokedAt: timestamp("revoked_at"),
  grantedByUserId: varchar("granted_by_user_id").references(() => users.id, { onDelete: "set null" }),
  notes: text("notes"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (t) => ({
  uniqUserApp: { name: "uq_user_app_entitlements_user_app", columns: [t.userId, t.appCode] },
}));
export type UserAppEntitlement = typeof userAppEntitlements.$inferSelect;

// ─── DriverConnect Provisioned Users ─────────────────────────────────────────
// Tracks JIT-provisioned DriverConnect users. One row per DriverHub user.
// DriverConnect creates/updates this record on each successful login.
// This is stored in DriverHub as the authoritative provisioning registry.
export const dcProvisionedUsers = pgTable("dc_provisioned_users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  driverHubUserId: varchar("driver_hub_user_id").notNull().unique().references(() => users.id, { onDelete: "cascade" }),
  email: varchar("email"),
  firstName: varchar("first_name"),
  lastName: varchar("last_name"),
  dcLocalRole: varchar("dc_local_role").notNull(), // DriverConnect-side role
  driverHubRoleClassification: varchar("driver_hub_role_classification").notNull(), // Snapshot at provision time
  orgId: varchar("org_id"),
  homeMarket: varchar("home_market"),
  homeNetwork: varchar("home_network"),
  branchId: varchar("branch_id"),
  companyId: varchar("company_id"),
  scopeMarkets: text("scope_markets").array(),
  scopeNetworks: text("scope_networks").array(),
  scopeAccounts: text("scope_accounts").array(),
  status: varchar("status").notNull().default("ACTIVE"), // ACTIVE | INACTIVE | SUSPENDED
  provisionedAt: timestamp("provisioned_at").defaultNow().notNull(),
  lastSyncAt: timestamp("last_sync_at").defaultNow().notNull(),
  lastLoginAt: timestamp("last_login_at"),
  provisioningTrigger: varchar("provisioning_trigger").notNull().default("FIRST_LOGIN"), // FIRST_LOGIN | MANUAL | SYNC
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (t) => ({
  driverHubUserIdx: index("dc_provisioned_users_dh_user_idx").on(t.driverHubUserId),
  statusIdx: index("dc_provisioned_users_status_idx").on(t.status),
}));
export type DcProvisionedUser = typeof dcProvisionedUsers.$inferSelect;
export type InsertDcProvisionedUser = typeof dcProvisionedUsers.$inferInsert;

// ─── SSO Audit Log ────────────────────────────────────────────────────────────
// Records all significant SSO events across both DriverHub and DriverConnect.
// Event codes:
//   DriverHub: LOGIN_SUCCESS | LOGIN_FAILURE | ENTITLEMENT_DENIED | INACTIVE_DENIED
//              TOKEN_ISSUED | TOKEN_EXCHANGED | TOKEN_INVALID | TOKEN_EXPIRED | TOKEN_ALREADY_USED
//   DriverConnect: FIRST_PROVISION | REPEAT_LOGIN | ROLE_MAPPED | SCOPE_SEEDED
//                  ACCESS_DENIED_UNMAPPED_ROLE | ACCESS_DENIED_NO_SCOPE | ACCESS_DENIED_INACTIVE
export const ssoAuditLog = pgTable("sso_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").references(() => users.id, { onDelete: "set null" }),
  email: varchar("email"), // Captured even if userId is unknown
  app: varchar("app").notNull(), // DRIVERHUB | DRIVERCONNECT
  event: varchar("event").notNull(),
  success: boolean("success").notNull().default(true),
  denialReason: varchar("denial_reason"), // INACTIVE | NO_ENTITLEMENT | INVALID_TOKEN | UNMAPPED_ROLE | NO_SCOPE
  roleClassification: varchar("role_classification"),
  dcLocalRole: varchar("dc_local_role"),
  details: jsonb("details"), // Additional context
  ipAddress: varchar("ip_address"),
  userAgent: text("user_agent"),
  requestId: varchar("request_id"), // X-Request-Id or meta.requestId
  createdAt: timestamp("created_at").defaultNow().notNull(),
}, (t) => ({
  userIdx: index("sso_audit_log_user_idx").on(t.userId),
  appIdx: index("sso_audit_log_app_idx").on(t.app),
  eventIdx: index("sso_audit_log_event_idx").on(t.event),
  createdAtIdx: index("sso_audit_log_created_at_idx").on(t.createdAt),
}));
export type SsoAuditLogEntry = typeof ssoAuditLog.$inferSelect;

// ─── Integration Crosswalk ────────────────────────────────────────────────────
// Stable source-to-internal identifier mapping for recurring integrations.
// Prevents repeated guessing on subsequent syncs and ensures stable matching.
export const integrationCrosswalk = pgTable("integration_crosswalk", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  entityType: varchar("entity_type").notNull(), // driver | employee | contact
  internalRecordId: varchar("internal_record_id").notNull(),
  partnerSystem: varchar("partner_system").notNull(), // e.g. openforce, wiw, hubspot, csv_import
  partnerRecordId: varchar("partner_record_id"),
  sourceFullNameRaw: varchar("source_full_name_raw"), // original inbound full name string
  matchedOn: varchar("matched_on"), // email | phone | driver_number | employee_id | name_fallback | manual
  matchConfidence: varchar("match_confidence").notNull().default("auto"), // auto | manual | low
  lastSyncAt: timestamp("last_sync_at").defaultNow().notNull(),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (t) => ({
  entityTypeIdx: index("crosswalk_entity_type_idx").on(t.entityType),
  internalRecordIdx: index("crosswalk_internal_record_idx").on(t.internalRecordId),
  partnerSystemIdx: index("crosswalk_partner_system_idx").on(t.partnerSystem),
  uniquePartnerRecord: uniqueIndex("crosswalk_unique_partner").on(t.partnerSystem, t.partnerRecordId, t.entityType),
}));
export type IntegrationCrosswalk = typeof integrationCrosswalk.$inferSelect;
export type InsertIntegrationCrosswalk = typeof integrationCrosswalk.$inferInsert;

// ─── Rideshare Reconciliation ─────────────────────────────────────────────────
//
// Platform naming convention (enforced across all rideshare + transport tables):
//
//   account_id     = internal system join key.  Always a FK → customers(id).
//                    Use this column for all DB joins, FK constraints, and any
//                    server-side logic that resolves an account.
//
//   account_number = visible business key.  Denormalized from customers.customerNumber
//                    at write time and stored alongside account_id so that reports
//                    and CSV exports can display it without a live join.
//                    NEVER use account_number as a DB join key, FK target, or
//                    primary key.  It is a display/export field only.

export const rideshareIngestionBatches = pgTable("rideshare_ingestion_batches", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  provider: varchar("provider", { length: 20 }).notNull(), // 'uber' | 'lyft'
  fileName: text("file_name").notNull(),
  fileSizeBytes: integer("file_size_bytes"),
  status: varchar("status", { length: 20 }).notNull().default("processing"), // 'processing' | 'complete' | 'failed'
  totalRecords: integer("total_records").default(0),
  matchedRecords: integer("matched_records").default(0),
  unmatchedRecords: integer("unmatched_records").default(0),
  skippedRecords: integer("skipped_records").default(0), // duplicates skipped during import
  uploadedByUserId: varchar("uploaded_by_user_id"),
  errorMessage: text("error_message"),
  isDeleted: boolean("is_deleted").notNull().default(false),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  providerIdx: index("rideshare_batches_provider_idx").on(t.provider),
  statusIdx: index("rideshare_batches_status_idx").on(t.status),
  createdAtIdx: index("rideshare_batches_created_at_idx").on(t.createdAt),
}));
export type RideshareIngestionBatch = typeof rideshareIngestionBatches.$inferSelect;
export type InsertRideshareIngestionBatch = typeof rideshareIngestionBatches.$inferInsert;

export const rideshareRides = pgTable("rideshare_rides", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  batchId: varchar("batch_id").notNull().references(() => rideshareIngestionBatches.id),
  provider: varchar("provider", { length: 20 }).notNull(), // 'uber' | 'lyft'
  // ── Account linkage ──────────────────────────────────────────────────────
  // account_id   = internal system join key → customers(id). Always use this
  //                for DB joins and FK constraints. NEVER use account_number
  //                as the database join key or primary key.
  // account_number = visible business key retained as a denormalized field
  //                for all reports and CSV exports. Never requires a live join
  //                to display — always populated from customers.customerNumber
  //                at write time and stored alongside account_id.
  accountId: varchar("account_id").references(() => customers.id, { onDelete: "set null" }),
  accountNumber: varchar("account_number"), // denormalized from customers.customerNumber
  accountName: varchar("account_name"),     // denormalized from customers.companyName
  matchStatus: varchar("match_status", { length: 20 }).notNull().default("unmatched"), // 'matched' | 'unmatched' | 'dismissed'
  matchConfidence: varchar("match_confidence", { length: 20 }), // 'high' | 'medium' | 'low'
  matchMethod: varchar("match_method", { length: 50 }), // 'address_exact' | 'address_fuzzy' | 'manual'
  // Normalized ride data
  providerTripId: varchar("provider_trip_id"),
  rideDate: date("ride_date"),
  rideDatetime: timestamp("ride_datetime", { withTimezone: true }),
  pickupAddress: text("pickup_address"),
  dropoffAddress: text("dropoff_address"),
  passengerName: varchar("passenger_name"),
  driverName: varchar("driver_name"),
  fareAmount: numeric("fare_amount", { precision: 10, scale: 2 }),
  tipAmount: numeric("tip_amount", { precision: 10, scale: 2 }),
  totalAmount: numeric("total_amount", { precision: 10, scale: 2 }),
  distanceMiles: numeric("distance_miles", { precision: 8, scale: 2 }),
  durationMinutes: integer("duration_minutes"),
  rideStatus: varchar("ride_status", { length: 50 }),
  rideType: varchar("ride_type", { length: 50 }),
  city: varchar("city"),
  state: varchar("state"),
  // Column AB — trip/move linkage
  externalTripMoveRefRaw: varchar("external_trip_move_ref_raw"),
  externalTripMoveRefNormalized: varchar("external_trip_move_ref_normalized"),
  tripMoveRefType: varchar("trip_move_ref_type"), // 'move_id' | 'trip_id' | 'employee' | 'invalid' | 'unknown'
  linkedMoveId: varchar("linked_move_id"),
  linkedTripId: varchar("linked_trip_id"),
  linkStatus: varchar("link_status").default("unlinked"), // 'linked' | 'unlinked' | 'exception' | 'employee_expense'
  linkExceptionReason: varchar("link_exception_reason"),
  // Raw source data preserved
  rawData: jsonb("raw_data"),
  // Soft delete — set when the parent batch is deleted
  isDeleted: boolean("is_deleted").notNull().default(false),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  batchIdx: index("rideshare_rides_batch_idx").on(t.batchId),
  accountIdx: index("rideshare_rides_account_idx").on(t.accountId),
  matchStatusIdx: index("rideshare_rides_match_status_idx").on(t.matchStatus),
  rideDateIdx: index("rideshare_rides_ride_date_idx").on(t.rideDate),
  providerIdx: index("rideshare_rides_provider_idx").on(t.provider),
}));
export type RideshareRide = typeof rideshareRides.$inferSelect;
export type InsertRideshareRide = typeof rideshareRides.$inferInsert;

export const rideshareExceptions = pgTable("rideshare_exceptions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  rideId: varchar("ride_id").notNull().references(() => rideshareRides.id),
  batchId: varchar("batch_id").notNull(),
  reason: text("reason"),
  resolution: varchar("resolution", { length: 20 }).notNull().default("pending"), // 'pending' | 'matched' | 'dismissed'
  resolvedByUserId: varchar("resolved_by_user_id"),
  resolvedAt: timestamp("resolved_at", { withTimezone: true }),
  notes: text("notes"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  rideIdx: index("rideshare_exc_ride_idx").on(t.rideId),
  batchIdx: index("rideshare_exc_batch_idx").on(t.batchId),
  resolutionIdx: index("rideshare_exc_resolution_idx").on(t.resolution),
}));
export type RideshareException = typeof rideshareExceptions.$inferSelect;
export type InsertRideshareException = typeof rideshareExceptions.$inferInsert;

// ─── Rideshare Raw Data Storage Layer ────────────────────────────────────────
// Preserves every source column exactly as uploaded.
// Supports future reprocessing without requiring a re-upload.

export const rideshareImportBatches = pgTable("rideshare_import_batches", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  provider: varchar("provider", { length: 20 }).notNull(), // 'uber' | 'lyft'
  sourceFileName: text("source_file_name").notNull(),
  sourceFileType: varchar("source_file_type", { length: 10 }), // 'csv' | 'xlsx' | 'xls'
  uploadedByUserId: varchar("uploaded_by_user_id"),
  uploadedAt: timestamp("uploaded_at", { withTimezone: true }).defaultNow(),
  processingStatus: varchar("processing_status", { length: 20 }).notNull().default("uploaded"),
  // Status enum: 'uploaded' | 'parsing' | 'parsed' | 'matched' | 'completed' | 'failed'
  totalRows: integer("total_rows"),
  parsedRows: integer("parsed_rows").default(0),
  matchedRows: integer("matched_rows").default(0),
  exceptionRows: integer("exception_rows").default(0),
  failedRows: integer("failed_rows").default(0),
  notes: text("notes"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  providerIdx: index("rs_import_batches_provider_idx").on(t.provider),
  statusIdx: index("rs_import_batches_status_idx").on(t.processingStatus),
  uploadedAtIdx: index("rs_import_batches_uploaded_at_idx").on(t.uploadedAt),
  userIdx: index("rs_import_batches_user_idx").on(t.uploadedByUserId),
}));
export type RideshareImportBatch = typeof rideshareImportBatches.$inferSelect;
export type InsertRideshareImportBatch = typeof rideshareImportBatches.$inferInsert;

export const rideshareImportRawRows = pgTable("rideshare_import_raw_rows", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  importBatchId: varchar("import_batch_id").notNull().references(() => rideshareImportBatches.id),
  rowNumber: integer("row_number").notNull(), // 1-based row position in the source file
  provider: varchar("provider", { length: 20 }).notNull(), // denormalized for query convenience
  rawRowJson: jsonb("raw_row_json").notNull(), // full untouched column payload, no transforms
  processingStatus: varchar("processing_status", { length: 20 }).notNull().default("new"),
  // Status enum: 'new' | 'parsed' | 'matched' | 'exception' | 'failed'
  failureReason: text("failure_reason"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  batchIdx: index("rs_raw_rows_batch_idx").on(t.importBatchId),
  statusIdx: index("rs_raw_rows_status_idx").on(t.processingStatus),
  rowNumberIdx: index("rs_raw_rows_row_number_idx").on(t.importBatchId, t.rowNumber),
}));
export type RideshareImportRawRow = typeof rideshareImportRawRows.$inferSelect;
export type InsertRideshareImportRawRow = typeof rideshareImportRawRows.$inferInsert;

// ─── Platform Transport Transactions (Normalized) ────────────────────────────
// Universal historical data layer for all provider-sourced mobility and
// transport records: rideshare (Uber/Lyft), future delivery, corporate
// shuttle, charter, and DriverConnect moves.
//
// Design principles:
//   1. matched_account_id is the PRIMARY internal join to customers(id).
//      matched_account_number is RETAINED as a denormalized field for all
//      business reports and exports — never requires a live join to display.
//   2. Platform join keys (move_id, invoice_id, payment_id, driver_id,
//      market_id) are nullable FKs that are populated incrementally as
//      cross-entity associations are established — they are never required
//      at insert time.
//   3. service_category classifies the record type so this single table
//      supports future non-rideshare transport categories without schema
//      changes.  record_source tracks the originating system for full
//      data provenance.
//   4. Rows are NEVER hard-deleted.  is_archived=false (default) = live
//      operational record.  is_archived=true = excluded from operational
//      views but retained in full for long-term analytics and audit.
//      All rows must be preserved indefinitely.

export const rideshareTransactions = pgTable("rideshare_transactions", {
  // ── Identity ────────────────────────────────────────────────────────────
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  importBatchId: varchar("import_batch_id").references(() => rideshareImportBatches.id),
  rawRowId: varchar("raw_row_id").references(() => rideshareImportRawRows.id),

  // ── Data layer classification ────────────────────────────────────────────
  // service_category makes the table reusable across all transport types.
  serviceCategory: varchar("service_category", { length: 50 }).notNull().default("rideshare"),
  // Enum: 'rideshare' | 'delivery' | 'corporate_shuttle' | 'charter' | 'other'
  recordSource: varchar("record_source", { length: 50 }),
  // Enum: 'uber_import' | 'lyft_import' | 'manual' | 'api' | 'driverconnect'

  // ── Provider / trip identity ─────────────────────────────────────────────
  provider: varchar("provider", { length: 20 }).notNull(), // 'uber' | 'lyft' | future providers
  providerTripId: varchar("provider_trip_id"),
  providerStatementId: varchar("provider_statement_id"),
  serviceType: varchar("service_type", { length: 100 }),
  rideStatus: varchar("ride_status", { length: 50 }),

  // ── Date / time ──────────────────────────────────────────────────────────
  rideDate: date("ride_date"),
  rideDatetime: timestamp("ride_datetime", { withTimezone: true }),
  pickupDatetime: timestamp("pickup_datetime", { withTimezone: true }),
  dropoffDatetime: timestamp("dropoff_datetime", { withTimezone: true }),

  // ── People ───────────────────────────────────────────────────────────────
  riderName: varchar("rider_name", { length: 255 }),
  riderEmail: varchar("rider_email", { length: 255 }),
  riderEmployeeReference: varchar("rider_employee_reference", { length: 255 }),

  // ── Addresses — raw (as received) and normalized (post-processing) ───────
  pickupAddressRaw: text("pickup_address_raw"),
  dropoffAddressRaw: text("dropoff_address_raw"),
  pickupAddressNormalized: text("pickup_address_normalized"),
  dropoffAddressNormalized: text("dropoff_address_normalized"),
  pickupLat: decimal("pickup_lat", { precision: 10, scale: 7 }),
  pickupLng: decimal("pickup_lng", { precision: 10, scale: 7 }),
  dropoffLat: decimal("dropoff_lat", { precision: 10, scale: 7 }),
  dropoffLng: decimal("dropoff_lng", { precision: 10, scale: 7 }),

  // ── Account matching ─────────────────────────────────────────────────────
  // matched_account_id is the PRIMARY reporting join key to customers(id).
  // matched_account_number is ALWAYS retained as a denormalized visible field.
  // Dual pickup/dropoff account fields support split-leg billing models.
  pickupAccountId: varchar("pickup_account_id").references(() => customers.id),
  pickupAccountNumber: varchar("pickup_account_number", { length: 100 }),
  dropoffAccountId: varchar("dropoff_account_id").references(() => customers.id),
  dropoffAccountNumber: varchar("dropoff_account_number", { length: 100 }),
  matchedAccountId: varchar("matched_account_id").references(() => customers.id),
  matchedAccountNumber: varchar("matched_account_number", { length: 100 }),
  matchMethod: varchar("match_method", { length: 30 }),
  // Enum: 'exact_normalized' | 'alias' | 'manual' | 'future_geo' | 'future_fuzzy'
  matchConfidence: decimal("match_confidence", { precision: 5, scale: 4 }),
  matchStatus: varchar("match_status", { length: 30 }).notNull().default("unmatched"),
  // Enum: 'auto_matched' | 'manual_matched' | 'exception' | 'unmatched'

  // ── Platform join keys ───────────────────────────────────────────────────
  // All nullable FKs — populated incrementally as cross-entity associations
  // are established.  Never required at insert time.
  // market_code is a denormalized copy of markets.code for export visibility.
  moveId:      varchar("move_id").references(() => moves.id),
  invoiceId:   varchar("invoice_id").references(() => invoices.id),
  paymentId:   varchar("payment_id").references(() => payments.id),
  driverId:    varchar("driver_id").references(() => drivers.id),
  marketId:    varchar("market_id").references(() => markets.id),
  marketCode:  varchar("market_code", { length: 20 }),
  // Mirrors markets.code — retained for exports without requiring a join.

  // ── Provider / trip — extended ───────────────────────────────────────────
  programName: varchar("program_name", { length: 255 }),     // Uber: Program
  groupName: varchar("group_name", { length: 255 }),          // Uber: Group
  country: varchar("country", { length: 100 }),
  city: varchar("city", { length: 100 }),

  // ── Date / time — extended ───────────────────────────────────────────────
  // rideDatetime / pickupDatetime / dropoffDatetime (above) = UTC canonical.
  // Uber provides multiple representations; all are stored for audit/re-processing.
  transactionTimestampUtc: timestamp("transaction_timestamp_utc", { withTimezone: true }),
  requestDatetimeLocal: timestamp("request_datetime_local"),    // local time, no tz stored
  dropoffDatetimeLocal: timestamp("dropoff_datetime_local"),
  timezoneOffset: varchar("timezone_offset", { length: 20 }), // e.g. "-06:00"

  // ── People — extended ────────────────────────────────────────────────────
  riderFirstName: varchar("rider_first_name", { length: 100 }),
  riderLastName: varchar("rider_last_name", { length: 100 }),
  guestName: varchar("guest_name", { length: 255 }),           // Guest first + last concatenated

  // ── Trip metrics ──────────────────────────────────────────────────────────
  distanceMiles: decimal("distance_miles", { precision: 8, scale: 2 }),
  durationMinutes: integer("duration_minutes"),

  // ── Financial — canonical (USD billing) ──────────────────────────────────
  // totalFare = Total Fare USD — primary billing amount used in all reports.
  // baseFare, tips, taxes kept for backward-compat and cross-provider reporting.
  totalFare: decimal("total_fare", { precision: 10, scale: 2 }),
  baseFare: decimal("base_fare", { precision: 10, scale: 2 }),
  tolls: decimal("tolls", { precision: 10, scale: 2 }),
  fees: decimal("fees", { precision: 10, scale: 2 }),
  tips: decimal("tips", { precision: 10, scale: 2 }),
  taxes: decimal("taxes", { precision: 10, scale: 2 }),
  currencyCode: varchar("currency_code", { length: 10 }).default("USD"),

  // ── Financial — local currency ────────────────────────────────────────────
  // Preserved exactly as received from the provider for reconciliation and audit.
  // USD equivalents are in the USD section below.
  transactionAmountLocal: decimal("transaction_amount_local", { precision: 10, scale: 2 }),
  baseFareLocal: decimal("base_fare_local", { precision: 10, scale: 2 }),
  bookingFeeLocal: decimal("booking_fee_local", { precision: 10, scale: 2 }),
  airportFeeLocal: decimal("airport_fee_local", { precision: 10, scale: 2 }),
  cityFeeLocal: decimal("city_fee_local", { precision: 10, scale: 2 }),
  tollFeeLocal: decimal("toll_fee_local", { precision: 10, scale: 2 }),
  deliveryFeeLocal: decimal("delivery_fee_local", { precision: 10, scale: 2 }),
  discountsLocal: decimal("discounts_local", { precision: 10, scale: 2 }),
  tipLocal: decimal("tip_local", { precision: 10, scale: 2 }),
  otherChargesLocal: decimal("other_charges_local", { precision: 10, scale: 2 }),
  totalFareLocal: decimal("total_fare_local", { precision: 10, scale: 2 }),
  totalTaxesLocal: decimal("total_taxes_local", { precision: 10, scale: 2 }),
  employeeGuestPaymentLocal: decimal("employee_guest_payment_local", { precision: 10, scale: 2 }),
  membershipSavingsLocal: decimal("membership_savings_local", { precision: 10, scale: 2 }),
  localCurrencyCode: varchar("local_currency_code", { length: 10 }),

  // ── Financial — USD ───────────────────────────────────────────────────────
  // totalFare (above) is the canonical USD billing amount.
  // These fields are supplementary USD line items from the Uber export.
  transactionAmountUsd: decimal("transaction_amount_usd", { precision: 10, scale: 2 }),
  tipUsd: decimal("tip_usd", { precision: 10, scale: 2 }),
  totalTaxesUsd: decimal("total_taxes_usd", { precision: 10, scale: 2 }),
  employeeGuestPaymentUsd: decimal("employee_guest_payment_usd", { precision: 10, scale: 2 }),
  estimatedServiceTechFeeUsd: decimal("estimated_service_tech_fee_usd", { precision: 10, scale: 2 }),
  estimatedIntegrationFeeUsd: decimal("estimated_integration_fee_usd", { precision: 10, scale: 2 }),

  // ── Billing / reference ───────────────────────────────────────────────────
  expenseCode: varchar("expense_code", { length: 255 }),
  expenseMemo: text("expense_memo"),
  paymentMethod: varchar("payment_method", { length: 100 }),
  invoicesReference: text("invoices_reference"),                         // raw provider invoices field
  providerInvoiceNumber: varchar("provider_invoice_number", { length: 100 }), // distinct from FK invoiceId
  voucherProgram: varchar("voucher_program", { length: 255 }),
  voucherProgramExpenseMemo: text("voucher_program_expense_memo"),
  voucherLink: text("voucher_link"),
  voucherPolicy: varchar("voucher_policy", { length: 255 }),
  voucherCampaignId: varchar("voucher_campaign_id", { length: 100 }),
  integrationPartner: varchar("integration_partner", { length: 255 }),

  // ── Additional source preservation ───────────────────────────────────────
  // All raw provider fields preserved verbatim for audit and future re-processing.
  fulfillmentType: varchar("fulfillment_type", { length: 100 }),
  cancellationType: varchar("cancellation_type", { length: 100 }),
  isGroupOrder: boolean("is_group_order"),
  storeName: varchar("store_name", { length: 255 }),
  orderItemsRaw: text("order_items_raw"),      // Uber "Order Items" raw string
  stopDetailsRaw: text("stop_details_raw"),    // Uber "Stop Details" raw string
  hasMultipleStops: boolean("has_multiple_stops"),

  // ── Reporting / workflow ─────────────────────────────────────────────────
  exceptionReason: text("exception_reason"),
  reviewedByUserId: varchar("reviewed_by_user_id"),
  reviewedAt: timestamp("reviewed_at", { withTimezone: true }),
  billingStatus: varchar("billing_status", { length: 30 }).notNull().default("unreviewed"),
  // Enum: 'unreviewed' | 'ready_for_billing' | 'billed' | 'excluded' | 'needs_followup'

  // ── Billing workflow fields ───────────────────────────────────────────────
  billingReadyAt:          timestamp("billing_ready_at",           { withTimezone: true }),
  billingReadyByUserId:    varchar("billing_ready_by_user_id",     { length: 255 }),
  billedAt:                timestamp("billed_at",                  { withTimezone: true }),
  billedByUserId:          varchar("billed_by_user_id",            { length: 255 }),
  billingNotes:            text("billing_notes"),
  invoiceNumberSnapshot:   varchar("invoice_number_snapshot",      { length: 100 }),
  billableAmount:          decimal("billable_amount",              { precision: 12, scale: 2 }),
  billToAccountId:         varchar("bill_to_account_id").references(() => customers.id),
  billToAccountNumber:     varchar("bill_to_account_number",       { length: 100 }),

  // ── Aggregation linkage ───────────────────────────────────────────────────
  // Populated when the transaction is included in a billing aggregate (weekly grouping)
  invoiceLineItemId:       varchar("invoice_line_item_id").references(() => invoiceLineItems.id, { onDelete: "set null" }),
  aggregationGroupId:      varchar("aggregation_group_id"),     // FK to rideshare_billing_aggregates.id (set after agg created)
  billingPeriodStart:      date("billing_period_start"),        // Week start date (Monday) derived from local ride time
  billingPeriodEnd:        date("billing_period_end"),          // Week end date (Sunday) derived from local ride time
  billingWeekLabel:        varchar("billing_week_label", { length: 30 }), // "MM/DD/YYYY – MM/DD/YYYY"

  // ── Historical retention ──────────────────────────────────────────────────
  // Rows are NEVER hard-deleted from this table.
  // is_archived=false (default): active operational record.
  // is_archived=true: excluded from operational views; retained for analytics.
  isArchived: boolean("is_archived").notNull().default(false),

  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  // ── Ingestion traceability ───────────────────────────────────────────────
  batchIdx:         index("rs_tx_batch_idx").on(t.importBatchId),
  rawRowIdx:        index("rs_tx_raw_row_idx").on(t.rawRowId),
  // ── Provider / trip ──────────────────────────────────────────────────────
  providerIdx:      index("rs_tx_provider_idx").on(t.provider),
  providerTripIdx:  index("rs_tx_provider_trip_idx").on(t.providerTripId),
  // ── Classification ───────────────────────────────────────────────────────
  serviceCatIdx:    index("rs_tx_service_cat_idx").on(t.serviceCategory),
  recordSourceIdx:  index("rs_tx_record_source_idx").on(t.recordSource),
  // ── Matching & billing ───────────────────────────────────────────────────
  matchStatusIdx:   index("rs_tx_match_status_idx").on(t.matchStatus),
  billingStatusIdx: index("rs_tx_billing_status_idx").on(t.billingStatus),
  // ── Time ─────────────────────────────────────────────────────────────────
  rideDateIdx:      index("rs_tx_ride_date_idx").on(t.rideDate),
  // ── Account joins ────────────────────────────────────────────────────────
  matchedAcctIdx:   index("rs_tx_matched_acct_idx").on(t.matchedAccountId),
  pickupAcctIdx:    index("rs_tx_pickup_acct_idx").on(t.pickupAccountId),
  dropoffAcctIdx:   index("rs_tx_dropoff_acct_idx").on(t.dropoffAccountId),
  // ── Platform join keys ───────────────────────────────────────────────────
  moveIdx:          index("rs_tx_move_idx").on(t.moveId),
  invoiceIdx:       index("rs_tx_invoice_idx").on(t.invoiceId),
  billToAcctIdx:    index("rs_tx_bill_to_acct_idx").on(t.billToAccountId),
  paymentIdx:       index("rs_tx_payment_idx").on(t.paymentId),
  driverIdx:        index("rs_tx_driver_idx").on(t.driverId),
  marketIdx:        index("rs_tx_market_idx").on(t.marketId),
  // ── Historical retention ──────────────────────────────────────────────────
  archivedIdx:      index("rs_tx_archived_idx").on(t.isArchived),
}));
export type RideshareTransaction = typeof rideshareTransactions.$inferSelect;
export type InsertRideshareTransaction = typeof rideshareTransactions.$inferInsert;

// ─── Rideshare Billing Audit ──────────────────────────────────────────────────
// Immutable audit log for all billing state transitions on rideshare_transactions.
// Every mark-ready, exclude, push-to-invoice, or billing-reopen action is logged here.

export const rideshareBillingAudit = pgTable("rideshare_billing_audit", {
  id:                    varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  rideshareTransactionId: varchar("rideshare_transaction_id").notNull().references(() => rideshareTransactions.id),
  // Action types: marked_ready | marked_excluded | pushed_to_invoice | billing_reopened | billing_notes_updated
  actionType:            varchar("action_type", { length: 50 }).notNull(),
  priorBillingStatus:    varchar("prior_billing_status", { length: 30 }),
  newBillingStatus:      varchar("new_billing_status",   { length: 30 }),
  actedByUserId:         varchar("acted_by_user_id",     { length: 255 }),
  actedAt:               timestamp("acted_at", { withTimezone: true }).defaultNow(),
  notes:                 text("notes"),
  invoiceId:             varchar("invoice_id").references(() => invoices.id, { onDelete: "set null" }),
  invoiceNumberSnapshot: varchar("invoice_number_snapshot", { length: 100 }),
  // Additional metadata for push-to-invoice batches
  batchRef:              varchar("batch_ref",             { length: 100 }), // groups records pushed together
  billableAmount:        decimal("billable_amount",       { precision: 12, scale: 2 }),
  billToAccountId:       varchar("bill_to_account_id"),
  billToAccountNumber:   varchar("bill_to_account_number", { length: 100 }),
}, (t) => ({
  txIdx:       index("rs_billing_audit_tx_idx").on(t.rideshareTransactionId),
  actedAtIdx:  index("rs_billing_audit_acted_at_idx").on(t.actedAt),
  actionIdx:   index("rs_billing_audit_action_idx").on(t.actionType),
  batchRefIdx: index("rs_billing_audit_batch_ref_idx").on(t.batchRef),
}));
export type RideshareBillingAudit = typeof rideshareBillingAudit.$inferSelect;
export type InsertRideshareBillingAudit = typeof rideshareBillingAudit.$inferInsert;

// ─── Rideshare Billing Aggregates ─────────────────────────────────────────────
// One row per (account × billing_period) grouping pushed to invoice.
// Each aggregate maps to ONE invoice line item (the "DriverReturn" summary line).

export const rideshareBillingAggregates = pgTable("rideshare_billing_aggregates", {
  id:                  varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  accountId:           varchar("account_id").notNull().references(() => customers.id),
  accountNumber:       varchar("account_number",        { length: 100 }),
  accountName:         varchar("account_name",          { length: 255 }),
  billingPeriodStart:  date("billing_period_start").notNull(),
  billingPeriodEnd:    date("billing_period_end").notNull(),
  totalRides:          integer("total_rides").notNull().default(0),
  totalAmount:         decimal("total_amount",          { precision: 12, scale: 2 }).notNull().default("0.00"),
  invoiceId:           varchar("invoice_id").references(() => invoices.id, { onDelete: "set null" }),
  invoiceLineItemId:   varchar("invoice_line_item_id").references(() => invoiceLineItems.id, { onDelete: "set null" }),
  invoiceNumberSnapshot: varchar("invoice_number_snapshot", { length: 100 }),
  batchRef:            varchar("batch_ref",             { length: 100 }),  // groups aggregates from same push
  createdAt:           timestamp("created_at", { withTimezone: true }).defaultNow(),
  createdByUserId:     varchar("created_by_user_id",    { length: 255 }),
}, (t) => ({
  accountIdx:       index("rs_agg_account_idx").on(t.accountId),
  periodIdx:        index("rs_agg_period_idx").on(t.billingPeriodStart, t.billingPeriodEnd),
  accountPeriodIdx: index("rs_agg_account_period_idx").on(t.accountId, t.billingPeriodStart, t.billingPeriodEnd),
  invoiceIdx:       index("rs_agg_invoice_idx").on(t.invoiceId),
  batchRefIdx:      index("rs_agg_batch_ref_idx").on(t.batchRef),
}));
export type RideshareBillingAggregate = typeof rideshareBillingAggregates.$inferSelect;
export type InsertRideshareBillingAggregate = typeof rideshareBillingAggregates.$inferInsert;

// ─── Rideshare Billing Aggregate Items ────────────────────────────────────────
// Linkage table: maps each individual rideshare_transaction to a billing aggregate.
// Enables full ride-level drilldown from any invoice or aggregate.

export const rideshareBillingAggregateItems = pgTable("rideshare_billing_aggregate_items", {
  id:                    varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  aggregateId:           varchar("aggregate_id").notNull().references(() => rideshareBillingAggregates.id, { onDelete: "cascade" }),
  rideshareTransactionId: varchar("rideshare_transaction_id").notNull().references(() => rideshareTransactions.id),
}, (t) => ({
  aggregateIdx:  index("rs_agg_items_aggregate_idx").on(t.aggregateId),
  txIdx:         index("rs_agg_items_tx_idx").on(t.rideshareTransactionId),
}));
export type RideshareBillingAggregateItem = typeof rideshareBillingAggregateItems.$inferSelect;
export type InsertRideshareBillingAggregateItem = typeof rideshareBillingAggregateItems.$inferInsert;

// ─── Account Address Reference ────────────────────────────────────────────────
// Multiple addresses per account for rideshare matching, future aliasing,
// and geospatial matching.  Matching uses only is_active rows; billing
// assignment uses is_billing_eligible rows unless manually overridden.

export const accountAddressReference = pgTable("account_address_reference", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  accountId: varchar("account_id").notNull().references(() => customers.id),
  accountNumber: varchar("account_number", { length: 100 }),
  addressLabel: varchar("address_label", { length: 255 }),
  addressType: varchar("address_type", { length: 20 }).notNull().default("other"),
  // Enum: 'primary' | 'billing' | 'service' | 'pickup' | 'dropoff' | 'branch' | 'other'
  addressRaw: text("address_raw"),
  addressNormalized: text("address_normalized"),
  latitude: decimal("latitude", { precision: 10, scale: 7 }),
  longitude: decimal("longitude", { precision: 10, scale: 7 }),
  isActive: boolean("is_active").notNull().default(true),
  isBillingEligible: boolean("is_billing_eligible").notNull().default(false),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  accountIdx:        index("acct_addr_ref_account_idx").on(t.accountId),
  accountNumberIdx:  index("acct_addr_ref_account_number_idx").on(t.accountNumber),
  typeIdx:           index("acct_addr_ref_type_idx").on(t.addressType),
  activeIdx:         index("acct_addr_ref_active_idx").on(t.isActive),
  billingIdx:        index("acct_addr_ref_billing_idx").on(t.isBillingEligible),
  activeBillingIdx:  index("acct_addr_ref_active_billing_idx").on(t.accountId, t.isActive, t.isBillingEligible),
}));
export type AccountAddressReference = typeof accountAddressReference.$inferSelect;
export type InsertAccountAddressReference = typeof accountAddressReference.$inferInsert;

// ─── Rideshare Export Log ──────────────────────────────────────────────────
export const rideshareExportLog = pgTable("rideshare_export_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id"),
  exportType: varchar("export_type", { length: 50 }).notNull().default("billing_detail"),
  accountId: varchar("account_id").references(() => customers.id, { onDelete: "set null" }),
  accountNumber: varchar("account_number", { length: 100 }),
  accountName: varchar("account_name", { length: 255 }),
  billingPeriodStart: date("billing_period_start"),
  billingPeriodEnd: date("billing_period_end"),
  invoiceId: varchar("invoice_id").references(() => invoices.id, { onDelete: "set null" }),
  invoiceNumber: varchar("invoice_number", { length: 100 }),
  provider: varchar("provider", { length: 50 }),
  rowCount: integer("row_count"),
  totalAmount: decimal("total_amount", { precision: 12, scale: 2 }),
  format: varchar("format", { length: 10 }).notNull().default("csv"),
  exportedAt: timestamp("exported_at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => ({
  userIdx:    index("rs_export_log_user_idx").on(t.userId),
  acctIdx:    index("rs_export_log_acct_idx").on(t.accountId),
  invoiceIdx: index("rs_export_log_invoice_idx").on(t.invoiceId),
  dateIdx:    index("rs_export_log_date_idx").on(t.exportedAt),
}));
export type RideshareExportLog = typeof rideshareExportLog.$inferSelect;
export type InsertRideshareExportLog = typeof rideshareExportLog.$inferInsert;

export const rideshareRejectedRows = pgTable("rideshare_rejected_rows", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  batchId: varchar("batch_id").notNull().references(() => rideshareIngestionBatches.id, { onDelete: "cascade" }),
  // Optional FK to the NEW import batch system (rideshare_import_batches).
  // Set when the upload route runs the canonical parser (runRideshareImport) before inserting rejected rows.
  // Used by the reconciliation engine to tie rejected rows to the canonical import batch.
  importBatchId: varchar("import_batch_id").references(() => rideshareImportBatches.id, { onDelete: "set null" }),
  provider: varchar("provider", { length: 50 }).notNull(),
  rowNumber: integer("row_number"),
  providerTripId: varchar("provider_trip_id", { length: 255 }),
  rideDate: varchar("ride_date", { length: 50 }),
  pickupAddress: text("pickup_address"),
  dropoffAddress: text("dropoff_address"),
  passengerName: varchar("passenger_name", { length: 255 }),
  totalAmount: decimal("total_amount", { precision: 12, scale: 2 }),
  rejectionCode: varchar("rejection_code", { length: 100 }).notNull(),
  rejectionDetail: varchar("rejection_detail", { length: 500 }),
  rejectionReason: text("rejection_reason").notNull(),
  rawData: jsonb("raw_data"),
  reprocessStatus: varchar("reprocess_status", { length: 50 }).notNull().default("pending"),
  reprocessedRideId: varchar("reprocessed_ride_id"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => ({
  batchIdx: index("rs_rejected_batch_idx").on(t.batchId),
  importBatchIdx: index("rs_rejected_import_batch_idx").on(t.importBatchId),
  tripIdIdx: index("rs_rejected_trip_id_idx").on(t.providerTripId),
  statusIdx: index("rs_rejected_reprocess_status_idx").on(t.reprocessStatus),
}));
export type RideshareRejectedRow = typeof rideshareRejectedRows.$inferSelect;
export type InsertRideshareRejectedRow = typeof rideshareRejectedRows.$inferInsert;

// ─── Batch Reconciliation Summary ─────────────────────────────────────────────
// Persisted per-import-batch reconciliation: row counts + dollar totals + balance flags.
// Computed automatically after each upload; recomputable on demand.
// reconciliation_status: 'balanced' | 'mismatch' | 'pending'
export const rideshareBatchReconciliation = pgTable("rideshare_batch_reconciliation", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  importBatchId: varchar("import_batch_id").notNull().unique()
    .references(() => rideshareImportBatches.id, { onDelete: "cascade" }),

  // ── Row counts ─────────────────────────────────────────────────────────────
  totalRowsInFile:      integer("total_rows_in_file").notNull().default(0),
  importedRows:         integer("imported_rows").notNull().default(0),
  rejectedRows:         integer("rejected_rows").notNull().default(0),
  duplicateRows:        integer("duplicate_rows").notNull().default(0),
  employeeExpenseRows:  integer("employee_expense_rows").notNull().default(0),

  // ── Dollar totals ──────────────────────────────────────────────────────────
  fileTotalAmount:      decimal("file_total_amount",     { precision: 14, scale: 2 }).notNull().default("0"),
  importedTotalAmount:  decimal("imported_total_amount", { precision: 14, scale: 2 }).notNull().default("0"),
  rejectedTotalAmount:  decimal("rejected_total_amount", { precision: 14, scale: 2 }).notNull().default("0"),
  duplicateTotalAmount: decimal("duplicate_total_amount",{ precision: 14, scale: 2 }).notNull().default("0"),
  employeeTotalAmount:  decimal("employee_total_amount", { precision: 14, scale: 2 }).notNull().default("0"),

  // ── Balance check ──────────────────────────────────────────────────────────
  totalAccountedRows:   integer("total_accounted_rows").notNull().default(0),
  totalAccountedAmount: decimal("total_accounted_amount",{ precision: 14, scale: 2 }).notNull().default("0"),
  rowBalanced:          boolean("row_balanced").notNull().default(false),
  amountBalanced:       boolean("amount_balanced").notNull().default(true),
  reconciliationStatus: varchar("reconciliation_status", { length: 20 }).notNull().default("pending"),

  computedAt: timestamp("computed_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  importBatchIdx: index("rs_recon_import_batch_idx").on(t.importBatchId),
  statusIdx: index("rs_recon_status_idx").on(t.reconciliationStatus),
}));
export type RideshareBatchReconciliation = typeof rideshareBatchReconciliation.$inferSelect;
export type InsertRideshareBatchReconciliation = typeof rideshareBatchReconciliation.$inferInsert;

// ─────────────────────────────────────────────────────────────────────────────
// OPENFORCE RECONCILIATION & LABOR COST ENGINE
// Mirrors the Rideshare Reconciliation architecture:
//   1. openforce_import_batches  — per-file upload tracking
//   2. openforce_import_raw_rows — immutable raw payload per row
//   3. openforce_transactions    — normalized, matched, reconciled records
// ─────────────────────────────────────────────────────────────────────────────

export const openforceImportBatches = pgTable("openforce_import_batches", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  sourceFileName: text("source_file_name").notNull(),
  sourceFileType: varchar("source_file_type", { length: 10 }),
  uploadedByUserId: varchar("uploaded_by_user_id"),
  uploadedAt: timestamp("uploaded_at", { withTimezone: true }).defaultNow(),
  processingStatus: varchar("processing_status", { length: 30 }).notNull().default("uploaded"),
  // Status enum: 'uploaded'|'parsing'|'parsed'|'matching'|'matched'|'committed'|'failed'
  settlementPeriodStart: date("settlement_period_start"),
  settlementPeriodEnd: date("settlement_period_end"),
  totalRows: integer("total_rows"),
  parsedRows: integer("parsed_rows").default(0),
  matchedRows: integer("matched_rows").default(0),
  exceptionRows: integer("exception_rows").default(0),
  totalGrossPay: numeric("total_gross_pay", { precision: 14, scale: 2 }),
  totalNetPay: numeric("total_net_pay", { precision: 14, scale: 2 }),
  resolvedRows: integer("resolved_rows").default(0),
  unresolvedRows: integer("unresolved_rows").default(0),
  notes: text("notes"),
  isArchived: boolean("is_archived").default(false),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  statusIdx: index("of_batches_status_idx").on(t.processingStatus),
  dateIdx:   index("of_batches_date_idx").on(t.uploadedAt),
  userIdx:   index("of_batches_user_idx").on(t.uploadedByUserId),
}));
export type OpenforceImportBatch = typeof openforceImportBatches.$inferSelect;
export type InsertOpenforceImportBatch = typeof openforceImportBatches.$inferInsert;

export const openforceImportRawRows = pgTable("openforce_import_raw_rows", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  importBatchId: varchar("import_batch_id").notNull().references(() => openforceImportBatches.id),
  rowNumber: integer("row_number").notNull(),
  rawRowJson: jsonb("raw_row_json").notNull(),
  processingStatus: varchar("processing_status", { length: 20 }).notNull().default("new"),
  // Status: 'new'|'parsed'|'matched'|'exception'|'failed'
  failureReason: text("failure_reason"),
  transactionId: varchar("transaction_id"), // populated after commit
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  batchIdx:  index("of_raw_rows_batch_idx").on(t.importBatchId),
  statusIdx: index("of_raw_rows_status_idx").on(t.processingStatus),
  rowIdx:    index("of_raw_rows_row_idx").on(t.importBatchId, t.rowNumber),
}));
export type OpenforceImportRawRow = typeof openforceImportRawRows.$inferSelect;
export type InsertOpenforceImportRawRow = typeof openforceImportRawRows.$inferInsert;

export const openforceTransactions = pgTable("openforce_transactions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  importBatchId: varchar("import_batch_id").references(() => openforceImportBatches.id),
  rawRowId: varchar("raw_row_id").references(() => openforceImportRawRows.id),

  // ── OpenForce identity ────────────────────────────────────────────────────
  openforceId: varchar("openforce_id", { length: 100 }),
  settlementId: varchar("settlement_id", { length: 100 }),

  // ── Pay period ────────────────────────────────────────────────────────────
  periodStart: date("period_start"),
  periodEnd: date("period_end"),

  // ── Driver (as received) ──────────────────────────────────────────────────
  rawDriverName: varchar("raw_driver_name", { length: 255 }),

  // ── Driver match (internal) ───────────────────────────────────────────────
  matchedDriverId: varchar("matched_driver_id").references(() => drivers.id),
  matchStatus: varchar("match_status", { length: 30 }).notNull().default("unmatched"),
  // 'matched' | 'unmatched' | 'exception' | 'excluded'

  // ── Pay data ─────────────────────────────────────────────────────────────
  hoursWorked: numeric("hours_worked", { precision: 8, scale: 2 }),
  tripsCompleted: integer("trips_completed"),
  grossPay: numeric("gross_pay", { precision: 14, scale: 2 }),
  deductions: numeric("deductions", { precision: 14, scale: 2 }).default("0"),
  netPay: numeric("net_pay", { precision: 14, scale: 2 }),

  // ── Calculated rates (populated during reconciliation engine) ─────────────
  effectiveHourlyRate: numeric("effective_hourly_rate", { precision: 10, scale: 4 }),
  effectivePerTripRate: numeric("effective_per_trip_rate", { precision: 10, scale: 4 }),
  costPerMove: numeric("cost_per_move", { precision: 10, scale: 4 }),

  // ── Variance flags ────────────────────────────────────────────────────────
  hourlyRateVariancePct: numeric("hourly_rate_variance_pct", { precision: 8, scale: 2 }),
  tripRateVariancePct: numeric("trip_rate_variance_pct", { precision: 8, scale: 2 }),

  // ── Exception tracking ────────────────────────────────────────────────────
  hasException: boolean("has_exception").default(false),
  exceptionType: varchar("exception_type", { length: 100 }),
  // 'missing_driver'|'not_ic'|'duplicate'|'abnormal_rate'|'missing_hours'|'missing_trips'
  exceptionNote: text("exception_note"),
  exceptionResolvedAt: timestamp("exception_resolved_at", { withTimezone: true }),
  exceptionResolvedBy: varchar("exception_resolved_by"),
  exceptionResolution: text("exception_resolution"),

  // ── Account linkage (via driver assignments) ──────────────────────────────
  linkedAccountId: varchar("linked_account_id"),
  linkedAccountName: varchar("linked_account_name"),
  linkedAccountNumber: varchar("linked_account_number"),

  // ── Workflow state ────────────────────────────────────────────────────────
  billingStatus: varchar("billing_status", { length: 30 }).default("pending"),
  // 'pending'|'verified'|'disputed'|'excluded'

  isArchived: boolean("is_archived").default(false),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  batchIdx:     index("of_tx_batch_idx").on(t.importBatchId),
  driverIdx:    index("of_tx_driver_idx").on(t.matchedDriverId),
  openforceIdx: index("of_tx_openforce_idx").on(t.openforceId),
  matchIdx:     index("of_tx_match_idx").on(t.matchStatus),
  periodIdx:    index("of_tx_period_idx").on(t.periodStart, t.periodEnd),
  accountIdx:   index("of_tx_account_idx").on(t.linkedAccountId),
  exceptionIdx: index("of_tx_exception_idx").on(t.hasException),
}));
export type OpenforceTransaction = typeof openforceTransactions.$inferSelect;
export type InsertOpenforceTransaction = typeof openforceTransactions.$inferInsert;

// ─── OpenForce Match Audit Log ────────────────────────────────────────────────
export const openforceMatchAuditLog = pgTable("openforce_match_audit_log", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  transactionId: varchar("transaction_id").notNull().references(() => openforceTransactions.id),
  actionType: varchar("action_type", { length: 30 }).notNull(),
  // 'auto_match' | 'auto_exception' | 'manual_match' | 'override' | 'excluded'
  previousStatus: varchar("previous_status", { length: 30 }),
  newStatus: varchar("new_status", { length: 30 }),
  previousExceptionType: varchar("previous_exception_type", { length: 100 }),
  assignedDriverId: varchar("assigned_driver_id"),
  userId: varchar("user_id"),
  notes: text("notes"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  txIdx:   index("of_audit_tx_idx").on(t.transactionId),
  userIdx: index("of_audit_user_idx").on(t.userId),
}));
export type OpenforceMatchAuditLog = typeof openforceMatchAuditLog.$inferSelect;
export type InsertOpenforceMatchAuditLog = typeof openforceMatchAuditLog.$inferInsert;

// ─── OpenForce Pay Reconciliation Results ────────────────────────────────────
// One row per matched transaction after the reconciliation engine runs.
export const openforceReconciliationResults = pgTable("openforce_reconciliation_results", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),

  // ── Source links ──────────────────────────────────────────────────────────
  transactionId: varchar("transaction_id").notNull().references(() => openforceTransactions.id),
  driverId: varchar("driver_id").references(() => drivers.id),
  openforceId: varchar("openforce_id", { length: 100 }),
  importBatchId: varchar("import_batch_id").references(() => openforceImportBatches.id),

  // ── Pay period ────────────────────────────────────────────────────────────
  payPeriodStart: date("pay_period_start"),
  payPeriodEnd: date("pay_period_end"),

  // ── Pay ───────────────────────────────────────────────────────────────────
  grossPay: numeric("gross_pay", { precision: 14, scale: 2 }),

  // ── Reported values (from OpenForce settlement file) ─────────────────────
  reportedHours: numeric("reported_hours", { precision: 8, scale: 2 }),
  reportedTrips: integer("reported_trips"),

  // ── System values (from DriverHub trips/shifts) ───────────────────────────
  systemHours: numeric("system_hours", { precision: 8, scale: 2 }),
  systemTrips: integer("system_trips"),

  // ── Calculated effective rates ────────────────────────────────────────────
  effectiveHourlyRate: numeric("effective_hourly_rate", { precision: 10, scale: 4 }),
  effectiveTripRate: numeric("effective_trip_rate", { precision: 10, scale: 4 }),

  // ── Variance ──────────────────────────────────────────────────────────────
  hoursVariance: numeric("hours_variance", { precision: 8, scale: 2 }),        // reported - system
  hoursVariancePct: numeric("hours_variance_pct", { precision: 8, scale: 2 }), // abs(variance)/reported * 100
  tripVariance: integer("trip_variance"),                                       // reported - system
  tripVariancePct: numeric("trip_variance_pct", { precision: 8, scale: 2 }),

  // ── Reconciliation statuses ───────────────────────────────────────────────
  hoursReconciliationStatus: varchar("hours_reconciliation_status", { length: 20 }).default("pending"),
  // 'reconciled' | 'variance' | 'insufficient_data' | 'pending'
  tripReconciliationStatus: varchar("trip_reconciliation_status", { length: 20 }).default("pending"),
  // 'reconciled' | 'variance' | 'insufficient_data' | 'pending'
  reconciliationStatus: varchar("reconciliation_status", { length: 20 }).default("pending"),
  // 'reconciled' | 'variance' | 'anomaly' | 'pending'

  // ── Anomaly flags (pipe-separated list of codes) ──────────────────────────
  anomalyFlag: boolean("anomaly_flag").default(false),
  anomalyCode: text("anomaly_code"),
  // Codes: high_effective_hourly_rate | low_effective_hourly_rate | high_effective_trip_rate
  //        low_effective_trip_rate | hours_variance | trip_variance
  //        pay_with_no_hours | pay_with_no_trips

  // ── Tolerance snapshot ────────────────────────────────────────────────────
  hoursTolerance: numeric("hours_tolerance", { precision: 6, scale: 2 }).default("0.25"),
  tripTolerance: integer("trip_tolerance").default(0),

  // ── Audit ─────────────────────────────────────────────────────────────────
  calculatedAt: timestamp("calculated_at", { withTimezone: true }).defaultNow(),
  lastUpdatedAt: timestamp("last_updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  txIdx:     index("of_rec_tx_idx").on(t.transactionId),
  driverIdx: index("of_rec_driver_idx").on(t.driverId),
  batchIdx:  index("of_rec_batch_idx").on(t.importBatchId),
  periodIdx: index("of_rec_period_idx").on(t.payPeriodStart, t.payPeriodEnd),
  statusIdx: index("of_rec_status_idx").on(t.reconciliationStatus),
}));
export type OpenforceReconciliationResult = typeof openforceReconciliationResults.$inferSelect;
export type InsertOpenforceReconciliationResult = typeof openforceReconciliationResults.$inferInsert;

// ─────────────────────────────────────────────────────────────────────────────
//   Cost Per Move Engine Output Tables
// ─────────────────────────────────────────────────────────────────────────────

// Move-level labor cost allocations
export const moveLaborCostAllocations = pgTable("move_labor_cost_allocations", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  moveId: varchar("move_id").references(() => trips.id, { onDelete: "set null" }),
  driverId: varchar("driver_id").references(() => drivers.id, { onDelete: "set null" }),
  driverType: varchar("driver_type"), // 'ic' | 'shift'
  payPeriodStart: date("pay_period_start"),
  payPeriodEnd: date("pay_period_end"),
  shiftId: varchar("shift_id"),                           // nullable; set for shift model
  costingMethod: varchar("costing_method").notNull(),     // 'on_demand' | 'shift'
  grossPaySourceId: varchar("gross_pay_source_id"),       // openforce_transaction id
  sourceTransactionId: varchar("source_transaction_id"),
  sourceReconciliationId: varchar("source_reconciliation_id"),
  moveLaborCost: numeric("move_labor_cost", { precision: 10, scale: 4 }).notNull().default("0"),
  costPerMoveBasis: numeric("cost_per_move_basis", { precision: 10, scale: 4 }),  // the CPM used
  completedMoveCountBasis: integer("completed_move_count_basis"),                  // denominator
  accountId: varchar("account_id").references(() => customers.id, { onDelete: "set null" }),
  accountName: varchar("account_name"),
  tripDate: timestamp("trip_date"),
  anomalyFlag: boolean("anomaly_flag").default(false),
  anomalyReason: varchar("anomaly_reason"),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  driverIdx: index("mlca_driver_idx").on(t.driverId),
  moveIdx:   index("mlca_move_idx").on(t.moveId),
  periodIdx: index("mlca_period_idx").on(t.payPeriodStart, t.payPeriodEnd),
  acctIdx:   index("mlca_acct_idx").on(t.accountId),
  methodIdx: index("mlca_method_idx").on(t.costingMethod),
}));
export type MoveLaborCostAllocation = typeof moveLaborCostAllocations.$inferSelect;

// ─────────────────────────────────────────────────────────────────────────────
//   Account Financial Summary — Gross Profit Engine output
// ─────────────────────────────────────────────────────────────────────────────
export const accountFinancialSummary = pgTable("account_financial_summary", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  accountId: varchar("account_id").references(() => customers.id, { onDelete: "set null" }),
  accountNumber: varchar("account_number"),
  accountName: varchar("account_name"),
  periodStart: date("period_start").notNull(),
  periodEnd: date("period_end").notNull(),

  // Revenue
  totalRevenue: numeric("total_revenue", { precision: 14, scale: 2 }).default("0"),
  invoiceCount: integer("invoice_count").default(0),

  // Costs
  totalLaborCost: numeric("total_labor_cost", { precision: 14, scale: 2 }).default("0"),
  totalRideshareCost: numeric("total_rideshare_cost", { precision: 14, scale: 2 }).default("0"),
  totalCost: numeric("total_cost", { precision: 14, scale: 2 }).default("0"),

  // Volume
  totalMoves: integer("total_moves").default(0),
  rideshareRideCount: integer("rideshare_ride_count").default(0),

  // Derived
  costPerMove: numeric("cost_per_move", { precision: 10, scale: 4 }),
  grossProfit: numeric("gross_profit", { precision: 14, scale: 2 }),
  marginPct: numeric("margin_pct", { precision: 8, scale: 4 }),   // 0.0 – 1.0

  // Anomalies
  anomalyFlag: boolean("anomaly_flag").default(false),
  anomalyCodes: varchar("anomaly_codes"),  // pipe-separated

  // Audit
  calculatedAt: timestamp("calculated_at", { withTimezone: true }).defaultNow(),
  lastUpdatedAt: timestamp("last_updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  accountIdx: index("afs_account_idx").on(t.accountId),
  periodIdx:  index("afs_period_idx").on(t.periodStart, t.periodEnd),
  profitIdx:  index("afs_profit_idx").on(t.grossProfit),
  anomalyIdx: index("afs_anomaly_idx").on(t.anomalyFlag),
}));
export type AccountFinancialSummary = typeof accountFinancialSummary.$inferSelect;

// Driver-level cost per move summary (one row per driver+pay period)
export const driverLaborCostSummary = pgTable("driver_labor_cost_summary", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  driverId: varchar("driver_id").references(() => drivers.id, { onDelete: "set null" }),
  openforceId: varchar("openforce_id"),
  driverName: varchar("driver_name"),
  driverType: varchar("driver_type"),                   // 'ic' | 'shift'
  payPeriodStart: date("pay_period_start"),
  payPeriodEnd: date("pay_period_end"),
  importBatchId: varchar("import_batch_id"),
  totalGrossPay: numeric("total_gross_pay", { precision: 12, scale: 2 }).default("0"),
  totalCompletedMoves: integer("total_completed_moves").default(0),
  costPerMove: numeric("cost_per_move", { precision: 10, scale: 4 }),
  calculationMethod: varchar("calculation_method"),     // 'on_demand' | 'shift'
  anomalyFlag: boolean("anomaly_flag").default(false),
  anomalyReason: varchar("anomaly_reason"),
  accountCount: integer("account_count").default(0),
  calculatedAt: timestamp("calculated_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  driverIdx: index("dlcs_driver_idx").on(t.driverId),
  periodIdx: index("dlcs_period_idx").on(t.payPeriodStart, t.payPeriodEnd),
  batchIdx:  index("dlcs_batch_idx").on(t.importBatchId),
  anomIdx:   index("dlcs_anomaly_idx").on(t.anomalyFlag),
}));
export type DriverLaborCostSummary = typeof driverLaborCostSummary.$inferSelect;

// ─────────────────────────────────────────────────────────────────────────────
//   System Exceptions — centralized exception & compliance log
// ─────────────────────────────────────────────────────────────────────────────
export const systemExceptions = pgTable("system_exceptions", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),

  exceptionType: varchar("exception_type", { length: 100 }).notNull(),
  exceptionCategory: varchar("exception_category", { length: 50 }).notNull(),
  // Categories: driver_compliance | pay_reconciliation | cost_allocation | rideshare | financial

  severity: varchar("severity", { length: 20 }).notNull().default("medium"),
  // Values: low | medium | high | critical

  entityType: varchar("entity_type", { length: 50 }),
  // Values: driver | account | move | transaction

  entityId: varchar("entity_id"),
  relatedIds: jsonb("related_ids"),   // { batchId, periodId, invoiceId, etc. }

  description: text("description"),
  sourceModule: varchar("source_module", { length: 50 }),
  // Values: openforce | rideshare | cost_engine | profitability

  status: varchar("status", { length: 20 }).notNull().default("open"),
  // Values: open | in_progress | resolved | ignored

  assignedToUserId: varchar("assigned_to_user_id").references(() => users.id, { onDelete: "set null" }),

  notes: text("notes"),

  resolvedAt: timestamp("resolved_at", { withTimezone: true }),
  resolvedByUserId: varchar("resolved_by_user_id").references(() => users.id, { onDelete: "set null" }),

  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  typeIdx:     index("se_type_idx").on(t.exceptionType),
  categoryIdx: index("se_category_idx").on(t.exceptionCategory),
  severityIdx: index("se_severity_idx").on(t.severity),
  statusIdx:   index("se_status_idx").on(t.status),
  entityIdx:   index("se_entity_idx").on(t.entityType, t.entityId),
  sourceIdx:   index("se_source_idx").on(t.sourceModule),
  createdIdx:  index("se_created_idx").on(t.createdAt),
}));
export type SystemException = typeof systemExceptions.$inferSelect;

// ─────────────────────────────────────────────────────────────────────────────
//   Move Financials — Move-Level Profitability Engine
// ─────────────────────────────────────────────────────────────────────────────
export const FINANCIAL_STATUSES = ["unpriced","costed_only","revenue_only","matched","exception","finalized"] as const;
export type FinancialStatus = typeof FINANCIAL_STATUSES[number];

export const moveFinancials = pgTable("move_financials", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  moveId:           varchar("move_id").references(() => trips.id, { onDelete: "cascade" }),
  accountId:        varchar("account_id").references(() => customers.id, { onDelete: "set null" }),
  accountNumber:    varchar("account_number", { length: 100 }),
  accountName:      varchar("account_name",   { length: 255 }),
  moveDate:         date("move_date"),
  moveType:         varchar("move_type",   { length: 50 }),
  driverType:       varchar("driver_type", { length: 20 }),
  driverId:         varchar("driver_id"),
  employeeId:       varchar("employee_id"),
  market:           varchar("market", { length: 100 }),

  // Revenue
  revenueAmount:    numeric("revenue_amount",  { precision: 12, scale: 2 }).default("0"),
  allocationMethod: varchar("allocation_method", { length: 20 }).default("direct"),
  revenueAllocationNotes: text("revenue_allocation_notes"),
  invoiceId:        varchar("invoice_id").references(() => invoices.id, { onDelete: "set null" }),
  invoiceLineId:    varchar("invoice_line_id"),
  billingPeriodStart: date("billing_period_start"),
  billingPeriodEnd:   date("billing_period_end"),

  // Costs
  laborCost:             numeric("labor_cost",             { precision: 12, scale: 2 }).default("0"),
  rideshareCost:         numeric("rideshare_cost",         { precision: 12, scale: 2 }).default("0"),
  repositionCostAmount:  numeric("reposition_cost_amount", { precision: 12, scale: 2 }).default("0"),
  incentiveCostAmount:   numeric("incentive_cost_amount",  { precision: 12, scale: 2 }).default("0"),
  adjustmentCostAmount:  numeric("adjustment_cost_amount", { precision: 12, scale: 2 }).default("0"),
  totalCost:             numeric("total_cost",             { precision: 12, scale: 2 }).default("0"),
  totalDirectCost:       numeric("total_direct_cost",      { precision: 12, scale: 2 }).default("0"),
  passThrough:           boolean("pass_through").default(false),

  // Derived
  grossProfit:  numeric("gross_profit", { precision: 12, scale: 2 }).default("0"),
  marginPct:    numeric("margin_pct",   { precision: 8,  scale: 4 }),

  // Status
  financialStatus: varchar("financial_status", { length: 30 }).default("unpriced"),

  // Linkage
  laborCostSourceId:      varchar("labor_cost_source_id"),
  driverEarningsId:       varchar("driver_earnings_id"),
  rideshareTransactionId: varchar("rideshare_transaction_id"),

  // Anomaly
  anomalyFlag:  boolean("anomaly_flag").default(false),
  anomalyCodes: text("anomaly_codes").array(),

  // Notes
  notes: text("notes"),

  // Audit
  calculatedAt:  timestamp("calculated_at",   { withTimezone: true }).defaultNow(),
  lastUpdatedAt: timestamp("last_updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  moveIdx:    index("mf_move_idx").on(t.moveId),
  acctIdx:    index("mf_acct_idx").on(t.accountId),
  dateIdx:    index("mf_date_idx").on(t.moveDate),
  profitIdx:  index("mf_profit_idx").on(t.grossProfit),
  marginIdx:  index("mf_margin_idx").on(t.marginPct),
  anomalyIdx: index("mf_anomaly_idx").on(t.anomalyFlag),
  statusIdx:  index("mf_status_idx").on(t.financialStatus),
  driverIdx:  index("mf_driver_idx").on(t.driverId),
}));

export const insertMoveFinancialsSchema = createInsertSchema(moveFinancials).omit({ id: true, calculatedAt: true, lastUpdatedAt: true });
export type MoveFinancial = typeof moveFinancials.$inferSelect;
export type InsertMoveFinancial = z.infer<typeof insertMoveFinancialsSchema>;

// ─── Margin Exceptions ────────────────────────────────────────────────────────
export const MARGIN_EXCEPTION_TYPES = [
  "missing_revenue","missing_cost","unlinked_invoice_line","unlinked_pay_record",
  "duplicate_mapping","negative_margin","pass_through_issue","manual_flag",
] as const;
export type MarginExceptionType = typeof MARGIN_EXCEPTION_TYPES[number];

export const marginExceptions = pgTable("margin_exceptions", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  moveFinancialId:  varchar("move_financial_id").references(() => moveFinancials.id, { onDelete: "cascade" }),
  moveId:           varchar("move_id"),
  accountId:        varchar("account_id").references(() => customers.id, { onDelete: "set null" }),
  exceptionType:    varchar("exception_type", { length: 60 }).notNull(),
  severity:         varchar("severity", { length: 10 }).default("warning"),
  description:      text("description"),
  resolutionStatus: varchar("resolution_status", { length: 20 }).default("open"),
  resolvedBy:       varchar("resolved_by"),
  resolvedAt:       timestamp("resolved_at", { withTimezone: true }),
  resolutionNote:   text("resolution_note"),
  autoDetected:     boolean("auto_detected").default(true),
  moveDate:         date("move_date"),
  accountName:      varchar("account_name", { length: 255 }),
  marginPct:        numeric("margin_pct", { precision: 8, scale: 4 }),
  createdAt:        timestamp("created_at", { withTimezone: true }).defaultNow(),
  updatedAt:        timestamp("updated_at", { withTimezone: true }).defaultNow(),
}, (t) => ({
  mfIdx:      index("me_move_fin_idx").on(t.moveFinancialId),
  statusIdx:  index("me_status_idx").on(t.resolutionStatus),
  typeIdx:    index("me_type_idx").on(t.exceptionType),
  acctIdx:    index("me_acct_idx").on(t.accountId),
  dateIdx:    index("me_date_idx").on(t.moveDate),
}));
export const insertMarginExceptionSchema = createInsertSchema(marginExceptions).omit({ id: true, createdAt: true, updatedAt: true });
export type MarginException = typeof marginExceptions.$inferSelect;
export type InsertMarginException = z.infer<typeof insertMarginExceptionSchema>;

// =============================================================================
// MULTI-FILE IMPORT FRAMEWORK — Moves Dataset
// =============================================================================
// Architecture: each Moves import is one ImportJob with multiple child
// ImportJobFiles (one per uploaded CSV/XLSX). Raw rows from every file are
// staged in moves_import_raw_rows before final processing commits them to
// the trips table.
// Status machine:
//   Job: draft → in_progress → staged → validating → validated → processing → completed | failed
//   File: pending → staged → validating → validated | failed | reprocessing
// =============================================================================

// ─── 1. import_jobs ─────────────────────────────────────────────────────────
// Parent record for every multi-file import operation.
// dataset_type = 'moves' for the Moves dataset; framework is extensible.
export const importJobs = pgTable("import_jobs", {
  id:             varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  datasetType:    varchar("dataset_type",  { length: 50 }).notNull(),    // 'moves'
  jobName:        varchar("job_name",      { length: 255 }).notNull(),
  status:         varchar("status",        { length: 30  }).notNull().default("draft"),
  // 'draft'|'in_progress'|'staged'|'validating'|'validated'|'processing'|'completed'|'failed'|'cancelled'
  createdByUserId:  varchar("created_by_user_id"),
  orgId:            varchar("org_id"),
  notes:            text("notes"),
  validationSummaryJson: jsonb("validation_summary_json"), // cached validation results
  processedAt:    timestamp("processed_at",   { withTimezone: true }),
  createdAt:      timestamp("created_at",     { withTimezone: true }).defaultNow(),
  updatedAt:      timestamp("updated_at",     { withTimezone: true }).defaultNow(),
}, (t) => ({
  statusIdx:      index("ij_status_idx").on(t.status),
  datasetIdx:     index("ij_dataset_idx").on(t.datasetType),
  createdByIdx:   index("ij_created_by_idx").on(t.createdByUserId),
  createdAtIdx:   index("ij_created_at_idx").on(t.createdAt),
}));

export const insertImportJobSchema = createInsertSchema(importJobs).omit({ id: true, createdAt: true, updatedAt: true, processedAt: true });
export type ImportJob = typeof importJobs.$inferSelect;
export type InsertImportJob = z.infer<typeof insertImportJobSchema>;

// ─── 2. import_job_files ────────────────────────────────────────────────────
// Child file record for each CSV/XLSX uploaded to an ImportJob.
// file_type is user-selected, not guessed from the filename.
// Moves file types: moves_master | move_stops | driver_assignments | revenue | status_history | other
export const importJobFiles = pgTable("import_job_files", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  importJobId:      varchar("import_job_id").notNull().references(() => importJobs.id, { onDelete: "cascade" }),
  fileType:         varchar("file_type",         { length: 50 }).notNull(),
  // Moves: 'moves_master'|'move_stops'|'driver_assignments'|'revenue'|'status_history'|'other'
  sourceFileName:   text("source_file_name").notNull(),
  sourceFileType:   varchar("source_file_type",  { length: 10 }),      // 'csv'|'xlsx'|'xls'
  uploadedByUserId: varchar("uploaded_by_user_id"),
  status:           varchar("status",            { length: 30 }).notNull().default("staged"),
  // 'pending'|'staged'|'validating'|'validated'|'failed'|'reprocessing'
  totalRows:        integer("total_rows"),
  stagedRows:       integer("staged_rows").default(0),
  validRows:        integer("valid_rows").default(0),
  invalidRows:      integer("invalid_rows").default(0),
  orphanRows:       integer("orphan_rows").default(0),
  duplicateRows:    integer("duplicate_rows").default(0),
  committedRows:    integer("committed_rows").default(0),
  detectedKeyColumn: varchar("detected_key_column", { length: 100 }), // e.g. 'move_id'
  notes:            text("notes"),
  createdAt:        timestamp("created_at",   { withTimezone: true }).defaultNow(),
  updatedAt:        timestamp("updated_at",   { withTimezone: true }).defaultNow(),
}, (t) => ({
  jobIdx:     index("ijf_job_idx").on(t.importJobId),
  statusIdx:  index("ijf_status_idx").on(t.status),
  typeIdx:    index("ijf_type_idx").on(t.fileType),
}));

export const insertImportJobFileSchema = createInsertSchema(importJobFiles).omit({ id: true, createdAt: true, updatedAt: true });
export type ImportJobFile = typeof importJobFiles.$inferSelect;
export type InsertImportJobFile = z.infer<typeof insertImportJobFileSchema>;

// ─── 3. moves_import_raw_rows ───────────────────────────────────────────────
// Immutable staging table: every row from every uploaded file is written here
// before any validation or final processing takes place.
// move_key holds the extracted linking identifier (move_id / trip_id / move_number).
export const movesImportRawRows = pgTable("moves_import_raw_rows", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  importJobId:      varchar("import_job_id").notNull().references(() => importJobs.id, { onDelete: "cascade" }),
  importFileId:     varchar("import_file_id").notNull().references(() => importJobFiles.id, { onDelete: "cascade" }),
  fileType:         varchar("file_type",      { length: 50 }).notNull(),  // denormalized
  rowNumber:        integer("row_number").notNull(),
  moveKey:          varchar("move_key",       { length: 100 }),            // extracted linking key
  rawRowJson:       jsonb("raw_row_json").notNull(),
  processingStatus: varchar("processing_status", { length: 30 }).notNull().default("staged"),
  // 'staged'|'validated'|'orphan'|'duplicate'|'failed'|'committed'
  failureReason:    text("failure_reason"),
  linkedTripId:     varchar("linked_trip_id"),  // populated after commit
  createdAt:        timestamp("created_at",   { withTimezone: true }).defaultNow(),
  updatedAt:        timestamp("updated_at",   { withTimezone: true }).defaultNow(),
}, (t) => ({
  jobIdx:     index("mirr_job_idx").on(t.importJobId),
  fileIdx:    index("mirr_file_idx").on(t.importFileId),
  statusIdx:  index("mirr_status_idx").on(t.processingStatus),
  keyIdx:     index("mirr_key_idx").on(t.moveKey),
  rowIdx:     index("mirr_row_idx").on(t.importFileId, t.rowNumber),
}));

export const insertMovesImportRawRowSchema = createInsertSchema(movesImportRawRows).omit({ id: true, createdAt: true, updatedAt: true });
export type MovesImportRawRow = typeof movesImportRawRows.$inferSelect;
export type InsertMovesImportRawRow = z.infer<typeof insertMovesImportRawRowSchema>;

// ═══════════════════════════════════════════════════════════════════════════
// AUTOMATED FILE-DROP INGESTION
// Secure SFTP-based inbound file ingestion with dedup, classification, and
// staged processing. Supports rideshare, openforce, and moves datasets.
// ═══════════════════════════════════════════════════════════════════════════

// ─── 1. file_drop_configs ───────────────────────────────────────────────────
// Each record represents one monitored inbound folder configuration.
export const fileDropConfigs = pgTable("file_drop_configs", {
  id:                      varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name:                    varchar("name", { length: 200 }).notNull(),
  datasetType:             varchar("dataset_type", { length: 50 }).notNull(),  // 'rideshare'|'openforce'|'moves'
  enabled:                 boolean("enabled").notNull().default(false),

  // ── SFTP Connection ──────────────────────────────────────────────────────
  sftpHost:                varchar("sftp_host", { length: 255 }),
  sftpPort:                integer("sftp_port").default(22),
  sftpUsername:            varchar("sftp_username", { length: 100 }),
  sftpPasswordEncrypted:   text("sftp_password_encrypted"),
  sftpPrivateKeyEncrypted: text("sftp_private_key_encrypted"),
  sftpPassphraseEncrypted: text("sftp_passphrase_encrypted"),

  // ── Folder Paths ────────────────────────────────────────────────────────
  inboundPath:             varchar("inbound_path", { length: 500 }).notNull().default("/inbound/"),
  archivePath:             varchar("archive_path", { length: 500 }).default("/archive/processed/"),
  errorPath:               varchar("error_path",   { length: 500 }).default("/archive/error/"),
  duplicatePath:           varchar("duplicate_path", { length: 500 }).default("/archive/duplicate/"),

  // ── Polling ─────────────────────────────────────────────────────────────
  pollIntervalMinutes:     integer("poll_interval_minutes").notNull().default(15), // 5|15|60

  // ── File Classification ──────────────────────────────────────────────────
  fileNamePattern:         varchar("file_name_pattern", { length: 255 }), // optional regex

  // ── Processing Behaviour ─────────────────────────────────────────────────
  autoProcess:             boolean("auto_process").notNull().default(false), // auto-commit after validation
  requireAllFileTypes:     boolean("require_all_file_types").notNull().default(false), // moves: wait for full set

  // ── Meta ─────────────────────────────────────────────────────────────────
  notes:                   text("notes"),
  lastPolledAt:            timestamp("last_polled_at", { withTimezone: true }),
  createdAt:               timestamp("created_at",    { withTimezone: true }).defaultNow(),
  updatedAt:               timestamp("updated_at",    { withTimezone: true }).defaultNow(),
});

export const insertFileDropConfigSchema = createInsertSchema(fileDropConfigs).omit({ id: true, createdAt: true, updatedAt: true, lastPolledAt: true });
export type FileDropConfig = typeof fileDropConfigs.$inferSelect;
export type InsertFileDropConfig = z.infer<typeof insertFileDropConfigSchema>;

// ─── 2. file_drop_ingestion_log ─────────────────────────────────────────────
// One row per file encounter. Duplicate files (same checksum) are re-detected
// and moved to the duplicate archive without re-processing.
export const fileDropIngestionLog = pgTable("file_drop_ingestion_log", {
  id:                 varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  fileDropConfigId:   varchar("file_drop_config_id").notNull().references(() => fileDropConfigs.id, { onDelete: "cascade" }),

  fileName:           varchar("file_name",    { length: 500 }).notNull(),
  remotePath:         varchar("remote_path",  { length: 1000 }),
  fileSize:           integer("file_size"),
  checksum:           varchar("checksum",     { length: 64 }), // SHA-256 hex

  status:             varchar("status", { length: 30 }).notNull().default("pending"),
  // 'pending'|'processing'|'processed'|'rejected'|'duplicate'

  datasetType:        varchar("dataset_type", { length: 50 }).notNull(),
  importJobId:        varchar("import_job_id"),   // references import_jobs.id  (moves)
  importBatchId:      varchar("import_batch_id"), // references rideshare/openforce batch

  rowsStaged:         integer("rows_staged"),
  rowsCommitted:      integer("rows_committed"),
  rowsFailed:         integer("rows_failed"),

  archivedPath:       varchar("archived_path", { length: 1000 }),
  errorMessage:       text("error_message"),

  detectedAt:         timestamp("detected_at",  { withTimezone: true }).defaultNow(),
  processedAt:        timestamp("processed_at", { withTimezone: true }),
  createdAt:          timestamp("created_at",   { withTimezone: true }).defaultNow(),
  updatedAt:          timestamp("updated_at",   { withTimezone: true }).defaultNow(),
});

export const insertFileDropIngestionLogSchema = createInsertSchema(fileDropIngestionLog).omit({ id: true, createdAt: true, updatedAt: true });
export type FileDropIngestionLog = typeof fileDropIngestionLog.$inferSelect;
export type InsertFileDropIngestionLog = z.infer<typeof insertFileDropIngestionLogSchema>;

// ─── Platform Configuration (Multi-Tenant Configurable Platform) ──────────────

// ── Recruiting Request Intake ──────────────────────────────────────────────────
export const recruitingRequests = pgTable("recruiting_requests", {
  id:                    varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orgId:                 varchar("org_id").notNull(),
  submittedBy:           varchar("submitted_by").notNull(),          // user id
  submittedByName:       varchar("submitted_by_name", { length: 200 }),
  submittedAt:           timestamp("submitted_at").defaultNow().notNull(),
  campaignType:          varchar("campaign_type", { length: 50 }).notNull(),  // expedite | standard | other
  urgency:               integer("urgency").notNull(),               // 1–5
  market:                varchar("market",         { length: 100 }),
  marketCode:            varchar("market_code",    { length: 20  }),
  dealershipName:        varchar("dealership_name",{ length: 200 }),
  address:               varchar("address",        { length: 500 }),
  city:                  varchar("city",           { length: 100 }),
  state:                 varchar("state",          { length: 50  }),
  zipCode:               varchar("zip_code",       { length: 20  }),
  driverTypes:           text("driver_types").array().notNull().default(sql`'{}'::text[]`),
  targetDriverCount:     integer("target_driver_count"),
  payRate:               numeric("pay_rate", { precision: 10, scale: 2 }),
  signOnBonus:           boolean("sign_on_bonus").default(false),
  signOnBonusAmount:     numeric("sign_on_bonus_amount", { precision: 10, scale: 2 }),
  targetDate:            date("target_date"),
  phoneInterviewContact: varchar("phone_interview_contact", { length: 200 }),
  certLiaison:           varchar("cert_liaison",           { length: 200 }),
  additionalComments:    text("additional_comments"),
  requestStatus:         varchar("request_status", { length: 50 }).notNull().default("submitted"),
  reviewedBy:            varchar("reviewed_by",    { length: 200 }),
  reviewedAt:            timestamp("reviewed_at"),
  reviewNotes:           text("review_notes"),
  // Ticket 37 — explicit approval fields
  approvalStatus:        varchar("approval_status", { length: 50 }),   // pending | approved | rejected
  approvedBy:            varchar("approved_by",     { length: 200 }),
  approvedAt:            timestamp("approved_at"),
  approvalNotes:         text("approval_notes"),
  // Ticket 38 — campaign linkage (set when a requisition is created from this request)
  campaignRequisitionId: varchar("campaign_requisition_id"),
  updatedAt:             timestamp("updated_at").defaultNow(),
  // New intake fields
  requestOrigin:         varchar("request_origin",        { length: 200 }),
  accountId:             varchar("account_id"),
  location:              varchar("location",              { length: 500 }),
  driverClassification:  varchar("driver_classification", { length: 100 }),
  driverType:            varchar("driver_type",           { length: 100 }),
  signOnBonusOption:     varchar("sign_on_bonus_option",  { length: 100 }),
  signOnBonusNotes:      text("sign_on_bonus_notes"),
  recruiter:             varchar("recruiter",             { length: 200 }),
  driverSchedule:        text("driver_schedule"),
  campaignStartDate:     date("campaign_start_date"),
  actualClosingDate:     date("actual_closing_date"),      // DH-002168 / DH-002164: canonical business closing date
  // Taxonomy fields (Phase 2 normalization)
  vehicleLicenseClass:   varchar("vehicle_license_class", { length: 100 }),   // Passenger Vehicle, CDL-A, CDL-B, etc.
  programType:           varchar("program_type",          { length: 100 }),   // DriverDash | DriverShift | Hybrid
  employmentType:        varchar("employment_type",        { length: 50  }),   // Part-Time | Full-Time | On-Call
  // Account network (auto-populated from account record)
  network:               varchar("network",               { length: 100 }),
  // Archive / soft-delete fields
  isArchived:            boolean("is_archived").notNull().default(false),
  archivedAt:            timestamp("archived_at", { withTimezone: true }),
  archivedBy:            varchar("archived_by",    { length: 200 }),
  archiveReason:         text("archive_reason"),
  archivePreviousStatus: varchar("archive_previous_status", { length: 50 }),
  // Workforce Planning intake fields (migration 0020)
  requestNumber:  varchar("request_number",  { length: 50  }),
  businessReason: varchar("business_reason", { length: 100 }),
  attachments:    text("attachments").array().default(sql`'{}'::text[]`),
  // Clone linkage (migration 0041) — set when this request was cloned from a closed campaign
  clonedFromCampaignId: varchar("cloned_from_campaign_id"),
  clonedBy:             varchar("cloned_by"),
  clonedAt:             timestamp("cloned_at", { withTimezone: true }),
  // Test-data exclusion (migration 0095 / DH-002334) — set automatically for
  // records created by a designated Gate 0 / UAT identity so operational
  // Recruiting reports and KPIs can exclude them without deleting anything.
  isTestData:    boolean("is_test_data").notNull().default(false),
}, table => ({
  orgIdx:       index("recruiting_requests_org_idx").on(table.orgId),
  statusIdx:    index("recruiting_requests_status_idx").on(table.requestStatus),
  submittedIdx: index("recruiting_requests_submitted_idx").on(table.submittedAt),
  archivedIdx:  index("recruiting_requests_is_archived_idx").on(table.isArchived),
  testDataIdx:  index("recruiting_requests_is_test_data_idx").on(table.isTestData),
}));

export const insertRecruitingRequestSchema = createInsertSchema(recruitingRequests).omit({
  id: true, submittedAt: true, updatedAt: true,
});
export type RecruitingRequest       = typeof recruitingRequests.$inferSelect;
export type InsertRecruitingRequest = z.infer<typeof insertRecruitingRequestSchema>;

// ─── Recruiting Request Activity Log ──────────────────────────────────────────
export const recruitingRequestActivity = pgTable("recruiting_request_activity", {
  id:         varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orgId:      varchar("org_id").notNull(),
  requestId:  varchar("request_id").notNull(),
  userId:     varchar("user_id").notNull(),
  userName:   varchar("user_name",  { length: 200 }),
  action:     varchar("action",     { length: 50  }).notNull().default("status_change"),
  fromStatus: varchar("from_status",{ length: 50  }),
  toStatus:   varchar("to_status",  { length: 50  }),
  notes:      text("notes"),
  metadata:   jsonb("metadata"),
  createdAt:  timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => ({
  requestIdx: index("rra_request_idx").on(t.requestId),
  orgIdx:     index("rra_org_idx").on(t.orgId),
}));
export type RecruitingRequestActivity = typeof recruitingRequestActivity.$inferSelect;

