// ─── Recruiting Campaigns ─────────────────────────────────────────────────────
export const CAMPAIGN_STATUSES = ["draft","active","paused","completed","cancelled"] as const;
export type CampaignStatus = typeof CAMPAIGN_STATUSES[number];

export const CAMPAIGN_PRIORITIES = ["low","medium","high","critical"] as const;
export type CampaignPriority = typeof CAMPAIGN_PRIORITIES[number];

export const recruitingCampaigns = pgTable("recruiting_campaigns", {
  id:            varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  orgId:         varchar("org_id").notNull(),
  campaignName:  varchar("campaign_name", { length: 200 }).notNull(),
  // Source linkage
  requestId:     varchar("request_id"),
  requisitionId: varchar("requisition_id"),
  // Config
  market:        varchar("market",   { length: 100 }),
  network:       varchar("network",  { length: 100 }),
  driverTypes:   text("driver_types").array().notNull().default(sql`'{}'::text[]`),
  driversNeeded: integer("drivers_needed").notNull().default(1),
  startDate:     date("start_date"),
  endDate:       date("end_date"),
  budget:        numeric("budget",       { precision: 12, scale: 2 }),
  totalSpend:    numeric("total_spend",  { precision: 12, scale: 2 }).notNull().default("0"),
  priority:      varchar("priority", { length: 20 }).notNull().default("medium"),
  recruiterId:   varchar("recruiter_id"),
  recruiterName: varchar("recruiter_name", { length: 200 }),
  advertisingSources: text("advertising_sources").array().notNull().default(sql`'{}'::text[]`),
  referralBonus: numeric("referral_bonus", { precision: 10, scale: 2 }),
  hiringGoal:    integer("hiring_goal").notNull().default(1),
  // Live tracking counters (denormalized for fast dashboard reads)
  applicantsCount: integer("applicants_count").notNull().default(0),
  interviewsCount: integer("interviews_count").notNull().default(0),
  offersCount:     integer("offers_count").notNull().default(0),
  hiresCount:      integer("hires_count").notNull().default(0),
  // Status
  status:        varchar("status", { length: 30 }).notNull().default("draft"),
  notes:         text("notes"),
  // Maintenance clone tracking
  urgencyLevel:              varchar("urgency_level", { length: 50 }),
  clonedFromCampaignId:      varchar("cloned_from_campaign_id"),
  clonedAt:                  timestamp("cloned_at", { withTimezone: true }),
  clonedBy:                  varchar("cloned_by"),
  maintenanceCloneId:        varchar("maintenance_clone_id"),
  maintenanceCloneCreatedAt: timestamp("maintenance_clone_created_at", { withTimezone: true }),
  // Closed Campaigns (DH-002168)
  closedAt:           timestamp("closed_at",            { withTimezone: true }),
  // Business-effective closing date (separate from system closedAt timestamp)
  actualClosingDate:  date("actual_closing_date"),
  // Who closed the campaign
  closedByUserId:     varchar("closed_by_user_id"),
  closedByName:       varchar("closed_by_name", { length: 200 }),
  // Audit
  createdAt:     timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt:     timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  createdBy:     varchar("created_by"),
  updatedBy:     varchar("updated_by"),
}, (t) => ({
  orgIdx:     index("rc_org_idx").on(t.orgId),
  statusIdx:  index("rc_status_idx").on(t.status),
  requestIdx: index("rc_request_idx").on(t.requestId),
  createdIdx: index("rc_created_idx").on(t.createdAt),
}));

export const insertRecruitingCampaignSchema = createInsertSchema(recruitingCampaigns).omit({
  id: true, createdAt: true, updatedAt: true,
  applicantsCount: true, interviewsCount: true, offersCount: true, hiresCount: true, totalSpend: true,
});
export type RecruitingCampaign       = typeof recruitingCampaigns.$inferSelect;
export type InsertRecruitingCampaign = z.infer<typeof insertRecruitingCampaignSchema>;


