export const insertDriverEarningsSchema = createInsertSchema(driverEarnings).omit({ id: true, createdAt: true, updatedAt: true });
export type InsertDriverEarnings = z.infer<typeof insertDriverEarningsSchema>;
export type DriverEarnings = typeof driverEarnings.$inferSelect;

// ─── Payroll Batches ──────────────────────────────────────────────────────────
// Weekly grouping of driver_earnings for payroll approval and payment.
// One batch per week per pay group (e.g., "DRIVERS_IC_WEEKLY", "DRIVERS_W2_WEEKLY").

export const BATCH_STATUS = ["open", "under_review", "approved", "paid", "voided"] as const;
export type BatchStatus = typeof BATCH_STATUS[number];

export const payrollBatches = pgTable("payroll_batches", {
  id:              varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  weekStart:       date("week_start").notNull(),
  weekEnd:         date("week_end").notNull(),
  payGroup:        varchar("pay_group", { length: 50 }).notNull().default("DRIVERS_WEEKLY"),
  status:          varchar("status", { length: 30 }).notNull().default("open"),
  driverCount:     integer("driver_count").notNull().default(0),
  totalAmountCents: integer("total_amount_cents").notNull().default(0),
  notes:           text("notes"),
  approvedBy:      varchar("approved_by").references(() => users.id, { onDelete: "set null" }),
  approvedAt:      timestamp("approved_at", { withTimezone: true }),
  paidAt:          timestamp("paid_at",     { withTimezone: true }),
  createdAt:       timestamp("created_at",  { withTimezone: true }).notNull().defaultNow(),
  updatedAt:       timestamp("updated_at",  { withTimezone: true }).notNull().defaultNow(),
}, (t) => ({
  weekPayGroupUniq: uniqueIndex("pb_week_paygroup_uniq").on(t.weekStart, t.payGroup),
  statusIdx:        index("pb_status_idx").on(t.status),
  weekIdx:          index("pb_week_idx").on(t.weekStart),
}));
export const insertPayrollBatchSchema = createInsertSchema(payrollBatches).omit({ id: true, createdAt: true, updatedAt: true });
export type InsertPayrollBatch = z.infer<typeof insertPayrollBatchSchema>;
export type PayrollBatch = typeof payrollBatches.$inferSelect;

// ── Report Delivery Logs ──────────────────────────────────────────────────────
export const reportDeliveryLogs = pgTable("report_delivery_logs", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  customerId:       varchar("customer_id").notNull().references(() => customers.id, { onDelete: "cascade" }),
  reportWeekStart:  date("report_week_start").notNull(),
  reportWeekEnd:    date("report_week_end").notNull(),
  status:           varchar("status", { length: 20 }).notNull().default("pending"), // pending | success | failed | skipped
  emailTo:          text("email_to"),
  emailCc:          text("email_cc"),
  errorMessage:     text("error_message"),
  attachmentCount:  integer("attachment_count").default(0),
  sentAt:           timestamp("sent_at"),
  createdAt:        timestamp("created_at").defaultNow(),
});
export const insertReportDeliveryLogSchema = createInsertSchema(reportDeliveryLogs).omit({ id: true, createdAt: true });
export type InsertReportDeliveryLog = z.infer<typeof insertReportDeliveryLogSchema>;
export type ReportDeliveryLog = typeof reportDeliveryLogs.$inferSelect;

// ── Account Report Logs (Ticket 2.3) — generation-only tracking ───────────────
export const accountReportLogs = pgTable("account_report_logs", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  accountId:        varchar("account_id").notNull().references(() => customers.id, { onDelete: "cascade" }),
  reportWeek:       date("report_week").notNull(),
  pdfGenerated:     boolean("pdf_generated").notNull().default(false),
  excelGenerated:   boolean("excel_generated").notNull().default(false),
  status:           varchar("status", { length: 20 }).notNull().default("pending"), // pending | success | partial | failed
  errorMessage:     text("error_message"),
  triggeredBy:      varchar("triggered_by", { length: 20 }).default("scheduler"),   // scheduler | manual
  emailSent:        boolean("email_sent").notNull().default(false),
  emailSentAt:      timestamp("email_sent_at", { withTimezone: true }),
  emailStatus:      varchar("email_status", { length: 20 }),  // success | failed | skipped
  emailErrorMessage: text("email_error_message"),
  recipientsJson:   text("recipients_json"),                  // JSON array of recipient emails (delivery job)
  createdAt:        timestamp("created_at").defaultNow(),
});
