// ─── Financial Record Locks ───────────────────────────────────────────────────
// Immutable audit trail for all lock/unlock/override events across invoices,
// payments, and deposit batches. One row per event.

export const financialRecordLocks = pgTable("financial_record_locks", {
  id:           varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // Which record
  entityType:   varchar("entity_type").notNull(), // 'invoice' | 'payment' | 'deposit_batch'
  entityId:     varchar("entity_id").notNull(),
  entityRef:    varchar("entity_ref"),            // Human-readable reference (invoice number, etc.)
  // Event
  action:       varchar("action").notNull(),       // 'locked' | 'unlocked_override' | 'edit_blocked' | 'edit_allowed_override'
  lockSource:   varchar("lock_source"),            // 'auto_paid' | 'deposit_locked' | 'deposit_reconciled' | 'manual'
  // Actor
  actorId:      varchar("actor_id").notNull().references(() => users.id),
  actorRole:    varchar("actor_role"),
  // Override context (only when action = 'unlocked_override')
  overrideReason: text("override_reason"),
  overrideExpiresAt: timestamp("override_expires_at"), // Temporary override window (null = permanent unlock)
  // Metadata
  metadata:     jsonb("metadata"),
  createdAt:    timestamp("created_at").defaultNow(),
});

export type FinancialRecordLock = typeof financialRecordLocks.$inferSelect;
export const insertFinancialRecordLockSchema = createInsertSchema(financialRecordLocks).omit({ id: true, createdAt: true });
export type InsertFinancialRecordLock = z.infer<typeof insertFinancialRecordLockSchema>;

// ─── Billing Documents (Customer-facing, e.g. W-9) ───────────────────────────
// Admin-managed documents that customers can download from the public billing
// portal without logging in.  Only one 'active' document per documentType.

export const billingDocuments = pgTable("billing_documents", {
  id:            varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  documentType:  varchar("document_type").notNull(),  // 'w9', 'terms', 'ach_auth', etc.
  displayName:   varchar("display_name").notNull(),    // Human-readable name shown on portal
  fileName:      varchar("file_name").notNull(),
  storageKey:    varchar("storage_key").notNull(),     // Key in object storage
  contentType:   varchar("content_type").notNull().default("application/pdf"),
  fileSizeBytes: integer("file_size_bytes"),
  effectiveDate: date("effective_date"),
  status:        varchar("status").notNull().default("active"), // 'active' | 'archived'
  notes:         text("notes"),
  downloadCount: integer("download_count").notNull().default(0),
  // Audit
  uploadedBy:    varchar("uploaded_by").notNull().references(() => users.id),
  uploadedAt:    timestamp("uploaded_at").notNull().defaultNow(),
  archivedAt:    timestamp("archived_at"),
  archivedBy:    varchar("archived_by").references(() => users.id),
  createdAt:     timestamp("created_at").defaultNow(),
});

export type BillingDocument = typeof billingDocuments.$inferSelect;
export const insertBillingDocumentSchema = createInsertSchema(billingDocuments).omit({
  id: true, uploadedAt: true, createdAt: true, downloadCount: true, archivedAt: true, archivedBy: true,
});
export type InsertBillingDocument = z.infer<typeof insertBillingDocumentSchema>;

// ─── Weekly Billing Runs ──────────────────────────────────────────────────────
// Persistent audit log for each Weekly Billing Control Panel run.
// Tracks preview → execute lifecycle, per-account results, and send mode.

export const weeklyBillingRuns = pgTable("weekly_billing_runs", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  tenantId:         varchar("tenant_id"),
  cycleStart:       varchar("cycle_start").notNull(),           // YYYY-MM-DD
  cycleEnd:         varchar("cycle_end").notNull(),             // YYYY-MM-DD
  runDate:          timestamp("run_date").notNull().defaultNow(),
  status:           varchar("status", { length: 30 }).notNull().default("previewing"), // previewing | confirmed | executed | failed
  sendMode:         varchar("send_mode", { length: 20 }).default("draft"),            // draft | send_now | scheduled
  scheduledSendAt:  timestamp("scheduled_send_at"),
  createdByUserId:  varchar("created_by_user_id"),
  accountsTotal:    integer("accounts_total").default(0),
  accountsReady:    integer("accounts_ready").default(0),
  accountsWarning:  integer("accounts_warning").default(0),
  accountsError:    integer("accounts_error").default(0),
  accountsSkipped:  integer("accounts_skipped").default(0),
  invoicesCreated:  integer("invoices_created").default(0),
  invoicesAppended: integer("invoices_appended").default(0),
  totalAmount:      varchar("total_amount").default("0"),
  overriddenAccounts: jsonb("overridden_accounts"),             // string[] of customerId overrides
  resultJson:       jsonb("result_json"),                       // full AssemblyRunResult snapshot
  notes:            text("notes"),
  createdAt:        timestamp("created_at").defaultNow(),
  completedAt:      timestamp("completed_at"),
}, (table) => ({
  tenantIdx:    index("weekly_billing_runs_tenant_idx").on(table.tenantId),
  statusIdx:    index("weekly_billing_runs_status_idx").on(table.status),
  cycleEndIdx:  index("weekly_billing_runs_cycle_end_idx").on(table.cycleEnd),
  createdAtIdx: index("weekly_billing_runs_created_at_idx").on(table.createdAt),
}));

export type WeeklyBillingRun = typeof weeklyBillingRuns.$inferSelect;
export const insertWeeklyBillingRunSchema = createInsertSchema(weeklyBillingRuns).omit({
  id: true, createdAt: true, runDate: true,
});
export type InsertWeeklyBillingRun = z.infer<typeof insertWeeklyBillingRunSchema>;

// ─── Stripe Webhook Event Log ─────────────────────────────────────────────────
// Immutable audit log of every Stripe webhook event received and processed.
// Enables idempotency checks, debugging, and operational visibility.

export const stripeWebhookEvents = pgTable("stripe_webhook_events", {
  id:             varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  stripeEventId:  varchar("stripe_event_id").notNull().unique(), // e.g. evt_xxx
  eventType:      varchar("event_type").notNull(),               // e.g. payment_intent.succeeded
  status:         varchar("status").notNull().default("received"), // received | processed | failed | skipped
  invoiceId:      varchar("invoice_id"),
  paymentId:      varchar("payment_id"),
  stripeObjectId: varchar("stripe_object_id"),                   // PaymentIntent/Charge/Dispute id
  amount:         varchar("amount"),                             // in dollars
  currency:       varchar("currency"),
  processingError: text("processing_error"),
  rawPayload:     text("raw_payload"),                           // Serialized JSON (stripped of PII keys)
  processedAt:    timestamp("processed_at"),
  receivedAt:     timestamp("received_at").notNull().defaultNow(),
}, (table) => ({
  eventTypeIdx:  index("stripe_webhook_events_type_idx").on(table.eventType),
  statusIdx:     index("stripe_webhook_events_status_idx").on(table.status),
  receivedAtIdx: index("stripe_webhook_events_received_at_idx").on(table.receivedAt),
  invoiceIdx:    index("stripe_webhook_events_invoice_idx").on(table.invoiceId),
}));

export type StripeWebhookEvent = typeof stripeWebhookEvents.$inferSelect;
export const insertStripeWebhookEventSchema = createInsertSchema(stripeWebhookEvents).omit({
  id: true, receivedAt: true,
});
export type InsertStripeWebhookEvent = z.infer<typeof insertStripeWebhookEventSchema>;

// ═══════════════════════════════════════════════════════════════════════════
// CORE COMMUNICATIONS FRAMEWORK
// Ticket 1 — Platform / Shared Infrastructure
// These tables are the canonical audit backbone for all outbound
// communications across every module (Assigned Drivers, Scheduling,
// Dispatch, Compliance, Claims, etc.). Provider-specific tables such as
// `driver_communication_logs` remain as operational convenience tables;
// this framework is the durable record of truth.
// ═══════════════════════════════════════════════════════════════════════════

// ── Shared Enums ────────────────────────────────────────────────────────────

export const commChannelEnum        = ["email", "sms"] as const;
export const commProviderEnum       = ["microsoft_365", "heymarket", "twilio", "sendgrid"] as const;
export const commDirectionEnum      = ["outbound"] as const;
export const commStatusEnum         = ["draft", "queued", "sent", "failed", "partial"] as const;
export const commRecipientTypeEnum  = ["driver", "account_contact", "employee", "unknown"] as const;
export const commDeliveryStatusEnum = ["pending", "sent", "failed", "excluded"] as const;

export type CommChannel        = typeof commChannelEnum[number];
export type CommProvider       = typeof commProviderEnum[number];
export type CommDirection      = typeof commDirectionEnum[number];
export type CommStatus         = typeof commStatusEnum[number];
export type CommRecipientType  = typeof commRecipientTypeEnum[number];
export type CommDeliveryStatus = typeof commDeliveryStatusEnum[number];

// ── communication_messages ───────────────────────────────────────────────────
// One record per outbound send attempt (batch or individual).
// The `related_module` + `related_entity_type` + `related_entity_id` triplet
// allows any part of the application to attach a send to its own context.

export const communicationMessages = pgTable("communication_messages", {
  id:                  varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  channel:             varchar("channel").notNull(),              // commChannelEnum
  provider:            varchar("provider"),                       // commProviderEnum
  direction:           varchar("direction").notNull().default("outbound"),
  status:              varchar("status").notNull().default("queued"),
  fromIdentity:        varchar("from_identity"),                  // e.g. inbox ID, email address
  subject:             varchar("subject"),                        // nullable — email only
  body:                text("body").notNull(),
  relatedModule:       varchar("related_module"),                 // e.g. assigned_drivers, scheduling
  relatedEntityType:   varchar("related_entity_type"),            // e.g. driver, account, shift, move, claim
  relatedEntityId:     varchar("related_entity_id"),
  createdByUserId:     varchar("created_by_user_id"),
  sentAt:              timestamp("sent_at",       { withTimezone: true }),
  providerMessageId:   varchar("provider_message_id"),
  providerRawResponse: jsonb("provider_raw_response"),
  errorMessage:        text("error_message"),
  createdAt:           timestamp("created_at",   { withTimezone: true }).default(sql`now()`),
  updatedAt:           timestamp("updated_at",   { withTimezone: true }).default(sql`now()`),
});

export const insertCommunicationMessageSchema = createInsertSchema(communicationMessages).omit({
  id: true, createdAt: true, updatedAt: true,
});
export type CommunicationMessage       = typeof communicationMessages.$inferSelect;
export type InsertCommunicationMessage = z.infer<typeof insertCommunicationMessageSchema>;

// ── communication_recipients ─────────────────────────────────────────────────
// One record per recipient per communication_message.
// Tracks individual delivery outcome and exclusion reasons so any
// module can query per-person delivery history later.

export const communicationRecipients = pgTable("communication_recipients", {
  id:                      varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  communicationMessageId:  varchar("communication_message_id").notNull(),
  recipientType:           varchar("recipient_type").notNull().default("unknown"),
  recipientId:             varchar("recipient_id"),               // FK to driver/employee/contact
  destinationRaw:          varchar("destination_raw"),            // phone or email as entered
  destinationNormalized:   varchar("destination_normalized"),     // E.164 or normalised email
  deliveryStatus:          varchar("delivery_status").notNull().default("pending"),
  excluded:                boolean("excluded").notNull().default(false),
  excludedReason:          varchar("excluded_reason"),            // missing_phone | opted_out | bad_format | …
  providerMessageId:       varchar("provider_message_id"),        // per-recipient ID if provider supports it
  deliveredAt:             timestamp("delivered_at",  { withTimezone: true }),
  failedAt:                timestamp("failed_at",     { withTimezone: true }),
  errorMessage:            text("error_message"),
  createdAt:               timestamp("created_at",    { withTimezone: true }).default(sql`now()`),
});

export const insertCommunicationRecipientSchema = createInsertSchema(communicationRecipients).omit({
  id: true, createdAt: true,
});
export type CommunicationRecipient       = typeof communicationRecipients.$inferSelect;
export type InsertCommunicationRecipient = z.infer<typeof insertCommunicationRecipientSchema>;

// ── heymarket_user_mappings ───────────────────────────────────────────────────
// Maps DriverHub users to their Heymarket member identity.
// Email is the primary matching key for auto-sync; manual overrides are also supported.
// For 1:1 outbound SMS, the mapped heymarket_user_id is passed as creator_id so the
// message appears in Heymarket attributed to the correct team member / signature.

export const heymarketUserMappings = pgTable("heymarket_user_mappings", {
  id:                serial("id").primaryKey(),
  driverHubUserId:   text("driverhub_user_id").notNull().unique(),   // FK to users.id
  heymarketUserId:   integer("heymarket_user_id").notNull(),          // Heymarket member/creator numeric ID
  heymarketEmail:    text("heymarket_email"),                         // email used to establish the match
  heymarketName:     text("heymarket_name"),                          // display name in Heymarket
  matchedBy:         text("matched_by").notNull().default("email"),   // 'email' | 'manual'
  createdAt:         timestamp("created_at").defaultNow().notNull(),
  updatedAt:         timestamp("updated_at").defaultNow().notNull(),
});

export const insertHeymarketUserMappingSchema = createInsertSchema(heymarketUserMappings).omit({
  id: true, createdAt: true, updatedAt: true,
});
export type HeymarketUserMapping       = typeof heymarketUserMappings.$inferSelect;
export type InsertHeymarketUserMapping = z.infer<typeof insertHeymarketUserMappingSchema>;

// ── custom_reports ───────────────────────────────────────────────────────────
// Saved / scheduled custom report definitions.

export const customReports = pgTable("custom_reports", {
  id:              varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name:            varchar("name").notNull(),
  description:     text("description"),
  subject:         varchar("subject"),               // Drivers | Moves | Invoices | Accounts | Payroll | General
  isPublic:        boolean("is_public").notNull().default(false),
  isSystem:        boolean("is_system").notNull().default(false),
  config:          jsonb("config"),                  // arbitrary report config JSON
  ownerId:         varchar("owner_id").notNull(),    // FK → users.id
  ownerName:       varchar("owner_name"),            // denormalised display name
  lastRunAt:       timestamp("last_run_at",  { withTimezone: true }),
  scheduledCron:   varchar("scheduled_cron"),        // null = not scheduled
  scheduleEnabled: boolean("schedule_enabled").notNull().default(false),
  nextRunAt:       timestamp("next_run_at",  { withTimezone: true }),
  createdAt:       timestamp("created_at",   { withTimezone: true }).default(sql`now()`),
  updatedAt:       timestamp("updated_at",   { withTimezone: true }).default(sql`now()`),
});

export const insertCustomReportSchema = createInsertSchema(customReports).omit({
  id: true, createdAt: true, updatedAt: true,
});
export type CustomReport       = typeof customReports.$inferSelect;
export type InsertCustomReport = z.infer<typeof insertCustomReportSchema>;

// ── report_favorites ─────────────────────────────────────────────────────────
