// ═══════════════════════════════════════════════════════════════════════════════
// ACCOUNT REPORT CAMPAIGNS
// ═══════════════════════════════════════════════════════════════════════════════

// ── account_report_campaigns ─────────────────────────────────────────────────
// A campaign defines a report type, sender mailbox, delivery schedule, and a
// set of target accounts. Structure only — no scheduling engine yet.

export const accountReportCampaigns = pgTable("account_report_campaigns", {
  id:              varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  campaignName:    varchar("campaign_name", { length: 255 }).notNull(),
  reportType:      varchar("report_type",   { length: 100 }).notNull(),  // e.g. WEEKLY_ACCOUNT_SCHEDULE
  senderProfile:   varchar("sender_profile",{ length: 50  }).notNull(),  // Reports | Data | Support | Dispatch | Recruiting
  status:          varchar("status",        { length: 20  }).notNull().default("active"),   // active | paused | disabled
  scheduleType:    varchar("schedule_type", { length: 20  }).notNull().default("manual"),  // manual | weekly | monthly
  scheduleDay:     varchar("schedule_day",  { length: 20  }),            // Monday…Sunday (optional)
  scheduleTime:    varchar("schedule_time", { length: 8   }),            // HH:MM UTC (optional, stored as text for simplicity)
  timezone:        varchar("timezone",      { length: 100 }).notNull().default("America/New_York"),
  createdByUserId: varchar("created_by_user_id"),
  createdAt:       timestamp("created_at", { withTimezone: true }).notNull().default(sql`now()`),
  updatedAt:       timestamp("updated_at", { withTimezone: true }).notNull().default(sql`now()`),
});

export const insertAccountReportCampaignSchema = createInsertSchema(accountReportCampaigns).omit({
  id: true, createdAt: true, updatedAt: true,
});
export type AccountReportCampaign       = typeof accountReportCampaigns.$inferSelect;
export type InsertAccountReportCampaign = z.infer<typeof insertAccountReportCampaignSchema>;

// ── account_report_campaign_accounts ─────────────────────────────────────────
// Many-to-many mapping: which accounts are targeted by a campaign.

export const accountReportCampaignAccounts = pgTable("account_report_campaign_accounts", {
  id:         varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  campaignId: varchar("campaign_id").notNull().references(() => accountReportCampaigns.id, { onDelete: "cascade" }),
  accountId:  varchar("account_id").notNull().references(() => customers.id, { onDelete: "cascade" }),
  createdAt:  timestamp("created_at", { withTimezone: true }).notNull().default(sql`now()`),
}, (table) => ({
  campaignAccountIdx: index("arc_accounts_campaign_idx").on(table.campaignId),
  accountIdx:         index("arc_accounts_account_idx").on(table.accountId),
}));

export const insertAccountReportCampaignAccountSchema = createInsertSchema(accountReportCampaignAccounts).omit({
  id: true, createdAt: true,
});
export type AccountReportCampaignAccount       = typeof accountReportCampaignAccounts.$inferSelect;
export type InsertAccountReportCampaignAccount = z.infer<typeof insertAccountReportCampaignAccountSchema>;

// ── account_report_campaign_recipients ───────────────────────────────────────
// Per-account recipients within a campaign. Different accounts can have
// different recipient lists.

export const accountReportCampaignRecipients = pgTable("account_report_campaign_recipients", {
  id:         varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  campaignId: varchar("campaign_id").notNull().references(() => accountReportCampaigns.id, { onDelete: "cascade" }),
  accountId:  varchar("account_id").notNull().references(() => customers.id, { onDelete: "cascade" }),
  email:      varchar("email", { length: 255 }).notNull(),
  name:       varchar("name",  { length: 255 }),
  createdAt:  timestamp("created_at", { withTimezone: true }).notNull().default(sql`now()`),
}, (table) => ({
  campaignIdx: index("arc_recipients_campaign_idx").on(table.campaignId),
  accountIdx:  index("arc_recipients_account_idx").on(table.accountId),
}));

export const insertAccountReportCampaignRecipientSchema = createInsertSchema(accountReportCampaignRecipients).omit({
  id: true, createdAt: true,
});
export type AccountReportCampaignRecipient       = typeof accountReportCampaignRecipients.$inferSelect;
export type InsertAccountReportCampaignRecipient = z.infer<typeof insertAccountReportCampaignRecipientSchema>;

// ── account_report_campaign_runs ─────────────────────────────────────────────
// Tracks each execution of a campaign (manual or automated). Structure only.

export const accountReportCampaignRuns = pgTable("account_report_campaign_runs", {
  id:             varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  campaignId:     varchar("campaign_id").notNull().references(() => accountReportCampaigns.id, { onDelete: "cascade" }),
  runType:        varchar("run_type",  { length: 20 }).notNull(), // manual | automated
  status:         varchar("status",   { length: 20 }).notNull().default("pending"),
                                                                  // pending | sending | completed | failed | blocked
  totalAccounts:  integer("total_accounts").notNull().default(0),
  deliveredCount: integer("delivered_count").notNull().default(0),
  failedCount:    integer("failed_count").notNull().default(0),
  notSentCount:   integer("not_sent_count").notNull().default(0),
  startedAt:      timestamp("started_at",   { withTimezone: true }),
  completedAt:    timestamp("completed_at", { withTimezone: true }),
  createdAt:      timestamp("created_at",   { withTimezone: true }).notNull().default(sql`now()`),
}, (table) => ({
  campaignIdx: index("arc_runs_campaign_idx").on(table.campaignId),
  statusIdx:   index("arc_runs_status_idx").on(table.status),
}));

export const insertAccountReportCampaignRunSchema = createInsertSchema(accountReportCampaignRuns).omit({
  id: true, createdAt: true,
});
export type AccountReportCampaignRun       = typeof accountReportCampaignRuns.$inferSelect;
export type InsertAccountReportCampaignRun = z.infer<typeof insertAccountReportCampaignRunSchema>;

// ── account_report_run_deliveries ────────────────────────────────────────────
// Account-level delivery record for a single campaign run.
// Supports Delivered / Failed / Not Sent tracking per account.

export const accountReportRunDeliveries = pgTable("account_report_run_deliveries", {
  id:                varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  runId:             varchar("run_id").notNull().references(() => accountReportCampaignRuns.id, { onDelete: "cascade" }),
  accountId:         varchar("account_id").notNull().references(() => customers.id, { onDelete: "cascade" }),
  status:            varchar("status",             { length: 20  }).notNull(),
                                                                     // delivered | failed | not_sent | blocked
  recipientEmail:    varchar("recipient_email",    { length: 255 }),
  recipientName:     varchar("recipient_name",     { length: 255 }),
  sentAt:            timestamp("sent_at",          { withTimezone: true }),
  errorMessage:      text("error_message"),
  failureType:       varchar("failure_type",       { length: 50  }),
                                                                     // invalid_email | mailbox_not_found | bounced | blocked | graph_error | no_recipient | unknown
  providerMessageId: varchar("provider_message_id",{ length: 255 }),
  opened:            boolean("opened").default(false),
  firstOpenedAt:     timestamp("first_opened_at",  { withTimezone: true }),
  lastOpenedAt:      timestamp("last_opened_at",   { withTimezone: true }),
  openCount:         integer("open_count").default(0),
  createdAt:         timestamp("created_at",       { withTimezone: true }).notNull().default(sql`now()`),
}, (table) => ({
  runIdx:     index("ard_deliveries_run_idx").on(table.runId),
  accountIdx: index("ard_deliveries_account_idx").on(table.accountId),
  statusIdx:  index("ard_deliveries_status_idx").on(table.status),
}));

export const insertAccountReportRunDeliverySchema = createInsertSchema(accountReportRunDeliveries).omit({
  id: true, createdAt: true,
});
export type AccountReportRunDelivery       = typeof accountReportRunDeliveries.$inferSelect;
export type InsertAccountReportRunDelivery = z.infer<typeof insertAccountReportRunDeliverySchema>;

