// ─────────────────────────────────────────────────────────────────────────────
// FINANCE MODULE PERMISSIONS
// Explicit per-user grants. No role inherits Finance access automatically.
// Only a super_user can grant/revoke. All columns default false.
// ─────────────────────────────────────────────────────────────────────────────

export const financePermissions = pgTable("finance_permissions", {
  id:               varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId:           varchar("user_id").notNull().unique().references(() => users.id, { onDelete: "cascade" }),

  // Gate columns — ALL default false
  canViewModule:    boolean("can_view_module").notNull().default(false),
                    // Master switch — must be true for any Finance access
  canViewDashboard: boolean("can_view_dashboard").notNull().default(false),
  canViewRevenue:   boolean("can_view_revenue").notNull().default(false),
  canViewExpenses:  boolean("can_view_expenses").notNull().default(false),
  canViewMargin:    boolean("can_view_margin").notNull().default(false),
  canExport:        boolean("can_export").notNull().default(false),
  canManageQbSync:  boolean("can_manage_qb_sync").notNull().default(false),
                    // Required for: Run Sync, Retry, Resolve Exceptions
  canManageProducts: boolean("can_manage_products").notNull().default(false),
                    // Required for Product Library create, edit, and delete actions

  // Audit
  grantedBy:        varchar("granted_by").references(() => users.id, { onDelete: "set null" }),
  grantedAt:        timestamp("granted_at").defaultNow(),
  updatedBy:        varchar("updated_by").references(() => users.id, { onDelete: "set null" }),
  updatedAt:        timestamp("updated_at").defaultNow(),
}, (table) => ({
  userIdx: index("finance_perms_user_idx").on(table.userId),
}));

export const insertFinancePermissionsSchema = createInsertSchema(financePermissions).omit({
  id: true, grantedAt: true, updatedAt: true,
});
export type FinancePermission = typeof financePermissions.$inferSelect;
export type InsertFinancePermission = z.infer<typeof insertFinancePermissionsSchema>;

// ─────────────────────────────────────────────────────────────────────────────
// FINANCE DATA ARCHITECTURE — Phase 1 (QB read-only local mirror)
// QuickBooks is the system of record. DriverHub is reporting/analytics only.
// All records retain original QB identifiers and are immutable from QB's side.
// ─────────────────────────────────────────────────────────────────────────────

// ── QB Customer reference list ────────────────────────────────────────────────
// Pulled from QB — used for AR transaction linkage and DH account mapping.

export const qboCustomers = pgTable("qbo_customers", {
  id:                varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // QB identifiers — retained as-is, never modified
  qboCustomerId:     varchar("qbo_customer_id",   { length: 100 }).notNull().unique(),
  qboSyncToken:      varchar("qbo_sync_token",    { length: 50  }),  // QB optimistic lock token
  displayName:       varchar("display_name",      { length: 500 }).notNull(),
  companyName:       varchar("company_name",      { length: 500 }),
  firstName:         varchar("first_name",        { length: 255 }),
  lastName:          varchar("last_name",         { length: 255 }),
  email:             varchar("email",             { length: 255 }),
  phone:             varchar("phone",             { length: 50  }),
  // Billing address
  billAddrLine1:     varchar("bill_addr_line1",   { length: 500 }),
  billAddrCity:      varchar("bill_addr_city",    { length: 255 }),
  billAddrState:     varchar("bill_addr_state",   { length: 100 }),
  billAddrZip:       varchar("bill_addr_zip",     { length: 20  }),
  // QB state
  isActive:          boolean("is_active").default(true),
  balance:           decimal("balance",           { precision: 14, scale: 2 }),
  balanceWithJobs:   decimal("balance_with_jobs", { precision: 14, scale: 2 }),
  // DH mapping
  dhAccountId:       varchar("dh_account_id").references(() => customers.id, { onDelete: "set null" }),
  mappingStatus:     varchar("mapping_status", { length: 20 }).default("unmapped"),
                     // 'unmapped' | 'mapped' | 'excluded' | 'review'
  mappingNote:       text("mapping_note"),
  mappedBy:          varchar("mapped_by").references(() => users.id, { onDelete: "set null" }),
  mappedAt:          timestamp("mapped_at"),
  // Sync audit
  sourceSystem:      varchar("source_system", { length: 50 }).default("quickbooks"),
  syncStatus:        varchar("sync_status",   { length: 20 }).default("ok"),
                     // 'ok' | 'failed' | 'stale' | 'excluded'
  qboLastModifiedAt: timestamp("qbo_last_modified_at"),
  lastSyncAt:        timestamp("last_sync_at").defaultNow(),
  syncRunId:         varchar("sync_run_id").references(() => qboSyncRuns.id),
  qboRealmId:        varchar("qbo_realm_id", { length: 100 }), // QB company realm ID (multi-entity future)
  createdAt:         timestamp("created_at").defaultNow(),
  updatedAt:         timestamp("updated_at").defaultNow(),
}, (table) => ({
  displayNameIdx:  index("qbo_cust_name_idx").on(table.displayName),
  mappingIdx:      index("qbo_cust_mapping_idx").on(table.mappingStatus),
  dhAccountIdx:    index("qbo_cust_dh_account_idx").on(table.dhAccountId),
}));
export const insertQboCustomerSchema = createInsertSchema(qboCustomers).omit({ id: true, createdAt: true, updatedAt: true });
export type QboCustomer = typeof qboCustomers.$inferSelect;
export type InsertQboCustomer = z.infer<typeof insertQboCustomerSchema>;

// ── QB AR transactions — invoices, payments, credit memos, refunds ────────────
// Revenue-side transactions pulled from QB. Retained read-only.

export const qboArTransactions = pgTable("qbo_ar_transactions", {
  id:                varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  // QB identifiers — never modified after import
  qboTxnId:          varchar("qbo_txn_id",   { length: 100 }).notNull(),
  qboTxnType:        varchar("qbo_txn_type", { length: 50  }).notNull(),
                     // 'Invoice' | 'Payment' | 'CreditMemo' | 'RefundReceipt' | 'SalesReceipt'
  qboSyncToken:      varchar("qbo_sync_token", { length: 50 }),
  qboDocNumber:      varchar("qbo_doc_number", { length: 100 }),   // RefNumber in QB
  qboRefNumber:      varchar("qbo_ref_number", { length: 100 }),   // QB's RefNumber field
  // Dates
  txnDate:           date("txn_date").notNull(),
  dueDate:           date("due_date"),
  // Customer
  qboCustomerId:     varchar("qbo_customer_id",   { length: 100 }),
  customerName:      varchar("customer_name",     { length: 500 }),
  customerRef:       varchar("customer_ref",      { length: 100 }),  // QB CustomerRef.value
  // Amounts
  totalAmount:       decimal("total_amount",      { precision: 14, scale: 2 }).notNull(),
  balance:           decimal("balance",           { precision: 14, scale: 2 }),
                     // Remaining unpaid balance (for invoices)
  taxAmount:         decimal("tax_amount",        { precision: 14, scale: 2 }),
  // Status
  txnStatus:         varchar("txn_status",        { length: 50 }),
                     // 'Voided' | 'Deleted' | 'Draft' | 'Pending' | 'Synchronized' etc.
  isPaid:            boolean("is_paid").default(false),
  isVoided:          boolean("is_voided").default(false),
  // Applied payments/credits (for invoices)
  linkedTxnIds:      text("linked_txn_ids").array(),  // QB LinkedTxn refs
  // Description
  memo:              text("memo"),
  privateNote:       text("private_note"),
  // Classification
  className:         varchar("class_name",    { length: 255 }),
  departmentName:    varchar("department_name", { length: 255 }),
  // DH linkage
  dhAccountId:       varchar("dh_account_id").references(() => customers.id, { onDelete: "set null" }),
  dhInvoiceId:       varchar("dh_invoice_id"),  // DriverHub invoice if matched
  // Raw payload (immutable QB source)
  rawPayload:        jsonb("raw_payload"),
  // Sync audit
  sourceSystem:      varchar("source_system",      { length: 50  }).default("quickbooks"),
  syncStatus:        varchar("sync_status",         { length: 20  }).default("ok"),
  qboLastModifiedAt: timestamp("qbo_last_modified_at"),
  lastSyncAt:        timestamp("last_sync_at").defaultNow(),
  syncRunId:         varchar("sync_run_id").references(() => qboSyncRuns.id),
  qboRealmId:        varchar("qbo_realm_id", { length: 100 }), // QB company realm ID (multi-entity future)
  createdAt:         timestamp("created_at").defaultNow(),
  updatedAt:         timestamp("updated_at").defaultNow(),
}, (table) => ({
  uniqueTxn:      uniqueIndex("qbo_ar_unique_txn_idx").on(table.qboTxnId, table.qboTxnType),
  txnTypeIdx:     index("qbo_ar_txn_type_idx").on(table.qboTxnType),
  txnDateIdx:     index("qbo_ar_txn_date_idx").on(table.txnDate),
  customerIdx:    index("qbo_ar_customer_idx").on(table.qboCustomerId),
  dhAccountIdx:   index("qbo_ar_dh_account_idx").on(table.dhAccountId),
  syncStatusIdx:  index("qbo_ar_sync_status_idx").on(table.syncStatus),
}));
export const insertQboArTransactionSchema = createInsertSchema(qboArTransactions).omit({ id: true, createdAt: true, updatedAt: true });
export type QboArTransaction = typeof qboArTransactions.$inferSelect;
export type InsertQboArTransaction = z.infer<typeof insertQboArTransactionSchema>;

// ── QB AR transaction line items ──────────────────────────────────────────────

